  useEffect(() => {
    if (diet) {
      reset({
        name: diet.name,
        description: diet.description || "",
        iconName: diet.iconName || "Leaf",
        isActive: diet.isActive,
        excludedIngredientIds: diet.excludedIngredients?.map((i: any) => i.id) || [],
        excludedCategoryIds: diet.excludedCategories?.map((c: any) => c.id) || [],
