                <div className="absolute top-[50%] -left-[100px] w-[200px] h-[200px] bg-green-500/10 rounded-full blur-[60px]" />
              </div>

              <div className="relative p-6 pb-4 border-b border-white/10 dark:border-white/5">
                <DialogHeader>
