                    />
                    {errors.name && (
                      <motion.p initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} className="text-xs text-destructive font-semibold flex items-center gap-1 mt-1">
                        <AlertCircle className="w-3 h-3" /> {errors.name.message}
                      </motion.p>
