import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, ShoppingCart, Check } from "lucide-react";
import type { IngredientResponse } from "@/entities/recipe/api/recipeApi";
import { MeasurementUnit, MeasurementCategory, MEASUREMENT_UNIT_LABELS, MEASUREMENT_CATEGORY_UNITS } from "@/shared/constants/measurement";

export interface RestockItem {
  ingredientId: string;
  quantity: number;
  unit: number;
}

interface PostCookDepletedModalProps {
  isOpen: boolean;
  onClose: () => void;
  depletedIngredients: IngredientResponse[];
  onSync: (items: RestockItem[]) => void;
  isSyncing: boolean;
}

export const PostCookDepletedModal = ({ isOpen, onClose, depletedIngredients, onSync, isSyncing }: PostCookDepletedModalProps) => {
  const [itemsData, setItemsData] = useState<Record<string, { selected: boolean; quantity: number | string; unit: number }>>({});

  useEffect(() => {
    if (isOpen) {
      const initial: Record<string, { selected: boolean; quantity: number; unit: number }> = {};
      depletedIngredients.forEach(item => {
        let defaultQuantity = 1;
        let defaultUnit = MeasurementUnit.Piece;
        
        let familyVal = item.unitFamily as unknown as number;
        if (typeof item.unitFamily === 'string') {
          familyVal = MeasurementCategory[item.unitFamily as keyof typeof MeasurementCategory] as number;
        }
        
        if (familyVal === MeasurementCategory.Weight) {
          defaultQuantity = 250;
          defaultUnit = MeasurementUnit.Gram;
        } else if (familyVal === MeasurementCategory.Volume) {
          defaultQuantity = 500;
          defaultUnit = MeasurementUnit.Milliliter;
        }

        initial[item.id] = {
          selected: true,
          quantity: defaultQuantity,
          unit: defaultUnit
        };
      });
      setItemsData(initial);
    }
  }, [isOpen, depletedIngredients]);

  if (!isOpen) return null;

  const handleToggle = (id: string) => {
    setItemsData(prev => ({
      ...prev,
      [id]: {
        ...prev[id],
        selected: !prev[id].selected
      }
    }));
  };

  const handleQuantityChange = (id: string, value: string) => {
    const num = parseFloat(value);
    if (!isNaN(num) && num > 0) {
      setItemsData(prev => ({
        ...prev,
        [id]: { ...prev[id], quantity: num }
      }));
    } else if (value === '') {
      setItemsData(prev => ({
        ...prev,
        [id]: { ...prev[id], quantity: '' }
      }));
    }
  };

  const handleUnitChange = (id: string, value: string) => {
    setItemsData(prev => ({
      ...prev,
      [id]: { ...prev[id], unit: parseInt(value, 10) }
    }));
  };

  const handleSync = () => {
    const itemsToSync: RestockItem[] = Object.entries(itemsData)
      .filter(([_, data]) => data.selected && typeof data.quantity === 'number' && data.quantity > 0)
      .map(([id, data]) => ({
        ingredientId: id,
        quantity: data.quantity as number,
        unit: data.unit
      }));
      
    onSync(itemsToSync);
  };
  
  const hasSelected = Object.values(itemsData).some(d => d.selected);

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={!isSyncing ? onClose : undefined}
          className="fixed inset-0 bg-black/60 backdrop-blur-sm"
        />

        <motion.div 
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          className="relative w-full max-w-2xl bg-card rounded-[2rem] shadow-2xl overflow-hidden flex flex-col"
        >
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-border/50 bg-emerald-500/5">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-full bg-emerald-500/20 flex items-center justify-center">
                <ShoppingCart className="w-6 h-6 text-emerald-600 dark:text-emerald-400" />
              </div>
              <div>
                <h3 className="font-black text-foreground text-xl">Biten Malzemeler</h3>
                <p className="text-sm text-muted-foreground font-medium">Alışveriş listenize ekleyelim mi?</p>
              </div>
            </div>
            {!isSyncing && (
              <button 
                onClick={onClose}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-muted/50 text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>

          {/* Body */}
          <div className="p-6 overflow-y-auto max-h-[60vh]">
            <p className="text-sm text-foreground/80 leading-relaxed mb-6">
              Bu tarifi pişirdikten sonra dolabınızdaki bazı malzemelerin stokları <strong className="text-foreground">sıfırlandı</strong>. Miktarlarını dilediğiniz gibi düzenleyerek alışveriş listenize ekleyebilirsiniz.
            </p>

            <div className="space-y-3">
              {depletedIngredients.map(item => {
                let familyVal = item.unitFamily as unknown as number;
                if (typeof item.unitFamily === 'string') {
                  familyVal = MeasurementCategory[item.unitFamily as keyof typeof MeasurementCategory] as number;
                }

                const data = itemsData[item.id] || { selected: false, quantity: 1, unit: MeasurementUnit.Piece };
                const availableUnits = MEASUREMENT_CATEGORY_UNITS[familyVal as MeasurementCategory] || [MeasurementUnit.Piece];

                return (
                  <div 
                    key={item.id} 
                    className={`flex flex-col sm:flex-row sm:items-center gap-4 p-4 rounded-2xl border transition-all ${
                      data.selected 
                        ? 'bg-primary/5 border-primary/30' 
                        : 'bg-muted/30 border-border/50'
                    }`}
                  >
                    <div 
                      className="flex items-center gap-4 cursor-pointer flex-1"
                      onClick={() => handleToggle(item.id)}
                    >
                      <div className={`w-6 h-6 rounded-md flex items-center justify-center border transition-colors flex-shrink-0 ${
                        data.selected
                          ? 'bg-primary border-primary text-primary-foreground'
                          : 'bg-background border-border'
                      }`}>
                        {data.selected && <Check className="w-4 h-4" />}
                      </div>
                      
                      <div className="flex flex-col">
                        <span className={`font-bold text-base transition-colors ${data.selected ? 'text-foreground' : 'text-foreground/70'}`}>
                          {item.name}
                        </span>
                      </div>
                    </div>

                    <div className={`flex items-center gap-2 ${!data.selected ? 'opacity-50 pointer-events-none' : ''}`}>
                      <input 
                        type="number" 
                        min="0"
                        step="any"
                        value={data.quantity}
                        onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                        className="w-24 px-3 py-2 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/50 text-right font-medium"
                      />
                      <select
                        value={data.unit}
                        onChange={(e) => handleUnitChange(item.id, e.target.value)}
                        className="w-36 px-3 py-2 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/50 font-medium"
                      >
                        {availableUnits.map((u: MeasurementUnit) => (
                          <option key={u} value={u}>{MEASUREMENT_UNIT_LABELS[u]}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Footer */}
          <div className="p-6 border-t border-border/50 bg-muted/10 flex justify-end gap-3">
            <button
              onClick={onClose}
              disabled={isSyncing}
              className="px-6 py-3 rounded-xl text-sm font-bold bg-background border border-border hover:bg-muted text-foreground transition-colors disabled:opacity-50"
            >
              Atla
            </button>
            <button
              onClick={handleSync}
              disabled={isSyncing || !hasSelected}
              className="flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-bold bg-primary text-primary-foreground shadow-lg hover:bg-primary/90 transition-colors disabled:opacity-50"
            >
              {isSyncing ? "Ekleniyor..." : "Listeye Ekle"}
            </button>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  );
};

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, AlertCircle, ChefHat, ShoppingCart, Package, Loader2 } from "lucide-react";
import type { IngredientResponse, RecipeIngredientResponse } from "@/entities/recipe/api/recipeApi";
import { MEASUREMENT_UNIT_LABELS, MeasurementUnit } from "@/shared/constants/measurement";
import { shoppingListApi } from "@/entities/shopping-list/api/shoppingListApi";
import { pantryApi } from "@/entities/pantry/api/pantryApi";
import { toast } from "sonner";

interface PreCookSyncModalProps {
  isOpen: boolean;
  onClose: () => void;
  missingIngredients: IngredientResponse[];
  recipeIngredients: RecipeIngredientResponse[];
  onContinue: (ignoredIngredientIds: string[]) => void;
}

type ActionType = 'ignore' | 'shopping' | 'pantry';

export const PreCookSyncModal = ({ isOpen, onClose, missingIngredients, recipeIngredients, onContinue }: PreCookSyncModalProps) => {
  const [actions, setActions] = useState<Record<string, ActionType>>({});
  const [quantities, setQuantities] = useState<Record<string, number>>({});
  const [isSyncing, setIsSyncing] = useState(false);

  if (!isOpen) return null;

  const handleActionChange = (id: string, action: ActionType) => {
    setActions(prev => ({ ...prev, [id]: action }));
  };

  const handleQuantityChange = (id: string, val: string) => {
    setQuantities(prev => ({ ...prev, [id]: parseFloat(val) || 0 }));
  };

  const handleContinue = async () => {
    setIsSyncing(true);
    try {
      const shoppingListItems: any[] = [];
      const pantryItems: any[] = [];
      const ignoredIds: string[] = [];

      missingIngredients.forEach(item => {
        const action = actions[item.id] || 'ignore';
        const recipeIngredient = recipeIngredients.find(ri => ri.ingredientId === item.id);
        const quantity = quantities[item.id] !== undefined ? quantities[item.id] : (recipeIngredient?.amount || 1);
        
        if (action === 'ignore') {
          ignoredIds.push(item.id);
        } else if (action === 'shopping') {
          shoppingListItems.push({
            ingredientId: item.id,
            quantity: quantity,
            unit: recipeIngredient?.unitId || 1,
          });
          // Also ignore it so it doesn't crash the cooking deduction!
          ignoredIds.push(item.id);
        } else if (action === 'pantry') {
          pantryItems.push({
            ingredientId: item.id,
            quantity: quantity,
            unit: recipeIngredient?.unitId || 1,
          });
          // We DO NOT ignore it, because it is now in the pantry and should be deducted!
        }
      });

      if (shoppingListItems.length > 0) {
        await shoppingListApi.bulkAddItems({ items: shoppingListItems });
        toast.success(`${shoppingListItems.length} ürün alışveriş listesine eklendi.`);
      }
      
      if (pantryItems.length > 0) {
        await pantryApi.addMultipleIngredients({ ingredients: pantryItems });
        toast.success(`${pantryItems.length} ürün dolabınıza eklendi.`);
      }

      onContinue(ignoredIds);
    } catch (error) {
      toast.error("İşlem sırasında bir hata oluştu.");
      onContinue([]); // Proceed anyway if it fails
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={!isSyncing ? onClose : undefined}
          className="fixed inset-0 bg-black/60 backdrop-blur-sm"
        />

        <motion.div 
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          className="relative w-full max-w-lg bg-card rounded-[2rem] shadow-2xl overflow-hidden flex flex-col"
        >
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-border/50 bg-amber-500/5">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-full bg-amber-500/20 flex items-center justify-center">
                <AlertCircle className="w-6 h-6 text-amber-600 dark:text-amber-400" />
              </div>
              <div>
                <h3 className="font-black text-foreground text-xl">Eksik Malzemeler</h3>
                <p className="text-sm text-muted-foreground font-medium">Dolabınızda bu ürünler bulunmuyor</p>
              </div>
            </div>
            {!isSyncing && (
              <button 
                onClick={onClose}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-muted/50 text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>

          {/* Body */}
          <div className="p-6 overflow-y-auto max-h-[60vh]">
            <p className="text-sm text-foreground/80 leading-relaxed mb-6">
              Aşağıdaki malzemeler dijital dolabınızda bulunamadı. Lütfen eksik ürünler için bir aksiyon seçin:
            </p>

            <div className="space-y-3">
              {missingIngredients.map(item => {
                const recipeIngredient = recipeIngredients.find(ri => ri.ingredientId === item.id);
                const currentAction = actions[item.id] || 'ignore';
                const currentQuantity = quantities[item.id] !== undefined ? quantities[item.id] : (recipeIngredient?.amount || 1);
                
                const unitLabel = recipeIngredient ? MEASUREMENT_UNIT_LABELS[recipeIngredient.unitId as MeasurementUnit] || "birim" : "birim";
                const amountText = recipeIngredient ? `${recipeIngredient.amount} ${unitLabel}` : "Tarifte gerekli";

                return (
                  <div key={item.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 rounded-2xl bg-muted/30 border border-border/50 hover:bg-muted/50 transition-colors gap-3">
                    <div className="flex flex-col">
                      <span className="font-bold text-foreground text-base">{item.name}</span>
                      
                      {currentAction !== 'ignore' ? (
                        <div className="flex items-center gap-2 mt-1.5">
                          <input 
                            type="number" 
                            min="0.1" 
                            step="0.1"
                            value={currentQuantity}
                            onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                            className="w-16 px-2 py-1 text-xs font-bold bg-background border border-border rounded-md focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all text-foreground"
                          />
                          <span className="text-xs text-muted-foreground font-medium">{unitLabel}</span>
                        </div>
                      ) : (
                        <span className="text-xs text-muted-foreground font-medium mt-1">
                          {amountText}
                        </span>
                      )}
                    </div>
                    
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <button
                        onClick={() => handleActionChange(item.id, 'ignore')}
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1 border ${
                          currentAction === 'ignore' 
                            ? 'bg-amber-500/10 text-amber-600 border-amber-500/30 dark:text-amber-400' 
                            : 'bg-background hover:bg-muted text-foreground/70 border-transparent'
                        }`}
                        title="Sadece bu yemeğe kullanacağım, stoktan düşme"
                      >
                        <ChefHat className="w-3.5 h-3.5" /> Yoksay
                      </button>
                      <button
                        onClick={() => handleActionChange(item.id, 'shopping')}
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1 border ${
                          currentAction === 'shopping' 
                            ? 'bg-blue-500/10 text-blue-600 border-blue-500/30 dark:text-blue-400' 
                            : 'bg-background hover:bg-muted text-foreground/70 border-transparent'
                        }`}
                        title="Alışveriş listeme ekle"
                      >
                        <ShoppingCart className="w-3.5 h-3.5" /> Listeye Al
                      </button>
                      <button
                        onClick={() => handleActionChange(item.id, 'pantry')}
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1 border ${
                          currentAction === 'pantry' 
                            ? 'bg-emerald-500/10 text-emerald-600 border-emerald-500/30 dark:text-emerald-400' 
                            : 'bg-background hover:bg-muted text-foreground/70 border-transparent'
                        }`}
                        title="Dijital dolabıma ekle"
                      >
                        <Package className="w-3.5 h-3.5" /> Dolaba Ekle
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Footer */}
          <div className="p-6 border-t border-border/50 bg-muted/10 flex justify-end gap-3">
            <button
              onClick={onClose}
              disabled={isSyncing}
              className="px-6 py-3 rounded-xl text-sm font-bold bg-background border border-border hover:bg-muted text-foreground transition-colors disabled:opacity-50"
            >
              İptal
            </button>
            <button
              onClick={handleContinue}
              disabled={isSyncing}
              className="flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-bold bg-primary text-primary-foreground shadow-lg hover:bg-primary/90 transition-colors disabled:opacity-70"
            >
              {isSyncing ? <Loader2 className="w-4 h-4 animate-spin" /> : <ChefHat className="w-4 h-4" />}
              {isSyncing ? "İşleniyor..." : "Devam Et"}
            </button>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  );
};

import { toast } from "sonner";
import { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Save, X, ImagePlus, ChevronDown, Plus, GripVertical, Search, Loader2 } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useMutation, useQueryClient, useQuery } from "@tanstack/react-query";
import { recipeApi } from "@/entities/recipe/api/recipeApi";
import { pantryApi } from "@/entities/pantry/api/pantryApi";
import { useAdminRecipeCategories, useAdminTags } from "@/entities/admin-recipe-taxonomy/api/adminRecipeTaxonomyQueries";
import { 
  MeasurementCategory, 
  MEASUREMENT_CATEGORY_UNITS, 
  MEASUREMENT_UNIT_LABELS,
  ALL_UNITS,
  MeasurementUnit
} from "@/shared/constants/measurement";

interface IngredientInput {
  id: string;
  qty: string;
  unitId: string;
  ingredientId: string;
  name: string;
  unitFamily?: MeasurementCategory;
  isSearching: boolean;
  searchResults: any[];
  isPending?: boolean;
  suggestedCategoryId?: string;
}

interface StepInput {
  id: string;
  instruction: string;
  image?: File | null;
  imagePreview?: string | null;
}

const DIFFICULTIES = [
  { id: "1", name: "Kolay" },
  { id: "2", name: "Orta" },
  { id: "3", name: "Zor" },
];

export const CreateRecipeForm = () => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [coverPhoto, setCoverPhoto] = useState<File | null>(null);
  const [coverPhotoPreview, setCoverPhotoPreview] = useState<string | null>(null);

  const [selectedCategoryIds, setSelectedCategoryIds] = useState<number[]>([]);
  const [difficulty, setDifficulty] = useState("");
  const [servings, setServings] = useState("");
  const [prepTime, setPrepTime] = useState("");
  const [cookTime, setCookTime] = useState("");
  const [visibility, setVisibility] = useState("2"); // 1=Private, 2=Public
  
  const [selectedTagIds, setSelectedTagIds] = useState<number[]>([]);

  const [ingredients, setIngredients] = useState<IngredientInput[]>([
    { id: "1", qty: "", unitId: "", ingredientId: "", name: "", isSearching: false, searchResults: [] }
  ]);

  const [steps, setSteps] = useState<StepInput[]>([
    { id: "1", instruction: "" }
  ]);

  // Modal State
  const [showAddModal, setShowAddModal] = useState(false);
  const [pendingIngredientName, setPendingIngredientName] = useState("");
  const [pendingIngredientRowId, setPendingIngredientRowId] = useState("");
  const [newIngCategory, setNewIngCategory] = useState("");
  const [newIngUnit, setNewIngUnit] = useState<MeasurementUnit>(MeasurementUnit.Piece);

  // Fetch Pantry Categories (for new ingredient suggestions)
  const { data: pantryCategories = [] } = useQuery({
    queryKey: ["ingredient-categories"],
    queryFn: () => pantryApi.getCategories()
  });

  // Fetch Recipe Taxonomy
  const { data: recipeCategories = [] } = useAdminRecipeCategories();
  const { data: recipeTags = [] } = useAdminTags();

  const toggleCategory = (id: number) => {
    setSelectedCategoryIds(prev => {
      if (prev.includes(id)) return prev.filter(c => c !== id);
      if (prev.length >= 3) {
        toast.error("En fazla 3 kategori seçebilirsiniz.");
        return prev;
      }
      return [...prev, id];
    });
  };

  const toggleTag = (id: number) => {
    setSelectedTagIds(prev => {
      if (prev.includes(id)) return prev.filter(t => t !== id);
      if (prev.length >= 5) {
        toast.error("En fazla 5 etiket seçebilirsiniz.");
        return prev;
      }
      return [...prev, id];
    });
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setCoverPhoto(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setCoverPhotoPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };



  const addIngredient = () => {
    setIngredients(prev => [...prev, { id: Date.now().toString(), qty: "", unitId: "", ingredientId: "", name: "", isSearching: false, searchResults: [] }]);
  };

  const removeIngredient = (id: string) => {
    setIngredients(prev => {
      if (prev.length > 1) {
        return prev.filter(ing => ing.id !== id);
      }
      return prev;
    });
  };

  const updateIngredient = (id: string, field: keyof IngredientInput, value: any) => {
    setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, [field]: value } : ing));
  };

  // Ingredient Autocomplete Logic
  const handleIngredientSearch = async (id: string, keyword: string) => {
    setIngredients(prev => prev.map(ing => 
      ing.id === id ? { ...ing, name: keyword, ingredientId: "" } : ing
    ));
    
    if (keyword.length >= 2) {
      setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, isSearching: true } : ing));
      try {
        const results = await pantryApi.searchIngredients(keyword);
        setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, searchResults: results } : ing));
      } catch (error) {
        console.error("Search failed", error);
      } finally {
        setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, isSearching: false } : ing));
      }
    } else {
      setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, searchResults: [] } : ing));
    }
  };

  const handleSelectSearchResult = (id: string, result: any) => {
    setIngredients(prev => prev.map(ing => {
      if (ing.id === id) {
        const familyVal = typeof result.unitFamily === 'string' 
          ? MeasurementCategory[result.unitFamily as keyof typeof MeasurementCategory] 
          : result.unitFamily;

        return {
          ...ing,
          name: result.displayName,
          ingredientId: result.masterIngredientId,
          unitFamily: familyVal,
          searchResults: [], 
          unitId: MEASUREMENT_CATEGORY_UNITS[familyVal as MeasurementCategory]?.[0]?.toString() || ""
        };
      }
      return ing;
    }));
  };

  const handleAddNewIngredientClick = (id: string, name: string) => {
    setPendingIngredientRowId(id);
    setPendingIngredientName(name);
    setShowAddModal(true);
    updateIngredient(id, "searchResults", []); // Close dropdown
  };

  const handleAddNewIngredientConfirm = () => {
    if (!newIngCategory) return;
    
    setIngredients(prev => prev.map(ing => {
      if (ing.id === pendingIngredientRowId) {
        return {
          ...ing,
          name: pendingIngredientName,
          ingredientId: "",
          isPending: true,
          suggestedCategoryId: newIngCategory,
          unitId: newIngUnit.toString()
        };
      }
      return ing;
    }));
    
    setShowAddModal(false);
    setNewIngCategory("");
  };

  const addStep = () => {
    setSteps(prev => [...prev, { id: Date.now().toString(), instruction: "" }]);
  };

  const updateStep = (id: string, field: keyof StepInput, value: any) => {
    setSteps(prev => prev.map(step => step.id === id ? { ...step, [field]: value } : step));
  };

  const removeStep = (id: string) => {
    setSteps(prev => {
      if (prev.length > 1) {
        return prev.filter(step => step.id !== id);
      }
      return prev;
    });
  };

  const createMutation = useMutation({
    mutationFn: (formData: FormData) => recipeApi.createRecipe(formData),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["recipes"] });
      navigate("/home");
    },
    onError: (error: any) => {
      console.error("Failed to create recipe", error);
      const errorMessage = error.response?.data?.detail || error.response?.data?.message || "Tarif kaydedilirken bir hata oluştu. Lütfen tüm alanları doldurduğunuzdan emin olun.";
      toast.error(errorMessage);
    }
  });

  const handleSubmit = () => {
    if (!title.trim() || selectedCategoryIds.length === 0 || !coverPhoto) {
      toast.error("Lütfen Tarif Adı, en az bir Kategori ve Kapak Fotoğrafı alanlarını eksiksiz doldurun.");
      return;
    }

    if (!difficulty) {
      toast.error("Lütfen bir zorluk derecesi seçin.");
      return;
    }

    if (!servings || parseInt(servings) <= 0) {
      toast.error("Porsiyon 0'dan büyük olmalıdır.");
      return;
    }

    if (!prepTime || parseInt(prepTime) < 0 || !cookTime || parseInt(cookTime) < 0) {
      toast.error("Lütfen geçerli bir hazırlık ve pişirme süresi girin.");
      return;
    }

    const validIngredients = ingredients.filter(i => (i.ingredientId || i.isPending) && i.qty && i.unitId);
    if (validIngredients.length === 0) {
      toast.error("Lütfen en az bir geçerli malzeme ekleyin.");
      return;
    }

    const formData = new FormData();
    formData.append("Title", title);
    formData.append("Description", description);
    formData.append("Visibility", visibility); // "1" or "2"
    formData.append("Difficulty", difficulty); // "1", "2" or "3"
    formData.append("Servings", servings);
    formData.append("PrepTime", prepTime);
    formData.append("CookTime", cookTime);
    
    const uniqueCategoryIds = Array.from(new Set(selectedCategoryIds));
    const uniqueTagIds = Array.from(new Set(selectedTagIds));

    if (uniqueCategoryIds.length === 0 || uniqueCategoryIds.length > 3) {
      toast.error("En az 1, en fazla 3 kategori seçebilirsiniz.");
      return;
    }

    if (uniqueTagIds.length > 5) {
      toast.error("En fazla 5 etiket seçebilirsiniz.");
      return;
    }

    uniqueCategoryIds.forEach(id => {
      formData.append("CategoryIds", id.toString());
    });

    uniqueTagIds.forEach(id => {
      formData.append("TagIds", id.toString());
    });

    formData.append("MainImage", coverPhoto);

    const formattedIngredients = validIngredients.map(i => ({
      IngredientId: i.ingredientId || null,
      RequestedName: i.isPending ? i.name : null,
      SuggestedCategoryId: i.isPending ? i.suggestedCategoryId : null,
      Amount: parseFloat(i.qty) || 0,
      UnitId: parseInt(i.unitId) || 1
    }));
    formData.append("IngredientsJson", JSON.stringify(formattedIngredients));

    const formattedSteps = steps
      .filter(s => s.instruction.trim() !== "")
      .map((s, index) => ({
        StepNumber: index + 1,
        Instruction: s.instruction
      }));
    formData.append("StepsJson", JSON.stringify(formattedSteps));

    steps.filter(s => s.instruction.trim() !== "").forEach((s, index) => {
      const stepNum = index + 1;
      if (s.image) {
        formData.append("StepImages", s.image);
        formData.append("StepImageStepNumbers", stepNum.toString());
      }
    });

    createMutation.mutate(formData);
  };

  return (
    <div className="w-full max-w-7xl mx-auto flex flex-col min-h-screen">
      {/* Header Actions */}
      <div className="flex items-center justify-between mb-8 pb-4 border-b border-muted/20">
        <div className="flex items-center gap-2 text-sm text-muted-foreground font-medium">
          <span>Tarifler</span>
          <span>/</span>
          <span className="text-foreground">Yeni Tarif Oluştur</span>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => navigate(-1)}
            disabled={createMutation.isPending}
            className="px-6 py-2.5 rounded-xl font-bold text-foreground hover:bg-muted/50 transition-colors"
          >
            İptal
          </button>
          <button 
            onClick={handleSubmit}
            disabled={createMutation.isPending}
            className="px-6 py-2.5 rounded-xl font-bold bg-[#588157] hover:bg-[#3a5a39] text-white transition-colors flex items-center gap-2 shadow-lg shadow-[#588157]/20 disabled:opacity-50"
          >
            {createMutation.isPending ? <span className="animate-pulse">Kaydediliyor...</span> : <><Save className="w-4 h-4" /> Tarifi Kaydet</>}
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-8 lg:gap-12">
        {/* LEFT COLUMN: Basic Info & Meta */}
        <div className="flex-1 flex flex-col gap-8">
          
          {/* Title & Description */}
          <div className="flex flex-col gap-4">
            <input
              type="text"
              placeholder="Tarif Adı"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="text-4xl md:text-5xl font-black text-foreground/30 placeholder:text-foreground/30 focus:text-foreground bg-transparent border-none outline-none w-full transition-colors"
            />
            <textarea
              placeholder="Bu yemeğin hikayesini anlatın... (Örn. 'Büyükannemden bana kalan, pazar günlerinin vazgeçilmezi...')"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="text-lg text-muted-foreground placeholder:text-muted-foreground/50 bg-transparent border-none outline-none w-full resize-none min-h-[100px]"
            />
          </div>

          {/* Cover Photo Upload */}
          <div 
            onClick={() => fileInputRef.current?.click()}
            className={`w-full aspect-[4/3] md:aspect-[16/9] border-2 border-dashed rounded-3xl flex flex-col items-center justify-center cursor-pointer transition-all relative overflow-hidden group ${coverPhoto ? 'border-primary/50' : 'border-muted/40 hover:bg-muted/5 hover:border-primary/50'}`}
          >
            {coverPhotoPreview ? (
              <>
                <img src={coverPhotoPreview} alt="Cover" className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                  <span className="text-white font-bold">Fotoğrafı Değiştir</span>
                </div>
              </>
            ) : (
              <div className="flex flex-col items-center gap-3 text-muted-foreground group-hover:text-primary transition-colors">
                <div className="w-16 h-16 rounded-full bg-muted/20 group-hover:bg-primary/10 flex items-center justify-center transition-colors">
                  <ImagePlus className="w-8 h-8" />
                </div>
                <span className="font-bold text-foreground">Kapak Fotoğrafı Yükle</span>
                <span className="text-sm">PNG, JPG (Maks 10MB)</span>
              </div>
            )}
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/png, image/jpeg"
              onChange={handlePhotoUpload} 
            />
          </div>

          {/* Meta Information Cards */}
          <div className="flex flex-col gap-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Zorluk Derecesi</span>
                <div className="relative">
                  <select 
                    value={difficulty} 
                    onChange={(e) => setDifficulty(e.target.value)}
                    className="w-full bg-muted/40 border border-muted hover:border-primary/30 rounded-xl px-4 py-3 appearance-none font-medium text-foreground outline-none focus:border-primary/50 transition-colors"
                  >
                    <option value="" disabled className="text-foreground bg-neutral-50 dark:bg-neutral-900">Zorluk Seçin</option>
                    {DIFFICULTIES.map(d => <option key={d.id} value={d.id} className="text-foreground bg-neutral-50 dark:bg-neutral-900">{d.name}</option>)}
                  </select>
                  <ChevronDown className="w-4 h-4 text-muted-foreground absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none" />
                </div>
              </div>

              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Görünürlük</span>
                <div className="relative">
                  <select 
                    value={visibility} 
                    onChange={(e) => setVisibility(e.target.value)}
                    className="w-full bg-muted/40 border border-muted hover:border-primary/30 rounded-xl px-4 py-3 appearance-none font-medium text-foreground outline-none focus:border-primary/50 transition-colors"
                  >
                    <option value="2" className="text-foreground bg-neutral-50 dark:bg-neutral-900">Herkese Açık (Public)</option>
                    <option value="1" className="text-foreground bg-neutral-50 dark:bg-neutral-900">Sadece Ben (Private)</option>
                  </select>
                  <ChevronDown className="w-4 h-4 text-muted-foreground absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none" />
                </div>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Porsiyon</span>
                <div className="flex items-center gap-2 bg-muted/40 border border-muted rounded-xl px-4 py-3 focus-within:border-primary/50 transition-colors hover:border-primary/30">
                  <input type="number" 
                    value={servings} 
                    onChange={(e) => setServings(e.target.value)}
                    className="w-full bg-transparent font-medium text-foreground outline-none"
                    min="1"
                  />
                  <span className="text-muted-foreground text-sm">Kişilik</span>
                </div>
              </div>

              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Hazırlık</span>
                <div className="flex items-center gap-2 bg-muted/40 border border-muted rounded-xl px-4 py-3 focus-within:border-primary/50 transition-colors hover:border-primary/30">
                  <input type="number" 
                    value={prepTime} 
                    onChange={(e) => setPrepTime(e.target.value)}
                    className="w-full bg-transparent font-medium text-foreground outline-none"
                    min="0"
                  />
                  <span className="text-muted-foreground text-sm">Dk</span>
                </div>
              </div>

              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Pişirme</span>
                <div className="flex items-center gap-2 bg-muted/40 border border-muted rounded-xl px-4 py-3 focus-within:border-primary/50 transition-colors hover:border-primary/30">
                  <input type="number" 
                    value={cookTime} 
                    onChange={(e) => setCookTime(e.target.value)}
                    className="w-full bg-transparent font-medium text-foreground outline-none"
                    min="0"
                  />
                  <span className="text-muted-foreground text-sm">Dk</span>
                </div>
              </div>
            </div>

            <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col gap-3">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Kategoriler</span>
                <span className="text-xs font-bold text-primary">{selectedCategoryIds.length}/3 Seçildi</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {recipeCategories.map((cat: any) => {
                  const isSelected = selectedCategoryIds.includes(cat.id);
                  return (
                    <button
                      key={cat.id}
                      onClick={() => toggleCategory(cat.id)}
                      className={`px-4 py-2 rounded-xl text-sm font-bold border transition-all ${
                        isSelected 
                          ? 'bg-primary text-primary-foreground border-primary shadow-md' 
                          : 'bg-muted/40 dark:bg-neutral-800 text-muted-foreground border-muted/50 hover:border-primary/50'
                      }`}
                    >
                      {cat.name}
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col gap-3">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Etiketler</span>
                <span className="text-xs font-bold text-primary">{selectedTagIds.length}/5 Seçildi</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {recipeTags.map((tag: any) => {
                  const isSelected = selectedTagIds.includes(tag.id);
                  return (
                    <button
                      key={tag.id}
                      onClick={() => toggleTag(tag.id)}
                      className={`px-3 py-1.5 rounded-full text-sm font-bold border transition-all ${
                        isSelected 
                          ? 'bg-primary text-primary-foreground border-primary shadow-md' 
                          : 'bg-muted/40 dark:bg-neutral-800 text-muted-foreground border-muted/50 hover:border-primary/50'
                      }`}
                    >
                      # {tag.name}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Ingredients & Preparation */}
        <div className="flex-1 flex flex-col gap-6">
          
          <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-[2rem] p-6 md:p-8">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-muted/40 dark:bg-neutral-800 flex items-center justify-center shadow-sm border border-muted/20">
                  <span className="text-primary font-bold text-lg">⚖️</span>
                </div>
                <h3 className="text-2xl font-bold text-foreground">Malzemeler</h3>
              </div>
              <span className="text-sm font-bold text-muted-foreground">{ingredients.length} ADET</span>
            </div>

            <div className="flex flex-col gap-3">
              <div className="grid grid-cols-[auto_60px_100px_1fr_auto] gap-4 px-2 text-xs font-bold text-muted-foreground uppercase tracking-wider mb-1">
                <div className="w-6"></div>
                <div>Miktar</div>
                <div>Birim</div>
                <div>Malzeme (Arama)</div>
                <div className="w-6"></div>
              </div>

              {ingredients.map((ing) => {
                const allowedUnits = ing.unitFamily 
                  ? MEASUREMENT_CATEGORY_UNITS[ing.unitFamily] || ALL_UNITS
                  : ALL_UNITS;

                return (
                  <div key={ing.id} className="grid grid-cols-[auto_60px_100px_1fr_auto] gap-4 items-center bg-muted/40 dark:bg-neutral-800 p-2 rounded-xl shadow-sm border border-muted/10 group relative">
                    <div className="w-6 flex items-center justify-center text-muted-foreground/30 cursor-grab">
                      <GripVertical className="w-4 h-4" />
                    </div>
                    
                    <input 
                      type="number" 
                      value={ing.qty} 
                      onChange={(e) => updateIngredient(ing.id, "qty", e.target.value)}
                      className="w-full bg-transparent outline-none text-center font-medium placeholder:text-muted-foreground/30"
                      placeholder="1"
                    />
                    
                    <div className="relative">
                      <select 
                        value={ing.unitId} 
                        onChange={(e) => updateIngredient(ing.id, "unitId", e.target.value)}
                        className={`w-full bg-transparent outline-none text-sm font-medium appearance-none ${!ing.ingredientId && !ing.isPending ? 'opacity-50' : ''}`}
                        disabled={!ing.ingredientId && !ing.isPending}
                      >
                        <option value="" disabled className="text-foreground bg-neutral-50 dark:bg-neutral-900">Seç...</option>
                        {allowedUnits.map(unitVal => (
                          <option key={unitVal} value={unitVal} className="text-foreground bg-neutral-50 dark:bg-neutral-900">
                            {MEASUREMENT_UNIT_LABELS[unitVal as MeasurementUnit]}
                          </option>
                        ))}
                      </select>
                      <ChevronDown className="w-3 h-3 text-muted-foreground absolute right-1 top-1/2 -translate-y-1/2 pointer-events-none" />
                    </div>

                    <div className="relative w-full">
                      <input 
                        type="text" 
                        value={ing.name} 
                        onChange={(e) => handleIngredientSearch(ing.id, e.target.value)}
                        className={`w-full bg-transparent outline-none font-medium pr-8 ${ing.ingredientId ? 'text-primary' : ing.isPending ? 'text-orange-500' : 'text-foreground'}`}
                        placeholder="Malzeme ara..."
                        disabled={ing.isPending}
                      />
                      {ing.isSearching ? (
                        <Loader2 className="w-4 h-4 text-muted-foreground animate-spin absolute right-2 top-1/2 -translate-y-1/2" />
                      ) : (
                        <Search className="w-4 h-4 text-muted-foreground/50 absolute right-2 top-1/2 -translate-y-1/2" />
                      )}

                      <AnimatePresence>
                        {(ing.searchResults.length > 0 || (ing.name.length >= 2 && !ing.isSearching && !ing.ingredientId && !ing.isPending)) && (
                          <motion.div 
                            initial={{ opacity: 0, y: 5 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: 5 }}
                            className="absolute top-full left-0 right-0 mt-2 bg-muted/40 dark:bg-neutral-800 rounded-xl shadow-xl border border-muted/20 z-50 overflow-hidden max-h-56 overflow-y-auto"
                          >
                            {ing.searchResults.length > 0 ? (
                              ing.searchResults.map((result, idx) => (
                                <button
                                  key={idx}
                                  onClick={() => handleSelectSearchResult(ing.id, result)}
                                  className="w-full text-left px-4 py-3 hover:bg-primary/5 transition-colors border-b border-muted/10 last:border-0 flex items-center justify-between group"
                                >
                                  <span className="font-medium text-foreground group-hover:text-primary transition-colors">{result.displayName}</span>
                                  <span className="text-xs text-muted-foreground px-2 py-1 bg-muted/20 rounded-md">
                                    {result.categoryName}
                                  </span>
                                </button>
                              ))
                            ) : (
                              <div className="p-4 text-center">
                                <p className="text-sm text-muted-foreground mb-3">Aradığınız malzeme veritabanında bulunamadı.</p>
                                <button
                                  onClick={() => handleAddNewIngredientClick(ing.id, ing.name)}
                                  className="w-full bg-primary/10 hover:bg-primary/20 text-primary font-bold py-2.5 rounded-xl transition-colors flex items-center justify-center gap-2 text-sm shadow-sm"
                                >
                                  <Plus className="w-4 h-4" /> Yeni Ekle ve Öner
                                </button>
                              </div>
                            )}
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>

                    <button 
                      onClick={() => removeIngredient(ing.id)}
                      className="w-6 flex items-center justify-center text-muted-foreground/50 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                );
              })}

              <button 
                onClick={addIngredient}
                className="flex items-center gap-2 text-primary font-bold px-2 py-3 hover:bg-primary/5 rounded-xl transition-colors w-fit mt-2"
              >
                <Plus className="w-5 h-5" /> Malzeme Ekle
              </button>
            </div>
          </div>

          <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-[2rem] p-6 md:p-8">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-muted/40 dark:bg-neutral-800 flex items-center justify-center shadow-sm border border-muted/20">
                  <span className="text-primary font-bold text-lg">📖</span>
                </div>
                <h3 className="text-2xl font-bold text-foreground">Hazırlanışı</h3>
              </div>
              <span className="text-sm font-bold text-muted-foreground">{steps.length} ADIM</span>
            </div>

            <div className="flex flex-col gap-6 relative">
              <div className="absolute left-6 top-6 bottom-16 w-px bg-muted/20 z-0"></div>

              {steps.map((step, index) => (
                <div key={step.id} className="flex gap-6 relative z-10 group">
                  <div className="w-12 h-12 rounded-full bg-[#588157] text-white flex items-center justify-center font-black flex-shrink-0 shadow-md">
                    {index + 1}
                  </div>
                  <div className="flex-1 bg-muted/40 dark:bg-neutral-800 rounded-2xl p-5 shadow-sm border border-muted/10 relative">
                    <textarea 
                      value={step.instruction}
                      onChange={(e) => updateStep(step.id, "instruction", e.target.value)}
                      placeholder="Bu adımda ne yapılması gerektiğini açıklayın..."
                      className="w-full bg-transparent outline-none resize-none text-foreground leading-relaxed min-h-[60px]"
                    />
                    
                    <div className="mt-4 flex items-center gap-4">
                      <label className="flex items-center gap-2 cursor-pointer text-sm font-bold text-muted-foreground hover:text-primary transition-colors">
                        <ImagePlus className="w-4 h-4" />
                        {step.image ? "Fotoğrafı Değiştir" : "Fotoğraf Ekle (İsteğe Bağlı)"}
                        <input 
                          type="file" 
                          className="hidden" 
                          accept="image/png, image/jpeg"
                          onChange={(e) => {
                            const file = e.target.files?.[0];
                            if (file) {
                              updateStep(step.id, "image", file);
                              const reader = new FileReader();
                              reader.onloadend = () => {
                                updateStep(step.id, "imagePreview", reader.result as string);
                              };
                              reader.readAsDataURL(file);
                            }
                          }}
                        />
                      </label>
                      
                      {step.imagePreview && (
                        <div className="relative w-16 h-16 rounded-xl overflow-hidden border border-muted/20 shadow-sm">
                          <img src={step.imagePreview} alt={`Adım ${index + 1}`} className="w-full h-full object-cover" />
                          <button 
                            onClick={(e) => {
                              e.preventDefault();
                              updateStep(step.id, "image", null);
                              updateStep(step.id, "imagePreview", null);
                            }}
                            className="absolute top-1 right-1 w-5 h-5 bg-black/50 hover:bg-black/80 rounded-full flex items-center justify-center text-white transition-colors"
                          >
                            <X className="w-3 h-3" />
                          </button>
                        </div>
                      )}
                    </div>

                    {steps.length > 1 && (
                      <button 
                        onClick={() => removeStep(step.id)}
                        className="absolute -right-3 -top-3 w-8 h-8 rounded-full bg-muted/40 dark:bg-neutral-800 border border-muted/20 shadow-sm flex items-center justify-center text-muted-foreground hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>
              ))}

              <button 
                onClick={addStep}
                className="ml-18 bg-transparent border-2 border-dashed border-muted/40 text-muted-foreground font-bold hover:bg-muted/10 hover:text-foreground transition-colors py-4 rounded-2xl flex items-center justify-center gap-2 z-10"
                style={{ marginLeft: '4.5rem' }}
              >
                <Plus className="w-5 h-5" /> Adım Ekle
              </button>
            </div>
          </div>

        </div>
      </div>

      {/* Add New Ingredient Modal */}
      <AnimatePresence>
        {showAddModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <motion.div 
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              className="absolute inset-0 bg-black/40 backdrop-blur-sm"
              onClick={() => setShowAddModal(false)}
            />
            <motion.div 
              initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }}
              className="bg-card w-full max-w-md rounded-3xl shadow-2xl relative z-10 overflow-hidden"
            >
              <div className="p-6 border-b border-muted/20 flex items-center justify-between">
                <h3 className="font-black text-xl text-foreground">Yeni Malzeme Öner</h3>
                <button onClick={() => setShowAddModal(false)} className="text-muted-foreground hover:text-foreground">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <div className="p-6 flex flex-col gap-5">
                <p className="text-sm text-muted-foreground">
                  "<span className="font-bold text-foreground">{pendingIngredientName}</span>" sistemimizde bulunamadı. Yapay zeka onayına göndererek sisteme (ve dolabınıza) eklenmesini sağlayabilirsiniz.
                </p>
                
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-bold text-muted-foreground uppercase">Önerilen Kategori</label>
                  <select 
                    value={newIngCategory} 
                    onChange={(e) => setNewIngCategory(e.target.value)}
                    className="w-full bg-neutral-100 dark:bg-neutral-800 p-3 rounded-xl font-medium text-foreground outline-none border-none"
                  >
                    <option value="" disabled>Kategori Seçin</option>
                    {pantryCategories.map((c: any) => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>

                <div className="flex flex-col gap-2">
                  <label className="text-xs font-bold text-muted-foreground uppercase">Varsayılan Birim</label>
                  <select 
                    value={newIngUnit} 
                    onChange={(e) => setNewIngUnit(Number(e.target.value) as MeasurementUnit)}
                    className="w-full bg-neutral-100 dark:bg-neutral-800 p-3 rounded-xl font-medium text-foreground outline-none border-none"
                  >
                    {ALL_UNITS.map(unitVal => (
                      <option key={unitVal} value={unitVal}>
                        {MEASUREMENT_UNIT_LABELS[unitVal as MeasurementUnit]}
                      </option>
                    ))}
                  </select>
                </div>
                
                <div className="bg-orange-500/10 text-orange-600 dark:text-orange-400 p-4 rounded-xl text-sm font-medium border border-orange-500/20 mt-2">
                  <span className="font-bold">Not:</span> Bu malzeme onaya gönderilecek ve "Beklemede" olarak işaretlenecektir. Ancak tarife kaydedilebilecektir.
                </div>

                <button 
                  onClick={handleAddNewIngredientConfirm}
                  disabled={!newIngCategory}
                  className="w-full mt-2 bg-primary hover:bg-primary/90 text-primary-foreground font-bold py-3.5 rounded-xl transition-colors disabled:opacity-50"
                >
                  Onaya Gönder ve Tarife Ekle
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

    </div>
  );
};

import { toast } from "sonner";
import { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Save, X, ImagePlus, ChevronDown, Plus, GripVertical, Search, Loader2 } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useMutation, useQueryClient, useQuery } from "@tanstack/react-query";
import { recipeApi } from "@/entities/recipe/api/recipeApi";
import { pantryApi } from "@/entities/pantry/api/pantryApi";
import { useAdminRecipeCategories, useAdminTags } from "@/entities/admin-recipe-taxonomy/api/adminRecipeTaxonomyQueries";
import { 
  MeasurementCategory, 
  MEASUREMENT_CATEGORY_UNITS, 
  MEASUREMENT_UNIT_LABELS,
  ALL_UNITS,
  MeasurementUnit
} from "@/shared/constants/measurement";

interface IngredientInput {
  id: string;
  qty: string;
  unitId: string;
  ingredientId: string;
  name: string;
  unitFamily?: MeasurementCategory;
  isSearching: boolean;
  searchResults: any[];
  isPending?: boolean;
  suggestedCategoryId?: string;
}

interface StepInput {
  id: string;
  instruction: string;
  image?: File | null;
  imagePreview?: string | null;
}

const DIFFICULTIES = [
  { id: "1", name: "Kolay" },
  { id: "2", name: "Orta" },
  { id: "3", name: "Zor" },
];

import type { RecipeDetailResponse } from "@/entities/recipe/api/recipeApi";

export const EditRecipeForm = ({ initialData }: { initialData: RecipeDetailResponse }) => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [title, setTitle] = useState(initialData.title);
  const [description, setDescription] = useState(initialData.description);
  const [coverPhoto, setCoverPhoto] = useState<File | null>(null);
  const [coverPhotoPreview, setCoverPhotoPreview] = useState<string | null>(initialData.images?.find((i: any) => i.isMain)?.imageUrl || null);

  const difficultyMap: Record<string, string> = {
    "Easy": "1",
    "Medium": "2",
    "Hard": "3",
    "1": "1",
    "2": "2",
    "3": "3"
  };

  const visibilityMap: Record<string, string> = {
    "Private": "1",
    "Public": "2",
    "1": "1",
    "2": "2"
  };

  const initialDiff = initialData.difficulty ? (difficultyMap[initialData.difficulty.toString()] || "1") : "1";
  const initialVis = initialData.visibility ? (visibilityMap[initialData.visibility.toString()] || "2") : "2";

  const [selectedCategoryIds, setSelectedCategoryIds] = useState<number[]>(
    Array.from(new Set(initialData.categories?.map((c: any) => c.id) || []))
  );
  const [difficulty, setDifficulty] = useState(initialDiff);
  const [servings, setServings] = useState(initialData.servings?.toString() || "4");
  const [prepTime, setPrepTime] = useState(initialData.prepTime?.toString() || "15");
  const [cookTime, setCookTime] = useState(initialData.cookTime?.toString() || "45");
  const [visibility, setVisibility] = useState(initialVis); 
  
  const [selectedTagIds, setSelectedTagIds] = useState<number[]>(
    Array.from(new Set(initialData.tags?.map((t: any) => t.id) || []))
  );

  const [ingredients, setIngredients] = useState<IngredientInput[]>(
    initialData.ingredients && initialData.ingredients.length > 0 
      ? initialData.ingredients.map((ing, i) => ({
          id: i.toString(),
          qty: ing.amount.toString(),
          unitId: ing.unitId.toString(),
          ingredientId: ing.ingredientId || "",
          name: ing.ingredientName,
          unitFamily: ing.unitFamily as MeasurementCategory,
          isSearching: false,
          searchResults: []
        }))
      : [{ id: "1", qty: "", unitId: "", ingredientId: "", name: "", isSearching: false, searchResults: [] }]
  );

  const [steps, setSteps] = useState<StepInput[]>(
    initialData.steps && initialData.steps.length > 0
      ? initialData.steps.map(s => ({
          id: s.id.toString(),
          instruction: s.instruction,
          imagePreview: initialData.images?.find((i: any) => i.stepId === s.id)?.imageUrl || null
        }))
      : [{ id: "1", instruction: "" }]
  );

  // Modal State
  const [showAddModal, setShowAddModal] = useState(false);
  const [pendingIngredientName, setPendingIngredientName] = useState("");
  const [pendingIngredientRowId, setPendingIngredientRowId] = useState("");
  const [newIngCategory, setNewIngCategory] = useState("");
  const [newIngUnit, setNewIngUnit] = useState<MeasurementUnit>(MeasurementUnit.Piece);

  // Fetch Pantry Categories (for new ingredient suggestions)
  const { data: pantryCategories = [] } = useQuery({
    queryKey: ["ingredient-categories"],
    queryFn: () => pantryApi.getCategories()
  });

  // Fetch Recipe Taxonomy
  const { data: recipeCategories = [] } = useAdminRecipeCategories();
  const { data: recipeTags = [] } = useAdminTags();

  const toggleCategory = (id: number) => {
    setSelectedCategoryIds(prev => {
      if (prev.includes(id)) return prev.filter(c => c !== id);
      if (prev.length >= 3) {
        toast.error("En fazla 3 kategori seçebilirsiniz.");
        return prev;
      }
      return [...prev, id];
    });
  };

  const toggleTag = (id: number) => {
    setSelectedTagIds(prev => {
      if (prev.includes(id)) return prev.filter(t => t !== id);
      if (prev.length >= 5) {
        toast.error("En fazla 5 etiket seçebilirsiniz.");
        return prev;
      }
      return [...prev, id];
    });
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setCoverPhoto(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setCoverPhotoPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };



  const addIngredient = () => {
    setIngredients(prev => [...prev, { id: Date.now().toString(), qty: "", unitId: "", ingredientId: "", name: "", isSearching: false, searchResults: [] }]);
  };

  const removeIngredient = (id: string) => {
    setIngredients(prev => {
      if (prev.length > 1) {
        return prev.filter(ing => ing.id !== id);
      }
      return prev;
    });
  };

  const updateIngredient = (id: string, field: keyof IngredientInput, value: any) => {
    setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, [field]: value } : ing));
  };

  // Ingredient Autocomplete Logic
  const handleIngredientSearch = async (id: string, keyword: string) => {
    setIngredients(prev => prev.map(ing => 
      ing.id === id ? { ...ing, name: keyword, ingredientId: "" } : ing
    ));
    
    if (keyword.length >= 2) {
      setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, isSearching: true } : ing));
      try {
        const results = await pantryApi.searchIngredients(keyword);
        setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, searchResults: results } : ing));
      } catch (error) {
        console.error("Search failed", error);
      } finally {
        setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, isSearching: false } : ing));
      }
    } else {
      setIngredients(prev => prev.map(ing => ing.id === id ? { ...ing, searchResults: [] } : ing));
    }
  };

  const handleSelectSearchResult = (id: string, result: any) => {
    setIngredients(prev => prev.map(ing => {
      if (ing.id === id) {
        const familyVal = typeof result.unitFamily === 'string' 
          ? MeasurementCategory[result.unitFamily as keyof typeof MeasurementCategory] 
          : result.unitFamily;

        return {
          ...ing,
          name: result.displayName,
          ingredientId: result.masterIngredientId,
          unitFamily: familyVal,
          searchResults: [], 
          unitId: MEASUREMENT_CATEGORY_UNITS[familyVal as MeasurementCategory]?.[0]?.toString() || ""
        };
      }
      return ing;
    }));
  };

  const handleAddNewIngredientClick = (id: string, name: string) => {
    setPendingIngredientRowId(id);
    setPendingIngredientName(name);
    setShowAddModal(true);
    updateIngredient(id, "searchResults", []); // Close dropdown
  };

  const handleAddNewIngredientConfirm = () => {
    if (!newIngCategory) return;
    
    setIngredients(prev => prev.map(ing => {
      if (ing.id === pendingIngredientRowId) {
        return {
          ...ing,
          name: pendingIngredientName,
          ingredientId: "",
          isPending: true,
          suggestedCategoryId: newIngCategory,
          unitId: newIngUnit.toString()
        };
      }
      return ing;
    }));
    
    setShowAddModal(false);
    setNewIngCategory("");
  };

  const addStep = () => {
    setSteps(prev => [...prev, { id: Date.now().toString(), instruction: "" }]);
  };

  const updateStep = (id: string, field: keyof StepInput, value: any) => {
    setSteps(prev => prev.map(step => step.id === id ? { ...step, [field]: value } : step));
  };

  const removeStep = (id: string) => {
    setSteps(prev => {
      if (prev.length > 1) {
        return prev.filter(step => step.id !== id);
      }
      return prev;
    });
  };

  const updateMutation = useMutation({
    mutationFn: (formData: FormData) => recipeApi.updateRecipe(initialData.id, formData),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["my-recipes"] });
      queryClient.invalidateQueries({ queryKey: ["recipe-detail", initialData.id] });
      navigate(`/recipes/${initialData.id}`);
    },
    onError: (error: any) => {
      console.error("Failed to update recipe", error);
      const errorMessage = error.response?.data?.detail || error.response?.data?.message || "Tarif güncellenirken bir hata oluştu.";
      toast.error(errorMessage);
    }
  });

  const handleSubmit = () => {
    if (!title.trim() || selectedCategoryIds.length === 0) {
      toast.error("Lütfen Tarif Adı ve en az bir kategori alanını eksiksiz doldurun.");
      return;
    }

    if (!difficulty) {
      toast.error("Lütfen bir zorluk derecesi seçin.");
      return;
    }

    if (!servings || parseInt(servings) <= 0) {
      toast.error("Porsiyon 0'dan büyük olmalıdır.");
      return;
    }

    if (!prepTime || parseInt(prepTime) < 0 || !cookTime || parseInt(cookTime) < 0) {
      toast.error("Lütfen geçerli bir hazırlık ve pişirme süresi girin.");
      return;
    }

    const validIngredients = ingredients.filter(i => (i.ingredientId || i.isPending) && i.qty && i.unitId);
    if (validIngredients.length === 0) {
      toast.error("Lütfen en az bir geçerli malzeme ekleyin.");
      return;
    }

    const formData = new FormData();
    formData.append("Title", title);
    formData.append("Description", description);
    formData.append("Visibility", visibility); // "1" or "2"
    formData.append("Difficulty", difficulty); // "1", "2" or "3"
    formData.append("Servings", servings);
    formData.append("PrepTime", prepTime);
    formData.append("CookTime", cookTime);
    
    const uniqueCategoryIds = Array.from(new Set(selectedCategoryIds));
    const uniqueTagIds = Array.from(new Set(selectedTagIds));

    if (uniqueCategoryIds.length === 0 || uniqueCategoryIds.length > 3) {
      toast.error("En az 1, en fazla 3 kategori seçebilirsiniz.");
      return;
    }

    if (uniqueTagIds.length > 5) {
      toast.error("En fazla 5 etiket seçebilirsiniz.");
      return;
    }

    uniqueCategoryIds.forEach(id => {
      formData.append("CategoryIds", id.toString());
    });

    uniqueTagIds.forEach(id => {
      formData.append("TagIds", id.toString());
    });

    if (coverPhoto) {
      formData.append("NewMainImage", coverPhoto);
    }

    const formattedIngredients = validIngredients.map(i => ({
      IngredientId: i.ingredientId || null,
      RequestedName: i.isPending ? i.name : null,
      SuggestedCategoryId: i.isPending ? i.suggestedCategoryId : null,
      Amount: parseFloat(i.qty) || 0,
      UnitId: parseInt(i.unitId) || 1
    }));
    formData.append("IngredientsJson", JSON.stringify(formattedIngredients));

    const formattedSteps = steps
      .filter(s => s.instruction.trim() !== "")
      .map((s, index) => ({
        StepNumber: index + 1,
        Instruction: s.instruction
      }));
    formData.append("StepsJson", JSON.stringify(formattedSteps));

    steps.filter(s => s.instruction.trim() !== "").forEach((s, index) => {
      const stepNum = index + 1;
      if (s.image) {
        formData.append("StepImages", s.image);
        formData.append("StepImageStepNumbers", stepNum.toString());
      }
    });

    updateMutation.mutate(formData);
  };

  return (
    <div className="w-full max-w-7xl mx-auto flex flex-col min-h-screen">
      {/* Header Actions */}
      <div className="flex items-center justify-between mb-8 pb-4 border-b border-muted/20">
        <div className="flex items-center gap-2 text-sm text-muted-foreground font-medium">
          <span>Tarifler</span>
          <span>/</span>
          <span className="text-foreground">Tarifi Düzenle</span>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => navigate(-1)}
            disabled={updateMutation.isPending}
            className="px-6 py-2.5 rounded-xl font-bold text-foreground hover:bg-muted/50 transition-colors"
          >
            İptal
          </button>
          <button 
            onClick={handleSubmit}
            disabled={updateMutation.isPending}
            className="px-6 py-2.5 rounded-xl font-bold bg-[#588157] hover:bg-[#3a5a39] text-white transition-colors flex items-center gap-2 shadow-lg shadow-[#588157]/20 disabled:opacity-50"
          >
            {updateMutation.isPending ? <span className="animate-pulse">Güncelleniyor...</span> : <><Save className="w-4 h-4" /> Tarifi Güncelle</>}
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-8 lg:gap-12">
        {/* LEFT COLUMN: Basic Info & Meta */}
        <div className="flex-1 flex flex-col gap-8">
          
          {/* Title & Description */}
          <div className="flex flex-col gap-4">
            <input
              type="text"
              placeholder="Tarif Adı"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="text-4xl md:text-5xl font-black text-foreground/30 placeholder:text-foreground/30 focus:text-foreground bg-transparent border-none outline-none w-full transition-colors"
            />
            <textarea
              placeholder="Bu yemeğin hikayesini anlatın... (Örn. 'Büyükannemden bana kalan, pazar günlerinin vazgeçilmezi...')"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="text-lg text-muted-foreground placeholder:text-muted-foreground/50 bg-transparent border-none outline-none w-full resize-none min-h-[100px]"
            />
          </div>

          {/* Cover Photo Upload */}
          <div 
            onClick={() => fileInputRef.current?.click()}
            className={`w-full aspect-[4/3] md:aspect-[16/9] border-2 border-dashed rounded-3xl flex flex-col items-center justify-center cursor-pointer transition-all relative overflow-hidden group ${coverPhoto ? 'border-primary/50' : 'border-muted/40 hover:bg-muted/5 hover:border-primary/50'}`}
          >
            {coverPhotoPreview ? (
              <>
                <img src={coverPhotoPreview} alt="Cover" className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                  <span className="text-white font-bold">Fotoğrafı Değiştir</span>
                </div>
              </>
            ) : (
              <div className="flex flex-col items-center gap-3 text-muted-foreground group-hover:text-primary transition-colors">
                <div className="w-16 h-16 rounded-full bg-muted/20 group-hover:bg-primary/10 flex items-center justify-center transition-colors">
                  <ImagePlus className="w-8 h-8" />
                </div>
                <span className="font-bold text-foreground">Kapak Fotoğrafı Yükle</span>
                <span className="text-sm">PNG, JPG (Maks 10MB)</span>
              </div>
            )}
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/png, image/jpeg"
              onChange={handlePhotoUpload} 
            />
          </div>

          {/* Meta Information Cards */}
          <div className="flex flex-col gap-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Zorluk Derecesi</span>
                <div className="relative">
                  <select 
                    value={difficulty} 
                    onChange={(e) => setDifficulty(e.target.value)}
                    className="w-full bg-muted/40 border border-muted hover:border-primary/30 rounded-xl px-4 py-3 appearance-none font-medium text-foreground outline-none focus:border-primary/50 transition-colors"
                  >
                    <option value="" disabled className="text-foreground bg-neutral-50 dark:bg-neutral-900">Zorluk Seçin</option>
                    {DIFFICULTIES.map(d => <option key={d.id} value={d.id} className="text-foreground bg-neutral-50 dark:bg-neutral-900">{d.name}</option>)}
                  </select>
                  <ChevronDown className="w-4 h-4 text-muted-foreground absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none" />
                </div>
              </div>

              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Görünürlük</span>
                <div className="relative">
                  <select 
                    value={visibility} 
                    onChange={(e) => setVisibility(e.target.value)}
                    className="w-full bg-muted/40 border border-muted hover:border-primary/30 rounded-xl px-4 py-3 appearance-none font-medium text-foreground outline-none focus:border-primary/50 transition-colors"
                  >
                    <option value="2" className="text-foreground bg-neutral-50 dark:bg-neutral-900">Herkese Açık (Public)</option>
                    <option value="1" className="text-foreground bg-neutral-50 dark:bg-neutral-900">Sadece Ben (Private)</option>
                  </select>
                  <ChevronDown className="w-4 h-4 text-muted-foreground absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none" />
                </div>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Porsiyon</span>
                <div className="flex items-center gap-2 bg-muted/40 border border-muted rounded-xl px-4 py-3 focus-within:border-primary/50 transition-colors hover:border-primary/30">
                  <input type="number" 
                    value={servings} 
                    onChange={(e) => setServings(e.target.value)}
                    className="w-full bg-transparent font-medium text-foreground outline-none"
                    min="1"
                  />
                  <span className="text-muted-foreground text-sm">Kişilik</span>
                </div>
              </div>

              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Hazırlık</span>
                <div className="flex items-center gap-2 bg-muted/40 border border-muted rounded-xl px-4 py-3 focus-within:border-primary/50 transition-colors hover:border-primary/30">
                  <input type="number" 
                    value={prepTime} 
                    onChange={(e) => setPrepTime(e.target.value)}
                    className="w-full bg-transparent font-medium text-foreground outline-none"
                    min="0"
                  />
                  <span className="text-muted-foreground text-sm">Dk</span>
                </div>
              </div>

              <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col">
                <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Pişirme</span>
                <div className="flex items-center gap-2 bg-muted/40 border border-muted rounded-xl px-4 py-3 focus-within:border-primary/50 transition-colors hover:border-primary/30">
                  <input type="number" 
                    value={cookTime} 
                    onChange={(e) => setCookTime(e.target.value)}
                    className="w-full bg-transparent font-medium text-foreground outline-none"
                    min="0"
                  />
                  <span className="text-muted-foreground text-sm">Dk</span>
                </div>
              </div>
            </div>

            <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col gap-3">
              <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Kategoriler</span>
              <div className="flex flex-wrap gap-2">
                {recipeCategories.map((cat: any) => {
                  const isSelected = selectedCategoryIds.includes(cat.id);
                  return (
                    <button
                      key={cat.id}
                      onClick={() => toggleCategory(cat.id)}
                      className={`px-4 py-2 rounded-xl text-sm font-bold border transition-all ${
                        isSelected 
                          ? 'bg-primary text-primary-foreground border-primary shadow-md' 
                          : 'bg-muted/40 dark:bg-neutral-800 text-muted-foreground border-muted/50 hover:border-primary/50'
                      }`}
                    >
                      {cat.name}
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl p-4 flex flex-col gap-3">
              <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Etiketler</span>
              <div className="flex flex-wrap gap-2">
                {recipeTags.map((tag: any) => {
                  const isSelected = selectedTagIds.includes(tag.id);
                  return (
                    <button
                      key={tag.id}
                      onClick={() => toggleTag(tag.id)}
                      className={`px-3 py-1.5 rounded-full text-sm font-bold border transition-all ${
                        isSelected 
                          ? 'bg-primary text-primary-foreground border-primary shadow-md' 
                          : 'bg-muted/40 dark:bg-neutral-800 text-muted-foreground border-muted/50 hover:border-primary/50'
                      }`}
                    >
                      # {tag.name}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Ingredients & Preparation */}
        <div className="flex-1 flex flex-col gap-6">
          
          <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-[2rem] p-6 md:p-8">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-muted/40 dark:bg-neutral-800 flex items-center justify-center shadow-sm border border-muted/20">
                  <span className="text-primary font-bold text-lg">⚖️</span>
                </div>
                <h3 className="text-2xl font-bold text-foreground">Malzemeler</h3>
              </div>
              <span className="text-sm font-bold text-muted-foreground">{ingredients.length} ADET</span>
            </div>

            <div className="flex flex-col gap-3">
              <div className="grid grid-cols-[auto_60px_100px_1fr_auto] gap-4 px-2 text-xs font-bold text-muted-foreground uppercase tracking-wider mb-1">
                <div className="w-6"></div>
                <div>Miktar</div>
                <div>Birim</div>
                <div>Malzeme (Arama)</div>
                <div className="w-6"></div>
              </div>

              {ingredients.map((ing) => {
                const allowedUnits = ing.unitFamily 
                  ? MEASUREMENT_CATEGORY_UNITS[ing.unitFamily] || ALL_UNITS
                  : ALL_UNITS;

                return (
                  <div key={ing.id} className="grid grid-cols-[auto_60px_100px_1fr_auto] gap-4 items-center bg-muted/40 dark:bg-neutral-800 p-2 rounded-xl shadow-sm border border-muted/10 group relative">
                    <div className="w-6 flex items-center justify-center text-muted-foreground/30 cursor-grab">
                      <GripVertical className="w-4 h-4" />
                    </div>
                    
                    <input 
                      type="number" 
                      value={ing.qty} 
                      onChange={(e) => updateIngredient(ing.id, "qty", e.target.value)}
                      className="w-full bg-transparent outline-none text-center font-medium placeholder:text-muted-foreground/30"
                      placeholder="1"
                    />
                    
                    <div className="relative">
                      <select 
                        value={ing.unitId} 
                        onChange={(e) => updateIngredient(ing.id, "unitId", e.target.value)}
                        className={`w-full bg-transparent outline-none text-sm font-medium appearance-none ${!ing.ingredientId && !ing.isPending ? 'opacity-50' : ''}`}
                        disabled={!ing.ingredientId && !ing.isPending}
                      >
                        <option value="" disabled className="text-foreground bg-neutral-50 dark:bg-neutral-900">Seç...</option>
                        {allowedUnits.map(unitVal => (
                          <option key={unitVal} value={unitVal} className="text-foreground bg-neutral-50 dark:bg-neutral-900">
                            {MEASUREMENT_UNIT_LABELS[unitVal as MeasurementUnit]}
                          </option>
