source:
import { Footer } from '@/widgets/footer';
import { useState, useEffect, useRef } from "react";
import { toast } from "sonner";
import { motion, AnimatePresence } from "framer-motion";
import { useQuery } from "@tanstack/react-query";
import { userApi, RecommendationMode } from "@/entities/user/api/userApi";
import { pantryApi } from "@/entities/pantry/api/pantryApi";
import { RecipeCard } from "@/widgets/recipe-card/ui/RecipeCard";
import { Sidebar } from "@/widgets/sidebar/ui/Sidebar";
import { DashboardHeader } from "@/widgets/dashboard-header/ui/DashboardHeader";
import { Sparkles, Zap, Flame, Compass, PackageMinus, BrainCircuit, Heart, Info, Loader2, Salad, Target, ChevronDown, Leaf, ShieldAlert, ThumbsDown } from "lucide-react";
import { cn } from "@/shared/lib/utils";


const modes = [
  { id: RecommendationMode.Default, label: "DENGELİ", fullLabel: "Dengeli Öneriler", icon: BrainCircuit, description: "Eldeki malzemelerinle damak zevkini harmanlayan en optimal günlük denge." },
  { id: RecommendationMode.Strict, label: "SADECE DOLAP", fullLabel: "Sadece Dolaptakiler", icon: Flame, description: "Alışverişe çıkmadan, kesinlikle sadece dolabındaki malzemelerle yapabileceğin tarifler." },
  { id: RecommendationMode.ForYou, label: "SANA ÖZEL", fullLabel: "Sana Özel", icon: Heart, description: "Malzemeleri umursamadan, tamamen geçmiş beğenilerine göre senin tarzına en uygun lezzetler." },
  { id: RecommendationMode.Ultimate, label: "GURME", fullLabel: "Gurme", icon: Sparkles, description: "Şefin seçimi! Hem zevkine uyan hem de 1'e 1 eşleşen kusursuz, garantili tarifler." },
  { id: RecommendationMode.Quick, label: "HIZLI PİŞİR", fullLabel: "Hızlı Pişir", icon: Zap, description: "Zamanın az olduğunda, minimum çaba ve eldeki malzemeyle şipşak kurtarıcı öğünler." },
  { id: RecommendationMode.Explore, label: "KEŞFET", fullLabel: "Keşfet", icon: Compass, description: "Klasikleri unut! Daha az bilinen, daha önce hiç denemediğin yeni gizli lezzetler." },
  { id: RecommendationMode.MinimalShopping, label: "AZ ALIŞVERİŞ", fullLabel: "Minimum Alışveriş", icon: PackageMinus, description: "Eksikleri minimumda tutarak, marketten sadece 1-2 şey alıp hemen hazırlayabileceğin tarifler." },
];

export const AiRecommendationsPage = () => {
  const [selectedMode, setSelectedMode] = useState<RecommendationMode>(RecommendationMode.Strict);
  const [useZeroWaste, setUseZeroWaste] = useState(false);
  const [useAllergyFilters, setUseAllergyFilters] = useState(true);
  const [useDietFilters, setUseDietFilters] = useState(true);
  const [useDislikedFilters, setUseDislikedFilters] = useState(true);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [hasRequested, setHasRequested] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);
  const resultsRef = useRef<HTMLElement>(null);

  const loadingTexts = [
    "Mutfak dolabındaki malzemeler taranıyor...",
    "Geçmiş lezzet profilin analiz ediliyor...",
    "Diyet tercihlerin gözden geçiriliyor...",
    "Sana özel kusursuz eşleşmeler hesaplanıyor...",
    "Şefin son dokunuşları yapılıyor..."
  ];

  // Queries for Context
  const { data: profile } = useQuery({
    queryKey: ["user_profile"],
    queryFn: () => userApi.getProfile(),
  });

  const { data: pantryItems } = useQuery({
    queryKey: ["pantry_items"],
    queryFn: () => pantryApi.getMyPantry(),
  });

  const { data: recommendations, isFetching, refetch } = useQuery({
    queryKey: ["ai_recommendations", selectedMode, useZeroWaste, useAllergyFilters, useDietFilters, useDislikedFilters],
    queryFn: () => userApi.getRecommendations(selectedMode, useZeroWaste, useAllergyFilters, useDietFilters, useDislikedFilters),
    enabled: false,
    staleTime: 5 * 60 * 1000,
  });

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isFetching) {
      setLoadingStep(0);
      interval = setInterval(() => {
        setLoadingStep((prev) => (prev + 1) % loadingTexts.length);
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [isFetching]);

  const handleGenerate = () => {
    setHasRequested(true);
    refetch().then((res) => {
      if (res.isError) {
        toast.error("Öneriler alınırken bir hata oluştu.", {
          description: "Lütfen bağlantınızı kontrol edip tekrar deneyin."
        });
      } else {
        // Scroll to results after fetching
        setTimeout(() => {
          resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
        }, 500);
      }
    }).catch(() => {
        toast.error("Beklenmeyen bir hata oluştu.");
    });
  };

  const handleModeSelect = (id: RecommendationMode) => {
    setSelectedMode(id);
    setHasRequested(false);
  };

  return (
    <div className="min-h-screen bg-[#fcfcfc] dark:bg-[#0a0a0a] transition-colors duration-500">
      <Sidebar />
      <main className="lg:ml-72 min-h-screen flex flex-col">
        <DashboardHeader />

        <div className="flex-1 p-8 max-w-7xl mx-auto w-full pt-10">
          
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 items-start">
            
            {/* Left Column - Content & Modes */}
            <div className="lg:col-span-7 space-y-12">
              
              {/* Hero Header */}
              <section>
                <h1 className="text-5xl md:text-7xl font-black text-foreground tracking-tighter leading-[1.1] mb-6">
                  Bir Sonraki Öğününü <br/> <span className="italic text-primary">Keşfet</span>
                </h1>
                <p className="text-lg md:text-xl text-muted-foreground leading-relaxed max-w-lg">
                  Nasıl bir deneyim aradığını seç ve OleAI sana özel kusursuz bir lezzet serüveni hazırlasın.
                </p>
              </section>

              {/* Modes Selection */}
              <section>
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-2xl font-bold tracking-tight text-foreground flex items-center gap-2">
                    <BrainCircuit className="w-6 h-6 text-primary" /> Analiz Modu
                  </h2>
                </div>
                
                {/* Custom Dropdown Selector */}
                <div className="relative">
                  <button
                    onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    className="w-full flex items-center justify-between bg-card border border-border/50 hover:border-primary/50 px-6 py-5 rounded-[24px] transition-all shadow-sm group"
                  >
                    <div className="flex items-center gap-4">
                      {(() => {
                        const SelectedIcon = modes.find(m => m.id === selectedMode)?.icon;
                        return SelectedIcon ? <SelectedIcon className="w-7 h-7 text-primary" /> : null;
                      })()}
                      <span className="font-bold text-lg text-foreground uppercase tracking-wide">
                        {modes.find(m => m.id === selectedMode)?.label}
                      </span>
                    </div>
                    <ChevronDown className={cn("w-6 h-6 text-muted-foreground transition-transform duration-300", isDropdownOpen && "rotate-180")} />
                  </button>

                  <AnimatePresence>
                    {isDropdownOpen && (
                      <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        className="absolute top-full left-0 right-0 mt-2 bg-card border border-border/50 rounded-[24px] shadow-2xl overflow-hidden z-50 flex flex-col p-2"
                      >
                        {modes.map((mode) => {
                          const Icon = mode.icon;
                          const isSelected = selectedMode === mode.id;
                          return (
                            <button
                              key={mode.id}
                              onClick={() => {
                                handleModeSelect(mode.id);
                                setIsDropdownOpen(false);
                              }}
                              className={cn(
                                "flex items-center gap-4 px-5 py-4 rounded-2xl transition-all text-left",
                                isSelected ? "bg-primary/10 text-primary" : "hover:bg-muted/50 text-muted-foreground hover:text-foreground"
                              )}
                            >
                              <Icon className="w-6 h-6 shrink-0" />
                              <span className="font-bold uppercase tracking-wide block">{mode.label}</span>
                            </button>
                          );
                        })}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>

                {/* Dynamic Mode Description */}
                <AnimatePresence mode="wait">
                  <motion.div
                    key={selectedMode}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    className="mt-6 bg-card border border-border/50 rounded-[24px] p-6 flex items-start gap-5 shadow-sm"
                  >
                    <div className="bg-primary/10 p-3 rounded-full shrink-0">
                      <Info className="w-6 h-6 text-primary" />
                    </div>
                    <div className="pt-1">
                      <h4 className="font-bold text-foreground mb-1 text-sm uppercase tracking-wider">{modes.find(m => m.id === selectedMode)?.label} Modu</h4>
                      <p className="text-muted-foreground leading-relaxed text-sm">
                        {modes.find(m => m.id === selectedMode)?.description}
                      </p>
                    </div>
                  </motion.div>
                </AnimatePresence>



                <div className="mt-8">
                  <button
                    onClick={handleGenerate}
                    disabled={isFetching}
                    className="w-full h-16 bg-[#588157] hover:bg-[#3a5a39] text-white rounded-[24px] flex items-center justify-center gap-3 font-bold text-lg shadow-lg shadow-[#588157]/20 transition-all active:scale-[0.98] disabled:opacity-70 disabled:scale-100"
                  >
                    {isFetching ? (
                      <Loader2 className="w-6 h-6 animate-spin" />
                    ) : (
                      <Sparkles className="w-6 h-6" />
                    )}
                    {isFetching ? "Yapay Zeka Çalışıyor..." : "Önerileri Getir"}
                  </button>
                </div>
              </section>
            </div>

            {/* Right Column - Visual & Context */}
            <div className="lg:col-span-5 flex flex-col gap-6 mt-10 lg:mt-0 md:flex">
               {/* Live Context Card */}
               <div className="bg-card/95 backdrop-blur-xl rounded-[32px] p-8 shadow-2xl border border-border/50 w-full shrink-0">
                 <div className="flex justify-between items-center mb-6">
                    <span className="text-[10px] font-black uppercase tracking-widest text-primary bg-primary/10 px-4 py-1.5 rounded-full">
                      Kişisel Bağlam
                    </span>
                    <div className="flex items-center gap-2 text-xs font-semibold text-muted-foreground">
                      <Target className="w-4 h-4" /> OleAI Aktif
                    </div>
                 </div>
                 
                 <div>
                    <h3 className="text-2xl font-bold tracking-tight text-foreground mb-2">Profil Özeti</h3>
                    <p className="text-sm text-muted-foreground mb-6 leading-relaxed">
                      Zeka motoru sana özel öneriler sunarken şu parametreleri anlık olarak kullanır:
                    </p>
                    
                    <div className="flex flex-col gap-4">
                      <div className="flex items-center gap-4 bg-muted/30 p-4 rounded-2xl relative overflow-hidden group">
                        <div className="absolute inset-0 bg-gradient-to-r from-blue-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                        <div className="w-12 h-12 rounded-full bg-blue-500/10 flex items-center justify-center relative">
                          <PackageMinus className="w-6 h-6 text-blue-500" />
                          <div className="absolute inset-0 rounded-full border-2 border-blue-500/30 animate-ping opacity-20" />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-foreground">Dolap Stoğu</p>
                          <p className="text-xs text-muted-foreground">
                            {pantryItems ? `${pantryItems.length} malzeme tanımlı` : "Yükleniyor..."}
                          </p>
                        </div>
                      </div>
                      
                      <div className="flex items-center gap-4 bg-muted/30 p-4 rounded-2xl relative overflow-hidden group">
                        <div className="absolute inset-0 bg-gradient-to-r from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                        <div className="w-12 h-12 rounded-full bg-emerald-500/10 flex items-center justify-center relative">
                          <Salad className="w-6 h-6 text-emerald-500" />
                          <div className="absolute inset-0 rounded-full border-2 border-emerald-500/30 animate-ping opacity-20" style={{ animationDelay: '0.5s' }} />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-foreground">Diyetler</p>
                          <p className="text-xs text-muted-foreground line-clamp-1">
                            {profile?.dietaryPreferences?.length ? profile.dietaryPreferences.map(d => d.name).join(", ") : "Özel diyet seçilmedi"}
                          </p>
                        </div>
                      </div>
                    </div>
                 </div>
               </div>

               {/* Advanced Options Card */}
               <div className="bg-card/95 backdrop-blur-xl rounded-[32px] p-8 shadow-2xl border border-border/50 w-full shrink-0">
                 <div className="flex justify-between items-center mb-6">
                    <span className="text-[10px] font-black uppercase tracking-widest text-primary bg-primary/10 px-4 py-1.5 rounded-full">
                      Gelişmiş Seçenekler
                    </span>
                 </div>
                 
                 <h3 className="text-2xl font-bold tracking-tight text-foreground mb-4">Motor Ayarları</h3>
                 <p className="text-sm text-muted-foreground mb-6 leading-relaxed">
                   Yapay zeka önerilerini oluştururken kullanılacak ek filtreleri buradan açıp kapatabilirsiniz.
                 </p>

                 <div className="flex flex-col gap-3">
                   {/* Zero Waste */}
                   <div className="flex items-center justify-between p-3 bg-muted/30 rounded-2xl">
                     <div className="flex items-center gap-3">
                       <div className={cn("p-2 rounded-full shrink-0 transition-colors", useZeroWaste ? "bg-primary/20" : "bg-muted")}>
                         <Leaf className={cn("w-5 h-5", useZeroWaste ? "text-primary" : "text-muted-foreground")} />
                       </div>
                       <div>
                         <h4 className="font-bold text-foreground text-sm">İsrafı Önle</h4>
                       </div>
                     </div>
                     <button 
                       onClick={() => setUseZeroWaste(!useZeroWaste)}
                       className={cn("relative inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none", useZeroWaste ? "bg-primary" : "bg-muted")}
                     >
                       <span className={cn("pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out", useZeroWaste ? "translate-x-5" : "translate-x-0")} />
                     </button>
                   </div>

                   {/* Allergy */}
                   <div className="flex items-center justify-between p-3 bg-muted/30 rounded-2xl">
                     <div className="flex items-center gap-3">
                       <div className={cn("p-2 rounded-full shrink-0 transition-colors", useAllergyFilters ? "bg-red-500/20" : "bg-muted")}>
                         <ShieldAlert className={cn("w-5 h-5", useAllergyFilters ? "text-red-500" : "text-muted-foreground")} />
                       </div>
                       <div>
                         <h4 className="font-bold text-foreground text-sm">Alerji Koruması</h4>
                       </div>
                     </div>
                     <button 
                       onClick={() => setUseAllergyFilters(!useAllergyFilters)}
                       className={cn("relative inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none", useAllergyFilters ? "bg-red-500" : "bg-muted")}
                     >
                       <span className={cn("pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out", useAllergyFilters ? "translate-x-5" : "translate-x-0")} />
                     </button>
                   </div>

                   {/* Diet */}
                   <div className="flex items-center justify-between p-3 bg-muted/30 rounded-2xl">
                     <div className="flex items-center gap-3">
                       <div className={cn("p-2 rounded-full shrink-0 transition-colors", useDietFilters ? "bg-green-500/20" : "bg-muted")}>
                         <Salad className={cn("w-5 h-5", useDietFilters ? "text-green-500" : "text-muted-foreground")} />
                       </div>
                       <div>
                         <h4 className="font-bold text-foreground text-sm">Diyet Kuralları</h4>
                       </div>
                     </div>
                     <button 
                       onClick={() => setUseDietFilters(!useDietFilters)}
                       className={cn("relative inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none", useDietFilters ? "bg-green-500" : "bg-muted")}
                     >
                       <span className={cn("pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out", useDietFilters ? "translate-x-5" : "translate-x-0")} />
                     </button>
                   </div>

                   {/* Disliked */}
                   <div className="flex items-center justify-between p-3 bg-muted/30 rounded-2xl">
                     <div className="flex items-center gap-3">
                       <div className={cn("p-2 rounded-full shrink-0 transition-colors", useDislikedFilters ? "bg-orange-500/20" : "bg-muted")}>
                         <ThumbsDown className={cn("w-5 h-5", useDislikedFilters ? "text-orange-500" : "text-muted-foreground")} />
                       </div>
                       <div>
                         <h4 className="font-bold text-foreground text-sm">Sevilmeyenler</h4>
                       </div>
                     </div>
                     <button 
                       onClick={() => setUseDislikedFilters(!useDislikedFilters)}
                       className={cn("relative inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none", useDislikedFilters ? "bg-orange-500" : "bg-muted")}
                     >
                       <span className={cn("pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out", useDislikedFilters ? "translate-x-5" : "translate-x-0")} />
                     </button>
                   </div>
                 </div>
               </div>
            </div>
          </div>

          {/* Results Area */}
          <section ref={resultsRef} className="mt-32 pb-20 scroll-mt-32">
            <AnimatePresence mode="wait">
              {isFetching ? (
                <motion.div
                  key="loading"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="flex flex-col items-center justify-center py-20 min-h-[400px]"
                >
                  <div className="relative mb-8">
                    <div className="absolute inset-0 bg-primary/20 blur-xl rounded-full animate-pulse" />
                    <div className="w-20 h-20 bg-primary/10 border-2 border-primary/20 rounded-full flex items-center justify-center relative">
                      <BrainCircuit className="w-10 h-10 text-primary animate-pulse" />
                    </div>
                  </div>
                  
                  <div className="h-8 overflow-hidden relative">
                    <AnimatePresence mode="wait">
                      <motion.p
                        key={loadingStep}
                        initial={{ y: 20, opacity: 0 }}
                        animate={{ y: 0, opacity: 1 }}
                        exit={{ y: -20, opacity: 0 }}
                        transition={{ duration: 0.3 }}
                        className="text-xl text-primary font-bold tracking-tight text-center"
                      >
                        {loadingTexts[loadingStep]}
                      </motion.p>
                    </AnimatePresence>
                  </div>
                  <p className="text-muted-foreground mt-4 max-w-sm text-center">Bu işlem, dolabındaki malzemelere ve profil büyüklüğüne göre birkaç saniye sürebilir.</p>
                </motion.div>
              ) : hasRequested && recommendations && recommendations.length > 0 ? (
                <motion.div
                  key="content"
                  initial={{ opacity: 0, y: 40 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-12"
                >
                  <div className="text-center mb-10">
                    <h2 className="text-4xl font-black tracking-tight text-foreground mb-4">Senin İçin Seçtiklerimiz</h2>
                    <p className="text-lg text-muted-foreground mb-6">Zeka Motoru profilini analiz etti ve en uygun {recommendations.length} tarifi buldu.</p>

                    {recommendations.some(r => r.isFallback) && (
                      <div className="bg-primary/10 border border-primary/20 p-6 rounded-[24px] flex items-start gap-4 text-left max-w-3xl mx-auto shadow-lg shadow-primary/5">
                        <div className="bg-primary/20 p-3 rounded-full shrink-0">
                           <Info className="w-6 h-6 text-primary" />
                        </div>
                        <div>
                          <h4 className="font-bold text-foreground text-lg mb-1">Daha Fazla Etkileşime İhtiyacımız Var</h4>
                          <p className="text-muted-foreground leading-relaxed">
                            Sistemimiz şu anda sizi tam olarak tanımadığı veya elinizdeki malzemelerle uygun eşleşme bulamadığı için size platformdaki <strong>en popüler trend tarifleri</strong> gösteriyor. Size özel kusursuz öneriler sunabilmemiz için bol bol tarif <strong>beğenmeniz</strong> veya <strong>kaydetmeniz</strong> gerekiyor!
                          </p>
                        </div>
                      </div>
                    )}
                  </div>
                  
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10">
                    {recommendations.map((item, idx) => (
                      <div key={item.recipe.id} className="relative group">
                        <div className="absolute top-4 right-4 z-20">
                          <div className={cn(
                            "px-4 py-2 rounded-2xl text-xs font-black text-white shadow-xl flex items-center gap-2 backdrop-blur-md",
                            item.matchScore >= 0.90 ? "bg-emerald-500/95" :
                            item.matchScore >= 0.70 ? "bg-blue-500/95" :
                            "bg-amber-500/95"
                          )}>
                            <Sparkles className="w-4 h-4" />
                            %{(item.matchScore * 100).toFixed(0)} Eşleşme
                          </div>
                        </div>
                        <RecipeCard recipe={item.recipe} index={idx} />
                      </div>
                    ))}
                  </div>
                </motion.div>
              ) : hasRequested && recommendations && recommendations.length === 0 ? (
                <motion.div
                  key="empty"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="flex flex-col items-center justify-center py-20 text-center"
                >
                  <div className="w-24 h-24 bg-muted rounded-[2rem] flex items-center justify-center mb-6">
                    <Info className="w-12 h-12 text-muted-foreground" />
                  </div>
                  <h3 className="text-3xl font-bold tracking-tight text-foreground mb-4">Uygun Tarif Bulunamadı</h3>
                  <p className="text-muted-foreground text-lg max-w-md">
                    Seçtiğiniz modda dolabınızdaki malzemelerle eşleşen bir tarif bulamadık. Lütfen farklı bir analiz modu seçin.
                  </p>
                </motion.div>
              ) : null}
            </AnimatePresence>
          </section>

        </div>
        <Footer />
      </main>
    </div>
  );
};

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/shared/ui";
import { 
  ArrowRight, 
  ArrowLeft, 
  Leaf, 
  Salad, 
  Flame, 
  WheatOff, 
  Dna, 
  Milk, 
  Egg, 
  Nut, 
  Fish, 
  Sprout, 
  Wheat,
  Check,
  UtensilsCrossed,
  Sparkles,
  Loader2,
  Search,
  X,
  Apple,
  Beef,
  Coffee,
  Grape,
  Camera,
  User,
  Calendar,
  ChevronLeft,
  ChevronRight
} from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { dietaryPreferenceApi } from "@/entities/dietary-preference/api/dietaryPreferenceApi";
import { allergyApi } from "@/entities/allergy/api/allergyApi";
import { userApi } from "@/entities/user/api/userApi";
import { pantryApi } from "@/entities/pantry/api/pantryApi";
import { useDebouncedValue } from '@/shared/lib/hooks/useDebouncedValue';
import { useSessionStore } from "@/entities/session";

const getDietIcon = (name: string) => {
  const n = name.toLowerCase();
  if (n.includes("vegan")) return <Leaf />;
  if (n.includes("vejetaryen") || n.includes("vegetarian")) return <Salad />;
  if (n.includes("keto")) return <Flame />;
  if (n.includes("glüten") || n.includes("gluten")) return <WheatOff />;
  if (n.includes("paleo")) return <Dna />;
  return <UtensilsCrossed />;
};

const getAllergyIcon = (name: string) => {
  const n = name.toLowerCase();
  if (n.includes("süt") || n.includes("milk")) return <Milk />;
  if (n.includes("yumurta") || n.includes("egg")) return <Egg />;
  if (n.includes("fıstık") || n.includes("peanut") || n.includes("nut")) return <Nut />;
  if (n.includes("deniz") || n.includes("fish") || n.includes("sea")) return <Fish />;
  if (n.includes("soya") || n.includes("soy")) return <Sprout />;
  if (n.includes("buğday") || n.includes("wheat")) return <Wheat />;
  return <Sparkles />;
};

const getCategoryIcon = (categoryName: string) => {
  const n = categoryName.toLowerCase();
  if (n.includes("sebze")) return <Leaf className="w-4 h-4" />;
  if (n.includes("meyve")) return <Apple className="w-4 h-4" />;
  if (n.includes("et") || n.includes("tavuk")) return <Beef className="w-4 h-4" />;
  if (n.includes("deniz")) return <Fish className="w-4 h-4" />;
  if (n.includes("süt") || n.includes("peynir")) return <Milk className="w-4 h-4" />;
  if (n.includes("tahıl") || n.includes("un")) return <Wheat className="w-4 h-4" />;
  if (n.includes("baharat")) return <Flame className="w-4 h-4" />;
  if (n.includes("içecek")) return <Coffee className="w-4 h-4" />;
  if (n.includes("atıştırmalık")) return <Grape className="w-4 h-4" />;
  return <Sparkles className="w-4 h-4" />;
};

export default function PreferencesPage() {
  const [step, setStep] = useState(1);
  const [username, setUsername] = useState("");
  const [usernameError, setUsernameError] = useState("");
  const [birthDate, setBirthDate] = useState("");
  const [profileImage, setProfileImage] = useState<string | null>(null);
  const [profileFile, setProfileFile] = useState<File | null>(null);
  
  const [selectedDiets, setSelectedDiets] = useState<string[]>([]);
  const [selectedAllergies, setSelectedAllergies] = useState<string[]>([]);
  const [selectedDislikedIngredients, setSelectedDislikedIngredients] = useState<{id: string, name: string}[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedPopularCategory, setSelectedPopularCategory] = useState<string>("Tümü");
  const [isFinishing, setIsFinishing] = useState(false);
  const navigate = useNavigate();
  const user = useSessionStore((state) => state.user);
  const initializeSession = useSessionStore((state) => state.initialize);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProfileFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const { data: diets, isLoading: isLoadingDiets } = useQuery({
    queryKey: ["dietary-preferences"],
    queryFn: dietaryPreferenceApi.getList,
    staleTime: Infinity,
  });

  const { data: allergies, isLoading: isLoadingAllergies } = useQuery({
    queryKey: ["allergy-restrictions"],
    queryFn: allergyApi.getList,
    staleTime: Infinity,
  });

  const { data: popularDislikes, isLoading: isLoadingPopular } = useQuery({
    queryKey: ["popular-dislikes"],
    queryFn: pantryApi.getPopularDislikes,
    staleTime: Infinity,
  });

  const debouncedSearchQuery = useDebouncedValue(searchQuery, 300);

  const { data: searchResults, isLoading: isLoadingSearch } = useQuery({
    queryKey: ["search-ingredients", debouncedSearchQuery],
    queryFn: () => pantryApi.searchIngredients(debouncedSearchQuery),
    enabled: debouncedSearchQuery.length >= 2,
  });

  const scrollRef = React.useRef<HTMLDivElement>(null);

  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const { current } = scrollRef;
      const scrollAmount = direction === 'left' ? -current.offsetWidth : current.offsetWidth;
      current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    }
  };

  const toggleAllergy = (id: string) => {
    setSelectedAllergies(prev => 
      prev.includes(id) ? prev.filter(a => a !== id) : [...prev, id]
    );
  };

  const toggleDiet = (id: string) => {
    setSelectedDiets(prev => {
      if (id === "none") return [];
      return prev.includes(id) ? prev.filter(d => d !== id) : [...prev, id];
    });
  };

  const toggleDislikedIngredient = (id: string, name: string) => {
    setSelectedDislikedIngredients(prev => 
      prev.some(i => i.id === id) 
        ? prev.filter(i => i.id !== id) 
        : [...prev, { id, name }]
    );
  };

  const popularCategories = popularDislikes 
    ? ["Tümü", ...Array.from(new Set(popularDislikes.map(i => i.categoryName)))]
    : ["Tümü"];

  const filteredPopular = popularDislikes
    ? popularDislikes.filter(i => selectedPopularCategory === "Tümü" || i.categoryName === selectedPopularCategory)
    : [];

  const handleFinish = async () => {
    setIsFinishing(true);
    try {
      await userApi.updateProfile({
        username: username || undefined,
        birthDate: birthDate || undefined,
        profileImage: profileFile ?? undefined,
      });

      // 2. Diyet tercihini kaydet
      await userApi.updateDietaryPreferences({ dietaryPreferenceIds: selectedDiets });
      
      // 2. Alerjileri kaydet
      await userApi.updateAllergies({ allergyRestrictionIds: selectedAllergies });

      // 3. Sevilmeyen malzemeleri kaydet
      const ingredientIds = selectedDislikedIngredients.map(i => i.id);
      await userApi.updateDislikedIngredients({ ingredientIds });

      await initializeSession();
      navigate("/home");
    } catch (error) {
      console.error("Tercihler kaydedilirken hata oluştu:", error);
    } finally {
      setIsFinishing(false);
    }
  };

  if (isLoadingDiets || isLoadingAllergies) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#fafafa] dark:bg-[#0a0a0a]">
        <Loader2 className="w-12 h-12 text-primary animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#fafafa] dark:bg-[#0a0a0a] font-outfit transition-colors duration-500 overflow-hidden relative">
      <div className="absolute top-0 left-0 w-full h-full pointer-events-none">
        <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-primary/10 rounded-full blur-[120px] dark:opacity-20" />
        <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-primary/10 rounded-full blur-[120px] dark:opacity-20" />
      </div>

      <div className="relative z-10 max-w-4xl mx-auto px-6 pt-12 pb-24 min-h-screen flex flex-col">
        <div className="flex justify-between items-center mb-12">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-xl text-foreground">OleAI Kişiselleştirme</span>
          </div>
          <div className="flex gap-2">
            {[1, 2, 3, 4].map((s) => (
              <div 
                key={s} 
                className={`h-1.5 rounded-full transition-all duration-500 ${
                  s === step ? "w-8 bg-primary" : "w-4 bg-muted"
                }`}
              />
            ))}
          </div>
        </div>

        <div className="flex-1">
          <AnimatePresence mode="wait">
            {step === 1 ? (
              <motion.div
                key="step1"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-12"
              >
                <div className="max-w-xl">
                  <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-4 leading-tight">
                    Seni daha yakından tanıyalım
                  </h1>
                  <p className="text-muted-foreground text-lg">
                    Profilini oluşturarak OleAI deneyimini sana özel hale getir.
                  </p>
                </div>

                <div className="flex flex-col md:flex-row gap-12 items-center">
                  {/* Profile Image Upload */}
                  <div className="relative group">
                    <div className="w-40 h-40 rounded-full border-4 border-white dark:border-neutral-800 shadow-2xl overflow-hidden bg-muted flex items-center justify-center relative">
                      {profileImage ? (
                        <img src={profileImage} alt="Profile" className="w-full h-full object-cover" />
                      ) : (
                        <User className="w-16 h-16 text-muted-foreground" />
                      )}
                      
                      <label className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                        <Camera className="w-8 h-8 text-white" />
                        <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                      </label>
                    </div>
                    <div className="absolute -bottom-2 -right-2 w-10 h-10 bg-primary rounded-full flex items-center justify-center border-4 border-[#fafafa] dark:border-[#0a0a0a] shadow-lg">
                      <Camera className="w-5 h-5 text-white" />
                    </div>
                  </div>

                  {/* Input Fields */}
                  <div className="flex-1 w-full space-y-6">
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-muted-foreground uppercase tracking-wider px-1">Kullanıcı Adı</label>
                      <div className="relative group">
                        <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground group-focus-within:text-primary transition-colors" />
                        <input 
                          type="text" 
                          value={username}
                          onChange={(e) => {
                            const val = e.target.value;
                            setUsername(val);
                            if (val.length > 0 && val.length < 3) setUsernameError("En az 3 karakter olmalıdır.");
                            else if (val.length > 50) setUsernameError("En fazla 50 karakter olabilir.");
                            else if (!/^[a-zA-Z0-9_]*$/.test(val)) setUsernameError("Sadece harf, rakam ve alt çizgi içerebilir.");
                            else setUsernameError("");
                          }}
                          placeholder="Örn: onuraydin"
                          className={`w-full h-14 pl-12 pr-4 rounded-2xl bg-card border-2 ${usernameError ? 'border-destructive' : 'border-transparent focus:border-primary'} focus:bg-background outline-none transition-all shadow-sm font-medium`}
                        />
                      </div>
                      {usernameError && <p className="text-sm text-destructive px-1">{usernameError}</p>}
                    </div>

                    <div className="space-y-2">
                      <div className="flex justify-between items-center px-1">
                        <label className="text-sm font-bold text-muted-foreground uppercase tracking-wider">Doğum Tarihi</label>
                        <span className="text-[10px] text-primary font-bold bg-primary/10 px-2 py-0.5 rounded-full">Min. 13 Yaş</span>
                      </div>
                      <div className="relative group">
                        <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground group-focus-within:text-primary transition-colors" />
                        <input 
                          type="date" 
                          value={birthDate}
                          max={new Date(new Date().setFullYear(new Date().getFullYear() - 13)).toISOString().split("T")[0]}
                          onChange={(e) => setBirthDate(e.target.value)}
                          className="w-full h-14 pl-12 pr-4 rounded-2xl bg-card border-2 border-transparent focus:border-primary focus:bg-background outline-none transition-all shadow-sm font-medium"
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </motion.div>
            ) : step === 2 ? (
              <motion.div
                key="step2"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-8"
              >
                <div className="max-w-xl">
                  <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-4 leading-tight">
                    Beslenme tarzını seç
                  </h1>
                  <p className="text-muted-foreground text-lg">
                    Sana en uygun tarifleri önermemiz için beslenme düzenini bilmemiz gerekiyor.
                  </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {diets?.filter(d => d.isActive).map((diet) => (
                    <motion.button
                      key={diet.id}
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      onClick={() => toggleDiet(diet.id)}
                      className={`relative flex flex-col items-start p-6 rounded-3xl border-2 transition-all text-left ${
                        selectedDiets.includes(diet.id) 
                          ? "border-primary bg-primary/5 shadow-xl shadow-primary/10" 
                          : "border-transparent bg-card shadow-sm hover:shadow-md"
                      }`}
                    >
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-4 transition-colors ${
                        selectedDiets.includes(diet.id) ? "bg-primary text-white" : "bg-muted dark:bg-neutral-800 text-primary"
                      }`}>
                        {getDietIcon(diet.name)}
                      </div>
                      <h3 className="font-bold text-xl mb-1 text-foreground">{diet.name}</h3>
                      <p className="text-sm text-muted-foreground line-clamp-2">{diet.description}</p>
                      
                      {selectedDiets.includes(diet.id) && (
                        <div className="absolute top-4 right-4 w-6 h-6 bg-primary rounded-full flex items-center justify-center">
                          <Check className="w-4 h-4 text-white" />
                        </div>
                      )}
                    </motion.button>
                  ))}
                  
                  <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => toggleDiet("none")}
                    className={`relative flex flex-col items-start p-6 rounded-3xl border-2 transition-all text-left ${
                      selectedDiets.length === 0 
                        ? "border-primary bg-primary/5 shadow-xl shadow-primary/10" 
                        : "border-transparent bg-card shadow-sm hover:shadow-md"
                    }`}
                  >
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-4 transition-colors ${
                      selectedDiets.length === 0 ? "bg-primary text-white" : "bg-muted dark:bg-neutral-800 text-primary"
                    }`}>
                      <UtensilsCrossed />
                    </div>
                    <h3 className="font-bold text-xl mb-1 text-foreground">Her Şeyi Yerim</h3>
                    <p className="text-sm text-muted-foreground">Herhangi bir beslenme kısıtlamam yok.</p>
                  </motion.button>
                </div>
              </motion.div>
            ) : step === 3 ? (
              <motion.div
                key="step3"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-8"
              >
                <div className="max-w-xl">
                  <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-4 leading-tight">
                    Alerjilerin var mı?
                  </h1>
                  <p className="text-muted-foreground text-lg">
                    Kullanmadığın veya alerjin olan malzemeleri seç, onları tariflerinden çıkaralım.
                  </p>
                </div>

                <div className="relative group">
                  <div 
                    ref={scrollRef}
                    className="overflow-x-auto pb-4 snap-x -mx-2 px-2 scroll-smooth [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]"
                  >
                    <div className="grid grid-rows-4 grid-flow-col auto-cols-[240px] md:auto-cols-[280px] gap-4 w-max">
                      {allergies?.filter(a => a.isActive).map((allergy) => (
                        <motion.button
                          key={allergy.id}
                          whileHover={{ scale: 1.02 }}
                          whileTap={{ scale: 0.98 }}
                          onClick={() => toggleAllergy(allergy.id)}
                          className={`relative snap-start flex flex-col items-start p-6 rounded-3xl border-2 transition-all text-left ${
                            selectedAllergies.includes(allergy.id)
                              ? "border-primary bg-primary/5 shadow-xl shadow-primary/10"
                              : "border-transparent bg-card shadow-sm hover:shadow-md"
                          }`}
                        >
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-4 transition-colors ${
                            selectedAllergies.includes(allergy.id) ? "bg-primary text-white" : "bg-muted dark:bg-neutral-800 text-primary"
                          }`}>
                            {getAllergyIcon(allergy.name)}
                          </div>
                          <h3 className="font-bold text-lg mb-1 text-foreground">{allergy.name}</h3>
                          {allergy.description && (
                            <p className="text-xs text-muted-foreground line-clamp-2">{allergy.description}</p>
                          )}
                          
                          {selectedAllergies.includes(allergy.id) && (
                            <div className="absolute top-4 right-4 w-6 h-6 bg-primary rounded-full flex items-center justify-center">
                              <Check className="w-4 h-4 text-white" />
                            </div>
                          )}
                        </motion.button>
                      ))}
                    </div>
                  </div>

                  <button 
                    onClick={() => scroll('left')}
                    className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-1/2 w-12 h-12 bg-background border-2 border-border rounded-full flex items-center justify-center shadow-lg text-foreground hover:border-primary hover:text-primary transition-all opacity-0 group-hover:opacity-100 disabled:opacity-0 z-10"
                  >
                    <ChevronLeft className="w-6 h-6" />
                  </button>
                  <button 
                    onClick={() => scroll('right')}
                    className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-1/2 w-12 h-12 bg-background border-2 border-border rounded-full flex items-center justify-center shadow-lg text-foreground hover:border-primary hover:text-primary transition-all opacity-0 group-hover:opacity-100 disabled:opacity-0 z-10"
                  >
                    <ChevronRight className="w-6 h-6" />
                  </button>
                </div>
              </motion.div>
            ) : step === 4 ? (
              <motion.div
                key="step4"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-8"
              >
                <div className="max-w-xl">
                  <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-4 leading-tight">
                    Sevmediğin malzemeler
                  </h1>
                  <p className="text-muted-foreground text-lg">
                    Tadı hoşuna gitmeyen veya görmek istemediğin malzemeleri buraya ekleyebilirsin.
                  </p>
                </div>

                <div className="space-y-6">
                  <div className="relative group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-6 h-6 text-muted-foreground group-focus-within:text-primary transition-colors" />
                    <input 
                      type="text"
                      placeholder="Malzeme ara... (örn: Mantar, Soğan)"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="w-full h-16 pl-14 pr-6 rounded-2xl bg-card border-2 border-transparent focus:border-primary focus:bg-background outline-none text-lg transition-all shadow-sm"
                    />
                    
                    <AnimatePresence>
                      {searchQuery.length >= 2 && (
                        <motion.div 
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          exit={{ opacity: 0, y: 10 }}
                          className="absolute top-full left-0 w-full mt-2 bg-card rounded-2xl shadow-2xl border border-muted z-50 max-h-60 overflow-y-auto"
                        >
                          {isLoadingSearch ? (
                            <div className="p-8 text-center text-muted-foreground">
                              <Loader2 className="w-6 h-6 animate-spin mx-auto mb-2" />
                              Aranıyor...
                            </div>
                          ) : searchResults && searchResults.length > 0 ? (
                            searchResults.map((ing) => (
                              <button
                                key={ing.masterIngredientId}
                                onClick={() => {
                                  toggleDislikedIngredient(ing.masterIngredientId, ing.displayName);
                                  setSearchQuery("");
                                }}
                                className="w-full flex items-center gap-3 p-4 hover:bg-muted/50 transition-colors text-left border-b border-muted/30 last:border-0"
                              >
                                <div className="w-10 h-10 bg-primary/10 rounded-xl flex items-center justify-center text-primary group-hover/item:bg-primary group-hover/item:text-white transition-colors">
                                  {getCategoryIcon(ing.categoryName)}
                                </div>
                                <div className="flex flex-col">
                                  <span className="font-bold text-foreground group-hover/item:text-primary transition-colors">
                                    {ing.displayName}
                                  </span>
                                  <span className="text-xs text-muted-foreground flex items-center gap-1">
                                    {ing.categoryName} {ing.isAlias && <span className="w-1 h-1 bg-muted-foreground rounded-full mx-1" />} {ing.isAlias && "Eşanlamlı"}
                                  </span>
                                </div>
                              </button>
                            ))
                          ) : (
                            <div className="p-8 text-center text-muted-foreground">
                              Sonuç bulunamadı.
                            </div>
                          )}
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>

                  <div className="flex flex-wrap gap-2 min-h-[50px]">
                    <AnimatePresence>
                      {selectedDislikedIngredients.map((ing) => (
                        <motion.div
                          key={ing.id}
                          initial={{ scale: 0.8, opacity: 0 }}
                          animate={{ scale: 1, opacity: 1 }}
                          exit={{ scale: 0.8, opacity: 0 }}
                          className="flex items-center gap-2 px-4 py-2 bg-primary/10 text-primary border border-primary/20 rounded-full font-bold"
                        >
                          {ing.name}
                          <button 
                            onClick={() => toggleDislikedIngredient(ing.id, ing.name)}
                            className="hover:text-destructive transition-colors"
                          >
                            <X className="w-4 h-4" />
                          </button>
                        </motion.div>
                      ))}
                    </AnimatePresence>
                  </div>

                  <div className="space-y-4">
                    <div className="flex justify-between items-end">
                      <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-2">
                        <Flame className="w-4 h-4" /> Popüler Seçimler
                      </h3>
                      {popularCategories.length > 1 && (
                        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                          {popularCategories.map(cat => (
                            <button
                              key={cat}
                              onClick={() => setSelectedPopularCategory(cat)}
                              className={`text-xs font-bold px-3 py-1.5 rounded-full transition-colors whitespace-nowrap ${
                                selectedPopularCategory === cat
                                  ? "bg-foreground text-background"
                                  : "bg-muted text-muted-foreground hover:bg-muted/80"
                              }`}
                            >
                              {cat}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    
                    <div className="flex flex-wrap gap-3">
                      {isLoadingPopular ? (
                        <div className="flex items-center gap-2 text-muted-foreground">
                          <Loader2 className="w-4 h-4 animate-spin" /> Yükleniyor...
                        </div>
                      ) : filteredPopular.length > 0 ? (
                        filteredPopular.map((item) => (
                          <button
                            key={item.id}
                            onClick={() => toggleDislikedIngredient(item.id, item.name)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border-2 font-medium shadow-sm transition-all group/pop ${
                              selectedDislikedIngredients.some(i => i.id === item.id)
                                ? "bg-primary/10 border-primary text-primary"
                                : "bg-card border-transparent hover:border-primary/50 text-foreground"
                            }`}
                          >
                            <span className={`${selectedDislikedIngredients.some(i => i.id === item.id) ? "text-primary" : "text-primary group-hover/pop:scale-110"} transition-transform`}>
                              {getCategoryIcon(item.categoryName)}
                            </span>
                            {item.name}
                          </button>
                        ))
                      ) : (
                        <div className="text-sm text-muted-foreground">Bu kategoride malzeme bulunamadı.</div>
                      )}
                    </div>
                  </div>
                </div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>

        <div className="mt-12 flex justify-between items-center">
          {step > 1 ? (
            <Button 
              variant="outline"
              disabled={isFinishing}
              onClick={() => setStep(step - 1)}
              className="h-14 px-8 rounded-2xl gap-2 font-bold"
            >
              <ArrowLeft className="w-5 h-5" /> Geri
            </Button>
          ) : (
            <div />
          )}

          <Button 
            disabled={(step === 1 && (!username || !birthDate || !!usernameError)) || isFinishing}
            onClick={() => step < 4 ? setStep(step + 1) : handleFinish()}
            className="h-14 px-10 rounded-2xl bg-primary hover:bg-primary/90 text-white font-bold text-lg shadow-xl shadow-primary/20 gap-2 group transition-all"
          >
            {isFinishing ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                {step === 4 ? "Tamamla" : "Devam Et"}
                <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

