source:
import { Footer } from '@/widgets/footer';
import { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { motion, AnimatePresence } from "framer-motion";
import {
  User,
  BarChart2,
  Leaf,
  Settings,
  Mail,
  Calendar,
  ShieldCheck,
  ShieldAlert,
  Clock,
  Camera,
  BookOpen,
  ThumbsDown,
  KeyRound,
  MessageSquare,
} from "lucide-react";
import { Sidebar } from "@/widgets/sidebar/ui/Sidebar";
import { DashboardHeader } from "@/widgets/dashboard-header/ui/DashboardHeader";
import { UserStatistics } from "@/widgets/user-statistics/ui/UserStatistics";
import { ProfileRecipesTab } from "@/widgets/profile-recipes";
import { ProfileCommentsTab } from "@/widgets/profile-comments";
import { 
  EditProfileForm, 
  DietaryPreferencesEditor, 
  AllergiesEditor, 
  ChangePasswordForm, 
  DislikedIngredientsEditor 
} from "@/features/edit-profile";
import { userApi } from "@/entities/user";
import { useSessionStore } from "@/entities/session";

const TABS = [
  { id: "overview", label: "Genel Bakış", icon: BarChart2 },
  { id: "recipes", label: "Tariflerim", icon: BookOpen },
  { id: "comments", label: "Yorumlarım", icon: MessageSquare },
  { id: "edit", label: "Profili Düzenle", icon: User },
  { id: "nutrition", label: "Beslenme", icon: Leaf },
  { id: "account", label: "Ayarlar", icon: Settings },
] as const;

type TabId = (typeof TABS)[number]["id"];

export default function ProfilePage() {
  const location = useLocation();
  const [activeTab, setActiveTab] = useState<TabId>("overview");

  useEffect(() => {
    if (location.state?.activeTab) {
      setActiveTab(location.state.activeTab as TabId);
    }
  }, [location.state]);

  const sessionUser = useSessionStore((s) => s.user);

  const { data: profile, isLoading } = useQuery({
    queryKey: ["user-profile"],
    queryFn: userApi.getProfile,
    staleTime: 1000 * 60 * 2,
  });

  const displayName = profile
    ? `${profile.firstName} ${profile.lastName}`.trim() || profile.username
    : sessionUser?.username || sessionUser?.email?.split("@")[0] || "Kullanıcı";

  const avatarLetter = (displayName?.[0] || "K").toUpperCase();
  const avatarUrl = profile?.profileImageUrl ?? sessionUser?.profileImageUrl;
  const memberSince = profile?.createdDate
    ? new Date(profile.createdDate).toLocaleDateString("tr-TR", { year: "numeric", month: "long" })
    : null;

  return (
    <div className="min-h-screen bg-[#fafafa] dark:bg-[#0a0a0a] transition-colors duration-500">
      <Sidebar />

      <main className="lg:ml-72 min-h-screen flex flex-col">
        <DashboardHeader />

        <div className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-8 pb-16">

          {/* ── Hero / Profile Header ── */}
          <section className="relative">
            {/* Cover gradient */}
            <div className="h-64 sm:h-80 rounded-b-[3rem] bg-gradient-to-br from-primary/40 via-violet-500/30 to-rose-500/30 dark:from-primary/30 dark:via-violet-500/20 dark:to-rose-500/20 overflow-hidden shadow-sm">
              <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-primary/30 via-transparent to-transparent" />
              {/* subtle pattern */}
              <svg className="absolute bottom-0 right-0 opacity-[0.15] w-96 h-96 text-primary mix-blend-overlay" viewBox="0 0 200 200" fill="currentColor">
                <circle cx="160" cy="160" r="80" />
                <circle cx="40" cy="40" r="50" />
              </svg>
            </div>

            {/* Avatar + info */}
            <div className="px-6 sm:px-12 pb-8">
              <div className="flex flex-col sm:flex-row sm:items-end gap-6 -mt-24 sm:-mt-28 relative z-10">
                {/* Avatar */}
                <div className="relative shrink-0 group">
                  {isLoading ? (
                    <div className="w-36 h-36 sm:w-48 sm:h-48 rounded-full bg-muted animate-pulse border-[6px] border-background shadow-2xl" />
                  ) : avatarUrl ? (
                    <img
                      src={avatarUrl}
                      alt="Profil"
                      className="w-36 h-36 sm:w-48 sm:h-48 rounded-[2.5rem] object-cover border-[6px] border-background shadow-2xl group-hover:scale-[1.02] transition-transform duration-300"
                    />
                  ) : (
                    <div className="w-36 h-36 sm:w-48 sm:h-48 rounded-[2.5rem] bg-gradient-to-br from-primary to-violet-600 border-[6px] border-background shadow-2xl flex items-center justify-center text-white font-black text-5xl sm:text-7xl group-hover:scale-[1.02] transition-transform duration-300">
                      {avatarLetter}
                    </div>
                  )}
                  <button
                    onClick={() => setActiveTab("edit")}
                    className="absolute -bottom-2 -right-2 sm:-bottom-4 sm:-right-4 w-12 h-12 rounded-2xl bg-background border-2 border-muted shadow-xl flex items-center justify-center hover:bg-primary hover:text-white hover:border-primary transition-all group-hover:scale-110"
                    title="Profil fotoğrafını değiştir"
                  >
                    <Camera className="w-5 h-5" />
                  </button>
                </div>

                {/* Name & meta */}
                <div className="flex-1 min-w-0 sm:pb-4">
                  {isLoading ? (
                    <div className="space-y-3">
                      <div className="h-10 w-64 rounded-xl bg-muted animate-pulse" />
                      <div className="h-5 w-48 rounded-lg bg-muted animate-pulse" />
                    </div>
                  ) : (
                    <>
                      <div className="flex items-baseline gap-3 flex-wrap">
                        <h1 className="text-3xl sm:text-5xl font-black text-foreground truncate tracking-tight">
                          {displayName}
                        </h1>
                        {profile?.username && (
                          <span className="text-xl sm:text-2xl font-bold text-muted-foreground/60">
                            @{profile.username}
                          </span>
                        )}
                      </div>
                      <div className="flex flex-wrap items-center gap-4 mt-3">
                        <span className="text-sm sm:text-base font-bold text-muted-foreground/90 flex items-center gap-1.5">
                          <Mail className="w-4 h-4" />
                          {profile?.email ?? sessionUser?.email}
                        </span>
                        {memberSince && (
                          <span className="text-sm text-muted-foreground flex items-center gap-1.5">
                            <Clock className="w-3.5 h-3.5" />
                            {memberSince}'dan beri üye
                          </span>
                        )}
                        {profile?.isEmailVerified && (
                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 text-xs font-bold">
                            <ShieldCheck className="w-3 h-3" /> Doğrulandı
                          </span>
                        )}
                      </div>

                      {/* Diyet + Alerji badges */}
                      {(profile?.dietaryPreferences.length ?? 0) > 0 || (profile?.allergies.length ?? 0) > 0 ? (
                        <div className="flex flex-wrap gap-1.5 mt-3">
                          {profile?.dietaryPreferences.slice(0, 3).map((p) => (
                            <span key={p.id} className="px-2.5 py-1 rounded-xl bg-primary/10 text-primary text-xs font-bold flex items-center gap-1">
                              <Leaf className="w-3 h-3" /> {p.name}
                            </span>
                          ))}
                          {profile?.allergies.slice(0, 2).map((a) => (
                            <span key={a.id} className="px-2.5 py-1 rounded-xl bg-primary/10 text-primary text-xs font-bold flex items-center gap-1">
                              <ShieldAlert className="w-3 h-3" /> {a.name}
                            </span>
                          ))}
                          {((profile?.dietaryPreferences.length ?? 0) + (profile?.allergies.length ?? 0)) > 5 && (
                            <span className="px-2.5 py-1 rounded-xl bg-muted/60 text-muted-foreground text-xs font-bold">
                              +{((profile?.dietaryPreferences.length ?? 0) + (profile?.allergies.length ?? 0)) - 5} daha
                            </span>
                          )}
                        </div>
                      ) : null}
                    </>
                  )}
                </div>

                {/* Edit shortcut button */}
                <button
                  onClick={() => setActiveTab("edit")}
                  className="shrink-0 h-12 px-6 rounded-2xl border-2 border-muted/60 font-bold text-sm hover:bg-primary hover:text-white hover:border-primary hover:shadow-xl transition-all sm:self-end"
                >
                  Profili Düzenle
                </button>
              </div>
            </div>
          </section>

          {/* ── Tabs ── */}
          <div className="px-6 sm:px-12 mt-6 mb-8">
            <div className="flex gap-2 p-2 rounded-full bg-muted/30 border border-muted/50 w-full overflow-x-auto scrollbar-hide shadow-sm backdrop-blur-sm">
              {TABS.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`relative flex items-center gap-2.5 px-6 py-3 rounded-full text-sm font-bold transition-all duration-300 whitespace-nowrap flex-1 sm:flex-none justify-center
                    ${activeTab === tab.id
                      ? "text-white bg-primary shadow-lg shadow-primary/20 scale-[1.02]"
                      : "text-muted-foreground hover:text-foreground hover:bg-muted/80 hover:scale-[1.02]"
                    }`}
                >
                  <tab.icon className="w-4 h-4" />
                  <span>{tab.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* ── Tab Content ── */}
          <div className="mt-12 px-6 sm:px-12">
            <AnimatePresence mode="wait">
              {activeTab === "overview" && (
                <motion.div
                  key="overview"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.2 }}
                  className="space-y-12"
                >
                  {/* Stats */}
                  <div>
                    <h2 className="text-xl font-black text-foreground mb-6 flex items-center gap-2">
                      <BarChart2 className="w-6 h-6 text-primary" />
                      Aktivite İstatistikleri
                    </h2>
                    <UserStatistics />
                  </div>

                  {/* Summary cards (Bento Box style) */}
                  {profile && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {/* Dietary */}
                      <div className="group relative p-8 rounded-[2rem] bg-card border-2 border-muted/30 shadow-sm hover:shadow-xl hover:border-primary/30 transition-all duration-300 flex flex-col">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-bl-full -z-0" />
                        <div className="flex items-center justify-between mb-6 relative z-10">
                          <div className="w-12 h-12 rounded-2xl bg-primary/10 flex items-center justify-center">
                            <Leaf className="w-6 h-6 text-primary" />
                          </div>
                          <button
                            onClick={() => setActiveTab("nutrition")}
                            className="px-4 py-2 rounded-xl bg-muted/50 text-sm font-bold text-foreground hover:bg-primary hover:text-white transition-colors"
                          >
                            Düzenle
                          </button>
                        </div>
                        <h3 className="text-xl font-black mb-4 relative z-10">Beslenme Tercihleri</h3>
                        {profile.dietaryPreferences.length === 0 ? (
                          <p className="text-muted-foreground font-medium flex-1">Herhangi bir beslenme kısıtlaman bulunmuyor.</p>
                        ) : (
                          <div className="flex flex-wrap gap-2 relative z-10">
                            {profile.dietaryPreferences.map((p) => (
                              <span key={p.id} className="px-4 py-2 rounded-xl bg-primary/10 text-primary text-sm font-bold border border-primary/20">
                                {p.name}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>

                      {/* Allergies */}
                      <div className="group relative p-8 rounded-[2rem] bg-card border-2 border-muted/30 shadow-sm hover:shadow-xl hover:border-primary/30 transition-all duration-300 flex flex-col">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-bl-full -z-0" />
                        <div className="flex items-center justify-between mb-6 relative z-10">
                          <div className="w-12 h-12 rounded-2xl bg-primary/10 flex items-center justify-center">
                            <ShieldAlert className="w-6 h-6 text-primary" />
                          </div>
                          <button
                            onClick={() => setActiveTab("nutrition")}
                            className="px-4 py-2 rounded-xl bg-muted/50 text-sm font-bold text-foreground hover:bg-primary hover:text-white transition-colors"
                          >
                            Düzenle
                          </button>
                        </div>
                        <h3 className="text-xl font-black mb-4 relative z-10">Alerjiler</h3>
                        {profile.allergies.length === 0 ? (
                          <p className="text-muted-foreground font-medium flex-1">Kayıtlı bir gıda alerjin bulunmuyor.</p>
                        ) : (
                          <div className="flex flex-wrap gap-2 relative z-10">
                            {profile.allergies.map((a) => (
                              <span key={a.id} className="px-4 py-2 rounded-xl bg-primary/10 text-primary text-sm font-bold border border-primary/20">
                                {a.name}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>

                      {/* Disliked Ingredients */}
                      <div className="group relative p-8 rounded-[2rem] bg-card border-2 border-muted/30 shadow-sm hover:shadow-xl hover:border-primary/30 transition-all duration-300 flex flex-col md:col-span-2">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-bl-full -z-0" />
                        <div className="flex items-center justify-between mb-6 relative z-10">
                          <div className="w-12 h-12 rounded-2xl bg-primary/10 flex items-center justify-center">
                            <ThumbsDown className="w-6 h-6 text-primary" />
                          </div>
                          <button
                            onClick={() => setActiveTab("nutrition")}
                            className="px-4 py-2 rounded-xl bg-muted/50 text-sm font-bold text-foreground hover:bg-primary hover:text-white transition-colors"
                          >
                            Düzenle
                          </button>
                        </div>
                        <h3 className="text-xl font-black mb-4 relative z-10">Sevilmeyen Malzemeler</h3>
                        {profile.dislikedIngredients.length === 0 ? (
                          <p className="text-muted-foreground font-medium flex-1">Sevilmeyen bir malzeme bulunmuyor.</p>
                        ) : (
                          <div className="flex flex-wrap gap-2 relative z-10">
                            {profile.dislikedIngredients.map((d) => (
                              <span key={d.id} className="px-4 py-2 rounded-xl bg-primary/10 text-primary text-sm font-bold border border-primary/20">
                                {d.name}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </motion.div>
              )}

              {activeTab === "recipes" && (
                <motion.div
                  key="recipes"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.2 }}
                >
                  <ProfileRecipesTab />
                </motion.div>
              )}

              {activeTab === "comments" && (
                <motion.div
                  key="comments"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.2 }}
                >
                  <ProfileCommentsTab />
                </motion.div>
              )}

              {activeTab === "edit" && (
                <motion.div
                  key="edit"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.2 }}
                  className="p-6 sm:p-8 rounded-[2rem] bg-card border border-muted/40 shadow-sm"
                >
                  <h2 className="text-lg font-black text-foreground mb-6 flex items-center gap-2">
                    <User className="w-5 h-5 text-primary" />
                    Kişisel Bilgiler
                  </h2>
                  {isLoading ? (
                    <div className="space-y-4">
                      {[1, 2, 3, 4].map((i) => (
                        <div key={i} className="h-12 rounded-xl bg-muted/50 animate-pulse" />
                      ))}
                    </div>
                  ) : profile ? (
                    <EditProfileForm profile={profile} />
                  ) : null}
                </motion.div>
              )}

              {activeTab === "nutrition" && (
                <motion.div
                  key="nutrition"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.2 }}
                  className="space-y-6"
                >
                  {/* Dietary */}
                  <div className="p-6 sm:p-8 rounded-[2rem] bg-card border border-muted/40 shadow-sm">
                    <h2 className="text-lg font-black text-foreground mb-1 flex items-center gap-2">
                      <Leaf className="w-5 h-5 text-primary" />
                      Beslenme Tercihleri
                    </h2>
                    <div className="mt-5">
                      {profile ? (
                        <DietaryPreferencesEditor currentPreferences={profile.dietaryPreferences} />
                      ) : (
                        <div className="grid grid-cols-3 gap-3">
                          {[1, 2, 3, 4, 5, 6].map((i) => (
                            <div key={i} className="h-14 rounded-2xl bg-muted/50 animate-pulse" />
                          ))}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Allergies */}
                  <div className="p-6 sm:p-8 rounded-[2rem] bg-card border border-muted/40 shadow-sm">
                    <h2 className="text-lg font-black text-foreground mb-1 flex items-center gap-2">
                      <ShieldAlert className="w-5 h-5 text-primary" />
                      Alerji ve Gıda Kısıtlamaları
                    </h2>
                    <div className="mt-5">
                      {profile ? (
                        <AllergiesEditor currentAllergies={profile.allergies} />
                      ) : (
                        <div className="grid grid-cols-3 gap-3">
                          {[1, 2, 3, 4, 5, 6].map((i) => (
                            <div key={i} className="h-14 rounded-2xl bg-muted/50 animate-pulse" />
                          ))}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Disliked Ingredients */}
                  <div className="p-6 sm:p-8 rounded-[2rem] bg-card border border-muted/40 shadow-sm">
                    <h2 className="text-lg font-black text-foreground mb-1 flex items-center gap-2">
                      <ThumbsDown className="w-5 h-5 text-primary" />
                      Sevilmeyen Malzemeler
                    </h2>
                    <div className="mt-5">
                      {profile ? (
                        <DislikedIngredientsEditor currentDisliked={profile.dislikedIngredients} />
                      ) : (
                        <div className="grid grid-cols-3 gap-3">
                          {[1, 2, 3, 4, 5, 6].map((i) => (
                            <div key={i} className="h-14 rounded-2xl bg-muted/50 animate-pulse" />
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                </motion.div>
              )}

              {activeTab === "account" && (
                <motion.div
                  key="account"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.2 }}
                  className="p-6 sm:p-8 rounded-[2rem] bg-card border border-muted/40 shadow-sm space-y-6"
                >
                  <h2 className="text-lg font-black text-foreground flex items-center gap-2">
                    <Settings className="w-5 h-5 text-primary" />
                    Hesap Bilgileri
                  </h2>

                  <div className="space-y-1">
                    {[
                      {
                        label: "E-posta Adresi",
                        icon: Mail,
                        value: profile?.email ?? sessionUser?.email,
                      },
                      {
                        label: "Doğum Tarihi",
                        icon: Calendar,
                        value: profile?.birthDate
                          ? new Date(profile.birthDate).toLocaleDateString("tr-TR", {
                              day: "numeric", month: "long", year: "numeric",
                            })
                          : "Belirtilmedi",
                      },
                      {
                        label: "Üyelik Tarihi",
                        icon: Clock,
                        value: profile?.createdDate
                          ? new Date(profile.createdDate).toLocaleDateString("tr-TR", {
                              day: "numeric", month: "long", year: "numeric",
                            })
                          : null,
                      },
                      {
                        label: "E-posta Doğrulama",
                        icon: ShieldCheck,
                        value: profile?.isEmailVerified ? "Doğrulandı ✓" : "Doğrulanmadı",
                        valueClass: profile?.isEmailVerified
                          ? "text-emerald-600 dark:text-emerald-400 font-bold"
                          : "text-amber-600 dark:text-amber-400 font-bold",
                      },
                    ].map((row) => (
                      row.value && (
                        <div
                          key={row.label}
                          className="flex items-center justify-between py-4 border-b border-muted/40 last:border-0"
                        >
                          <div className="flex items-center gap-3 text-muted-foreground">
                            <row.icon className="w-4 h-4" />
                            <span className="text-sm font-medium">{row.label}</span>
                          </div>
                          <span className={`text-sm font-semibold text-foreground ${row.valueClass ?? ""}`}>
                            {row.value}
                          </span>
                        </div>
                      )
                    ))}
                  </div>

                  {/* Change Password */}
                  <div className="pt-6 mt-6 border-t border-muted/40">
                    <h2 className="text-lg font-black text-foreground flex items-center gap-2 mb-6">
                      <KeyRound className="w-5 h-5 text-primary" />
                      Şifre Değiştir
                    </h2>
                    <ChangePasswordForm />
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>
        <Footer />
      </main>
    </div>
  );
}

import { Footer } from '@/widgets/footer';
import { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useQuery } from "@tanstack/react-query";
import { recipeApi } from "@/entities/recipe/api/recipeApi";
import { useNavigate } from "react-router-dom";
import { Search, Sparkles, ChevronLeft, ChevronRight, SlidersHorizontal } from "lucide-react";
import { useDebounce } from "@/shared/hooks/useDebounce";

import { Sidebar } from "@/widgets/sidebar/ui/Sidebar";
import { DashboardHeader } from "@/widgets/dashboard-header/ui/DashboardHeader";
import { RecipeCard } from "@/widgets/recipe-card";

export const RecipesPage = () => {
  const navigate = useNavigate();
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const scrollCategories = (direction: 'left' | 'right') => {
    if (scrollContainerRef.current) {
      const scrollAmount = 300;
      scrollContainerRef.current.scrollBy({ left: direction === 'left' ? -scrollAmount : scrollAmount, behavior: 'smooth' });
    }
  };

  const [searchTerm, setSearchTerm] = useState("");
  const debouncedSearch = useDebounce(searchTerm, 500);
  const [page, setPage] = useState(0);
  const [size, setSize] = useState(12);
  const [showFilters, setShowFilters] = useState(false);
  const [sortBy, setSortBy] = useState("Popular");

  // Seçili Filtreler (Sadece UI'da Gözüken)
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>(undefined);
  const [selectedDifficulty, setSelectedDifficulty] = useState<number | undefined>(undefined);
  const [selectedTime, setSelectedTime] = useState<number | undefined>(undefined);
  const [selectedTag, setSelectedTag] = useState<number | undefined>(undefined);

  // Uygulanmış Filtreler (API'ye Gönderilen)
  const [appliedCategory, setAppliedCategory] = useState<number | undefined>(undefined);
  const [appliedDifficulty, setAppliedDifficulty] = useState<number | undefined>(undefined);
  const [appliedTime, setAppliedTime] = useState<number | undefined>(undefined);
  const [appliedTag, setAppliedTag] = useState<number | undefined>(undefined);
  const [selectedRating, setSelectedRating] = useState<number | undefined>(undefined);
  const [appliedRating, setAppliedRating] = useState<number | undefined>(undefined);

  const handleApplyFilters = () => {
    setAppliedCategory(selectedCategory);
    setAppliedDifficulty(selectedDifficulty);
    setAppliedTime(selectedTime);
    setAppliedTag(selectedTag);
    setAppliedRating(selectedRating);
    setShowFilters(false);
  };

  const handleClearFilters = () => {
    setSelectedCategory(undefined);
    setSelectedDifficulty(undefined);
    setSelectedTime(undefined);
    setSelectedTag(undefined);
    setSelectedRating(undefined);
    
    setAppliedCategory(undefined);
    setAppliedDifficulty(undefined);
    setAppliedTime(undefined);
    setAppliedTag(undefined);
    setAppliedRating(undefined);
  };

  // Filtreler için veriler
  const { data: categories } = useQuery({ queryKey: ["categories"], queryFn: recipeApi.getRecipeCategories });
  const { data: tags } = useQuery({ queryKey: ["tags"], queryFn: recipeApi.getRecipeTags });

  const { data, isLoading, isError } = useQuery({
    queryKey: ["recipes", "published", page, size, debouncedSearch, appliedCategory, appliedRating, appliedDifficulty, appliedTime, appliedTag, sortBy],
    queryFn: () => recipeApi.getPublishedRecipes(page, size, debouncedSearch || undefined, appliedCategory, appliedRating, appliedDifficulty, appliedTime, appliedTag, sortBy),
  });

  // Reset page when search, size or any APPLIED filter changes
  useEffect(() => {
    setPage(0);
  }, [debouncedSearch, size, appliedCategory, appliedDifficulty, appliedTime, appliedTag, appliedRating, sortBy]);

  return (
    <div className="min-h-screen bg-[#fafafa] dark:bg-[#0a0a0a] transition-colors duration-500">
      <Sidebar />
      <main className="lg:ml-72 min-h-screen flex flex-col">
        <DashboardHeader />
        
        <div className="flex-1 p-8 space-y-8 max-w-7xl mx-auto w-full animate-in fade-in slide-in-from-bottom-4 duration-500">
          {/* Header section */}
      <div className="flex flex-col lg:flex-row lg:items-center gap-4 w-full">
        <h1 className="text-3xl md:text-4xl font-black text-foreground whitespace-nowrap">Tarifleri Keşfet</h1>

        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
          <input
            type="text"
            placeholder="Tarif ara..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-12 pr-4 py-3 bg-card border-2 border-transparent focus:border-primary rounded-[1rem] outline-none transition-all shadow-sm font-medium"
          />
        </div>

        <div className="flex items-center gap-3 flex-shrink-0">
          <div className="relative">
            <select 
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="appearance-none pl-4 pr-10 py-3 bg-card border-2 border-transparent focus:border-primary rounded-[1rem] outline-none transition-all shadow-sm font-medium cursor-pointer"
            >
              <option value="Popular">Popüler</option>
              <option value="Newest">En Yeni</option>
              <option value="Highest Rated">En Çok Oylanan</option>
              <option value="Quickest">En Hızlı</option>
            </select>
            <ChevronRight className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground rotate-90 pointer-events-none" />
          </div>

          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center justify-center gap-2 px-4 py-3 rounded-[1rem] shadow-sm transition-colors font-medium border-2 ${
              showFilters 
                ? "bg-primary text-primary-foreground border-primary" 
                : "bg-card text-foreground border-transparent hover:bg-neutral-50 dark:hover:bg-neutral-800"
            }`}
          >
            <SlidersHorizontal className="w-5 h-5" />
            <span className="hidden sm:inline">Filtreler</span>
          </button>
        </div>
      </div>

      {/* Expanded Filters Panel (UI Only) */}
      <AnimatePresence>
        {showFilters && (
          <motion.div 
            initial={{ opacity: 0, height: 0, marginTop: 0 }}
            animate={{ opacity: 1, height: "auto", marginTop: 24 }}
            exit={{ opacity: 0, height: 0, marginTop: 0 }}
            className="overflow-hidden"
          >
            <div className="bg-card p-6 rounded-[2rem] shadow-sm border border-muted/30">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                {/* Rating Filter */}
                <div className="space-y-3">
                  <h3 className="font-bold text-foreground">Değerlendirme Puanı</h3>
                  <div className="flex flex-wrap gap-2">
                    <button 
                      onClick={() => setSelectedRating(undefined)}
                      className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${
                        selectedRating === undefined 
                          ? "bg-primary/10 text-primary border-2 border-primary/20" 
                          : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                      }`}
                    >
                      Tümü
                    </button>
                    {[
                      { label: "4+ Yıldız", val: 4 }, 
                      { label: "3+ Yıldız", val: 3 }, 
                      { label: "2+ Yıldız", val: 2 }
                    ].map(rating => (
                      <button 
                        key={rating.val}
                        onClick={() => setSelectedRating(rating.val)}
                        className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors flex items-center gap-1 ${
                          selectedRating === rating.val 
                            ? "bg-primary/10 text-primary border-2 border-primary/20" 
                            : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                        }`}
                      >
                        {rating.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Difficulty Filter */}
                <div className="space-y-3">
                  <h3 className="font-bold text-foreground">Zorluk</h3>
                  <div className="flex flex-wrap gap-2">
                    <button 
                      onClick={() => setSelectedDifficulty(undefined)}
                      className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${
                        selectedDifficulty === undefined ? "bg-primary/10 text-primary border-2 border-primary/20" : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                      }`}>Tümü</button>
                    {[
                      { label: "Kolay", val: 1 }, 
                      { label: "Orta", val: 2 }, 
                      { label: "Zor", val: 3 }
                    ].map(level => (
                      <button 
                        key={level.val}
                        onClick={() => setSelectedDifficulty(level.val)}
                        className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${
                          selectedDifficulty === level.val 
                            ? "bg-primary/10 text-primary border-2 border-primary/20" 
                            : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                        }`}
                      >
                        {level.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Cook Time Filter */}
                <div className="space-y-3">
                  <h3 className="font-bold text-foreground">Hazırlama Süresi</h3>
                  <div className="flex flex-wrap gap-2">
                    <button 
                      onClick={() => setSelectedTime(undefined)}
                      className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${
                        selectedTime === undefined ? "bg-primary/10 text-primary border-2 border-primary/20" : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                      }`}>Tümü</button>
                    {[
                      { label: "< 15 dk", val: 15 },
                      { label: "< 30 dk", val: 30 },
                      { label: "< 60 dk", val: 60 }
                    ].map(time => (
                      <button 
                        key={time.val}
                        onClick={() => setSelectedTime(time.val)}
                        className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${
                          selectedTime === time.val 
                            ? "bg-primary/10 text-primary border-2 border-primary/20" 
                            : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                        }`}
                      >
                        {time.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Dietary Preferences Filter (Tag) */}
                <div className="space-y-3">
                  <h3 className="font-bold text-foreground">Diyet / Etiket</h3>
                  <div className="max-h-48 overflow-y-auto pr-2" style={{ scrollbarWidth: 'thin' }}>
                    <div className="flex flex-wrap gap-2">
                      <button 
                        onClick={() => setSelectedTag(undefined)}
                        className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${
                          selectedTag === undefined ? "bg-primary/10 text-primary border-2 border-primary/20" : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                        }`}>Tümü</button>
                      {tags?.map(tag => (
                        <button 
                          key={tag.id}
                          onClick={() => setSelectedTag(tag.id)}
                          className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${
                            selectedTag === tag.id 
                              ? "bg-primary/10 text-primary border-2 border-primary/20" 
                              : "bg-muted/30 text-muted-foreground hover:bg-muted border-2 border-transparent"
                          }`}
                        >
                          {tag.name}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
              
              <div className="flex items-center justify-end gap-3 mt-6 pt-6 border-t border-muted/30">
                <button 
                  onClick={handleClearFilters}
                  className="px-5 py-2.5 text-muted-foreground font-medium hover:text-foreground transition-colors"
                >
                  Temizle
                </button>
                <button 
                  onClick={handleApplyFilters}
                  className="px-6 py-2.5 bg-primary text-primary-foreground font-bold rounded-xl hover:opacity-90 transition-opacity shadow-sm"
                >
                  Filtreleri Uygula
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Decorative Categories */}
      <div className="relative group flex items-center">
        <button 
          onClick={() => scrollCategories('left')}
          className="absolute -left-2 z-10 p-2 rounded-full bg-background/90 shadow-sm border hover:bg-muted opacity-0 group-hover:opacity-100 transition-opacity"
        >
          <ChevronLeft className="w-5 h-5 text-foreground" />
        </button>
        <div ref={scrollContainerRef} className="flex items-center gap-3 overflow-x-auto pb-2 scrollbar-hide w-full" style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
          <button 
            onClick={() => {
              setSelectedCategory(undefined);
              setAppliedCategory(undefined);
            }}
            className={`px-5 py-2 rounded-full font-bold whitespace-nowrap shadow-sm transition-colors shrink-0 ${appliedCategory === undefined ? 'bg-primary text-primary-foreground shadow-primary/20' : 'bg-card text-muted-foreground hover:bg-neutral-50'}`}
          >
            Tümü
          </button>
          {categories?.map((cat) => (
            <button 
              key={cat.id}
              onClick={() => {
                setSelectedCategory(cat.id);
                setAppliedCategory(cat.id);
              }}
              className={`px-5 py-2 rounded-full font-bold whitespace-nowrap shadow-sm transition-colors shrink-0 ${appliedCategory === cat.id ? 'bg-primary text-primary-foreground shadow-primary/20' : 'bg-card text-muted-foreground hover:bg-neutral-50 dark:hover:bg-neutral-800'}`}
            >
              {cat.name}
            </button>
          ))}
        </div>
        <button 
          onClick={() => scrollCategories('right')}
          className="absolute -right-2 z-10 p-2 rounded-full bg-background/90 shadow-sm border hover:bg-muted opacity-0 group-hover:opacity-100 transition-opacity"
        >
          <ChevronRight className="w-5 h-5 text-foreground" />
        </button>
      </div>

      {/* Content */}
      {isLoading ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {[...Array(8)].map((_, i) => (
            <div key={i} className="space-y-4">
              <div className="aspect-square rounded-3xl bg-card shadow-sm animate-pulse" />
            </div>
          ))}
        </div>
      ) : isError ? (
        <div className="py-20 text-center space-y-4 bg-card rounded-[3rem] shadow-sm">
          <div className="w-16 h-16 bg-red-100 dark:bg-red-900/20 text-red-500 rounded-2xl flex items-center justify-center mx-auto">
            <Sparkles className="w-8 h-8" />
          </div>
          <h2 className="text-xl font-bold">Bir hata oluştu</h2>
          <p className="text-muted-foreground">Tarifler yüklenemedi. Lütfen tekrar deneyin.</p>
        </div>
      ) : data?.items.length === 0 ? (
        <div className="py-20 text-center space-y-4 bg-card rounded-[3rem] shadow-sm">
          <div className="w-16 h-16 bg-muted rounded-2xl flex items-center justify-center mx-auto text-muted-foreground">
            <Search className="w-8 h-8" />
          </div>
          <h2 className="text-xl font-bold text-foreground">Sonuç Bulunamadı</h2>
          <p className="text-muted-foreground max-w-xs mx-auto">
            Arama kriterlerinize uygun tarif bulunamadı. Lütfen başka kelimeler deneyin.
          </p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            <AnimatePresence mode="popLayout">
              {data?.items.map((recipe, index) => (
                <RecipeCard key={recipe.id} recipe={recipe} index={index} />
              ))}
            </AnimatePresence>
          </div>

          {/* Pagination & Footer */}
          {data && (
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 pt-8 border-t border-muted/50 mt-8">
              
              <div className="flex items-center gap-2 text-sm text-muted-foreground font-medium">
                <span>Göster:</span>
                <select 
                  value={size}
                  onChange={(e) => setSize(Number(e.target.value))}
                  className="bg-card border-2 border-transparent focus:border-primary rounded-xl px-2 py-1 outline-none transition-all shadow-sm cursor-pointer"
                >
                  <option value={12}>12</option>
                  <option value={24}>24</option>
                  <option value={48}>48</option>
                </select>
                <span className="ml-2 border-l border-muted/50 pl-4">Toplam {data.totalItems} tarif ({data.totalPages} sayfa)</span>
              </div>

              {data.totalPages > 0 && (
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => setPage(p => Math.max(0, p - 1))}
                    disabled={!data.hasPreviousPage}
                    className="p-2 rounded-xl bg-card text-foreground disabled:opacity-50 disabled:cursor-not-allowed hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors shadow-sm"
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </button>
                  
                  <div className="flex items-center gap-2">
                    {[...Array(data.totalPages)].map((_, i) => (
                      <button
                        key={i}
                        onClick={() => setPage(i)}
                        className={`w-10 h-10 rounded-xl font-bold transition-colors shadow-sm ${
                          page === i 
                            ? 'bg-primary text-primary-foreground' 
                            : 'bg-card text-muted-foreground hover:bg-neutral-50 dark:hover:bg-neutral-800'
                        }`}
                      >
                        {i + 1}
                      </button>
                    ))}
                  </div>

                  <button 
                    onClick={() => setPage(p => Math.min(data.totalPages - 1, p + 1))}
                    disabled={!data.hasNextPage}
                    className="p-2 rounded-xl bg-card text-foreground disabled:opacity-50 disabled:cursor-not-allowed hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors shadow-sm"
                  >
                    <ChevronRight className="w-5 h-5" />
                  </button>
                </div>
              )}
            </div>
          )}
        </>
      )}
        </div>
        <Footer />
      </main>
    </div>
  );
};

import { Footer } from '@/widgets/footer';
import { useState, useMemo } from "react";
import { Sidebar } from "@/widgets/sidebar/ui/Sidebar";
import { DashboardHeader } from "@/widgets/dashboard-header/ui/DashboardHeader";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { shoppingListApi } from "@/entities/shopping-list/api/shoppingListApi";
import { useAddIngredientStore } from "@/entities/pantry/model/useAddIngredientStore";
import { ShoppingListGroup } from "@/widgets/shopping-list/ui/ShoppingListGroup";
import { AddIngredientModal } from "@/features/add-pantry-item/ui/AddIngredientModal";
import { Loader2, CheckCircle2, ChevronDown, Plus } from "lucide-react";
import { MeasurementUnit } from "@/shared/constants/measurement";

export const ShoppingListPage = () => {
  const queryClient = useQueryClient();
  const [selectedItemIds, setSelectedItemIds] = useState<string[]>([]);
  const [sortBy, setSortBy] = useState<"name" | "recent">("recent");
  const [filterBy, setFilterBy] = useState<"all" | "unselected">("all");
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  
  const { data: shoppingList, isLoading } = useQuery({
    queryKey: ["shopping-list"],
    queryFn: shoppingListApi.getMyShoppingList
  });

  const deleteMutation = useMutation({
    mutationFn: shoppingListApi.removeItem,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["shopping-list"] });
    }
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, qty, unit }: { id: string, qty: number, unit: MeasurementUnit }) => 
      shoppingListApi.updateItem(id, { newQuantity: qty, newUnit: unit }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["shopping-list"] });
    }
  });

  const addMutation = useMutation({
    mutationFn: shoppingListApi.addItem,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["shopping-list"] });
    }
  });

  const bulkAddMutation = useMutation({
    mutationFn: shoppingListApi.bulkAddItems,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["shopping-list"] });
    }
  });

  const bulkPurchaseMutation = useMutation({
    mutationFn: shoppingListApi.bulkMarkAsPurchased,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["shopping-list"] });
      setSelectedItemIds([]);
    }
  });

  const handleToggleSelect = (id: string) => {
    setSelectedItemIds(prev => 
      prev.includes(id) ? prev.filter(itemId => itemId !== id) : [...prev, id]
    );
  };

  const handleDoneShopping = () => {
    if (selectedItemIds.length > 0) {
      bulkPurchaseMutation.mutate(selectedItemIds);
    }
  };

  // Processing logic (Filtering, Sorting, Grouping)
  const groupedList = useMemo(() => {
    if (!shoppingList) return {};
    
    // 1. Filter
    let processedList = shoppingList;
    if (filterBy === "unselected") {
      processedList = shoppingList.filter(item => !selectedItemIds.includes(item.id));
    }

    // 2. Sort
    processedList = [...processedList].sort((a, b) => {
      if (sortBy === "name") return a.ingredientName.localeCompare(b.ingredientName);
      // 'recent' can just keep original order assuming API returns recent first, 
      // or we sort by ID/Date if available. Assuming original is recent.
      return 0; 
    });

    // 3. Group
    return processedList.reduce((acc, item) => {
      const cat = item.categoryName || "DİĞER";
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(item);
      return acc;
    }, {} as Record<string, typeof shoppingList>);
  }, [shoppingList, filterBy, sortBy, selectedItemIds]);

  const totalItems = shoppingList?.length || 0;
  const doneItems = selectedItemIds.length;
  const progressPercentage = totalItems === 0 ? 0 : Math.round((doneItems / totalItems) * 100);

  return (
    <div className="min-h-screen bg-[#fafafa] dark:bg-[#0a0a0a] transition-colors duration-500">
