        <div className="flex-1 p-8 space-y-8 max-w-7xl mx-auto w-full animate-in fade-in slide-in-from-bottom-4 duration-500">
          
          {/* Header Area */}
          <div className="flex flex-col md:flex-row md:items-start justify-between gap-6">
            <div>
              <h1 className="text-4xl md:text-5xl font-black text-foreground tracking-tight mb-3">Alışveriş Listesi</h1>
              <p className="text-lg text-muted-foreground font-medium">Haftalık kiler ve mutfak alışverişini planla.</p>
            </div>
            
            <div className="flex flex-col sm:flex-row items-end sm:items-center gap-4">
              <button 
                onClick={() => setIsAddModalOpen(true)}
                className="w-full sm:w-auto h-12 px-6 rounded-2xl bg-primary text-primary-foreground font-bold flex items-center justify-center gap-2 hover:bg-primary/90 transition-colors shadow-sm shrink-0"
              >
                <Plus className="w-5 h-5" />
                <span>Malzeme Ekle</span>
              </button>

              {/* Progress Circle */}
            <div className="flex items-center gap-4 bg-card p-4 rounded-3xl shadow-sm border border-muted/30">
              <div className="relative w-16 h-16 flex items-center justify-center">
                <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                  <circle cx="50" cy="50" r="40" className="stroke-muted fill-none" strokeWidth="8" />
                  <circle 
                    cx="50" cy="50" r="40" 
                    className="stroke-primary fill-none transition-all duration-500 ease-out" 
                    strokeWidth="8"
                    strokeDasharray={`${2 * Math.PI * 40}`}
                    strokeDashoffset={`${2 * Math.PI * 40 * (1 - progressPercentage / 100)}`}
                    strokeLinecap="round"
                  />
                </svg>
                <span className="absolute text-xs font-bold">{progressPercentage}%</span>
              </div>
              <div className="flex flex-col justify-center">
                <span className="text-xl font-black leading-none">{doneItems}/{totalItems}</span>
                <span className="text-xs font-bold text-muted-foreground tracking-widest mt-1">TAMAMLANAN</span>
              </div>
              </div>
            </div>
          </div>

          {/* Main Content Area */}
          <div className="space-y-6">
            
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row md:items-center justify-end gap-4">

              <div className="flex items-center gap-3">
                <div className="relative group">
                  <select
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value as "name" | "recent")}
                    className="appearance-none pl-4 pr-10 py-2.5 bg-card border border-muted/50 rounded-xl text-sm font-bold text-foreground outline-none focus:border-primary cursor-pointer shadow-sm"
                  >
                    <option value="recent">Sırala: Varsayılan</option>
                    <option value="name">Sırala: İsim (A-Z)</option>
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
                </div>

                <div className="relative group">
                  <select
                    value={filterBy}
                    onChange={(e) => setFilterBy(e.target.value as "all" | "unselected")}
                    className="appearance-none pl-4 pr-10 py-2.5 bg-card border border-muted/50 rounded-xl text-sm font-bold text-foreground outline-none focus:border-primary cursor-pointer shadow-sm"
                  >
                    <option value="all">Filtre: Tümü</option>
                    <option value="unselected">Filtre: Eksikler</option>
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
                </div>
              </div>
            </div>

            {/* List */}
            {isLoading ? (
              <div className="py-20 flex justify-center">
                <Loader2 className="w-8 h-8 text-primary animate-spin" />
              </div>
            ) : totalItems === 0 ? (
              <div className="py-20 text-center flex flex-col items-center bg-card/50 rounded-3xl p-8 border border-dashed border-muted/50">
                <div className="w-16 h-16 bg-muted/50 rounded-full flex items-center justify-center mb-4">
                  <CheckCircle2 className="w-8 h-8 text-muted-foreground" />
                </div>
                <h3 className="text-lg font-bold text-foreground mb-2">Listeniz Bomboş!</h3>
                <p className="text-muted-foreground">Alışveriş listenize malzeme eklemeye başlayın.</p>
              </div>
            ) : Object.keys(groupedList).length === 0 ? (
              <div className="py-20 text-center bg-card/50 rounded-3xl p-8 border border-dashed border-muted/50">
                <p className="text-muted-foreground font-medium">Bu filtreye uygun malzeme bulunamadı.</p>
              </div>
            ) : (
              <div className="space-y-6">
                {Object.entries(groupedList).map(([cat, items]) => (
                  <ShoppingListGroup 
                    key={cat} 
                    categoryName={cat} 
                    items={items} 
                    selectedItemIds={selectedItemIds}
                    onToggleSelect={handleToggleSelect}
                    onDelete={(id) => deleteMutation.mutate(id)}
                    onUpdate={(id, qty, unit) => updateMutation.mutate({ id, qty, unit })}
                  />
                ))}
              </div>
            )}

            {/* List ends here */}

            {/* Done Shopping Button */}
            <button
              onClick={handleDoneShopping}
              disabled={selectedItemIds.length === 0 || bulkPurchaseMutation.isPending}
              className={`w-full py-4 rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all ${
                selectedItemIds.length > 0 
                  ? "bg-primary text-primary-foreground hover:opacity-90 shadow-md hover:shadow-lg transform hover:-translate-y-0.5" 
                  : "bg-card text-muted-foreground cursor-not-allowed border-2 border-dashed border-muted/50"
              }`}
            >
              {bulkPurchaseMutation.isPending ? (
                <Loader2 className="w-6 h-6 animate-spin" />
              ) : (
                <>
                  <CheckCircle2 className="w-6 h-6" />
                  <span>Alışverişi Tamamla</span>
                </>
              )}
            </button>

          </div>
        </div>
        <Footer />
      </main>

      <AddIngredientModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)}
        mode="shopping-list"
        isLoadingOverride={bulkAddMutation.isPending}
        onSubmitOverride={(request: any) => {
          const bulkRequest = {
            items: request.ingredients.map((item: any) => ({
              ingredientId: item.ingredientId,
              requestedName: item.requestedName,
              suggestedCategoryId: item.suggestedCategoryId,
              quantity: item.quantity,
              unit: item.unit
            }))
          };
          bulkAddMutation.mutate(bulkRequest, {
            onSuccess: () => {
              useAddIngredientStore.getState().clearShoppingListDrafts();
              setIsAddModalOpen(false);
            },
            onError: (error) => {
              console.error("Listeye eklenirken hata oluştu", error);
            }
          });
        }}
      />
    </div>
  );
};

import axios from 'axios';

export interface HealthCheckResponse {
  status: string;
  totalDuration: string;
  entries: {
    [key: string]: {
      data: any;
      duration: string;
      status: string;
      tags: string[];
    };
  };
}

export const getHealthStatus = async (): Promise<HealthCheckResponse> => {
  // Extract base URL without the /api suffix
  const baseUrl = import.meta.env.VITE_API_URL?.replace('/api', '') || 'https://localhost:7190';
  
  const response = await axios.get<HealthCheckResponse>(`${baseUrl}/health`);
  return response.data;
};

import { initializeApp } from "firebase/app";
import { getMessaging, getToken, onMessage } from "firebase/messaging";
import { getAnalytics } from "firebase/analytics";

const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID,
  measurementId: import.meta.env.VITE_FIREBASE_MEASUREMENT_ID
};

const app = initializeApp(firebaseConfig);
const analytics = getAnalytics(app);
const messaging = getMessaging(app);

// Request permission and get device token
export const requestForToken = async () => {
  try {
    const currentToken = await getToken(messaging, { 
        // VAPID key is necessary for web push notifications.
        // It's recommended to generate one in Firebase Console -> Project Settings -> Cloud Messaging -> Web Push certificates.
        // For now, it will work with the default, but if you have a custom VAPID key, add it here.
    });
    if (currentToken) {
      console.log('FCM Token generated');
      return currentToken;
    } else {
      console.log('No registration token available. Request permission to generate one.');
      return null;
    }
  } catch (err) {
    console.error('An error occurred while retrieving token. ', err);
    return null;
  }
};

export const onMessageListener = () =>
  new Promise((resolve) => {
    onMessage(messaging, (payload) => {
      resolve(payload);
    });
  });

