                              title="Sil"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import { useState, useMemo } from "react";
import * as LucideIcons from "lucide-react";
import { Search, Pencil, Trash2, HelpCircle, RotateCcw } from "lucide-react";
import { Input } from "@/shared/ui/input";
import { Button } from "@/shared/ui/button";
import type { Category } from "@/entities/admin-category/model/types";
import { useAdminCategories, useRestoreCategory } from "@/entities/admin-category/api/adminCategoryQueries";

interface CategoriesTableProps {
  onEdit: (category: Category) => void;
  onDelete: (category: Category) => void;
}

const toPascalCase = (str: string) => {
  return str
    .split(/[-_]+/)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join("");
};

export const CategoriesTable = ({ onEdit, onDelete }: CategoriesTableProps) => {
  const { data: categories = [], isLoading } = useAdminCategories();
  const restoreCategoryMutation = useRestoreCategory();
  const [searchQuery, setSearchQuery] = useState("");

  const filteredCategories = useMemo(() => {
    return categories.filter((cat) =>
      cat.name.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [categories, searchQuery]);

  if (isLoading) {
    return (
      <div className="bg-card border border-muted/50 rounded-2xl p-8 flex flex-col items-center justify-center min-h-[400px]">
        <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
        <p className="mt-4 text-muted-foreground font-medium">Kategoriler yükleniyor...</p>
      </div>
    );
  }

  return (
    <div className="bg-card border border-muted/50 rounded-2xl shadow-sm overflow-hidden flex flex-col">
      <div className="p-4 border-b border-muted/50 flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-muted/10">
        <div className="relative max-w-sm w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Kategori adı ile ara..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 bg-background"
          />
        </div>
        <div className="text-sm text-muted-foreground font-medium px-2">
          Toplam <span className="text-foreground font-bold">{filteredCategories.length}</span> kategori bulundu
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b border-muted/30 bg-muted/5">
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider w-16">İkon</th>
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider">Kategori Adı</th>
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider">Lucide İkon Kodu</th>
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider text-right">İşlemler</th>
            </tr>
          </thead>
          <tbody>
            {filteredCategories.length === 0 ? (
              <tr>
                <td colSpan={4} className="px-6 py-12 text-center">
                  <div className="flex flex-col items-center justify-center">
                    <div className="w-12 h-12 rounded-full bg-muted/30 flex items-center justify-center mb-3">
                      <Search className="w-6 h-6 text-muted-foreground" />
                    </div>
                    <p className="text-muted-foreground font-medium">Kategori bulunamadı</p>
                  </div>
                </td>
              </tr>
            ) : (
              filteredCategories.map((category) => {
                const parsedIconName = category.iconName ? toPascalCase(category.iconName) : "";
                const IconComponent = parsedIconName ? (LucideIcons as any)[parsedIconName] : null;
                const isPassive = !!category.deletedDate;

                return (
                  <tr
                    key={category.id}
                    className={`border-b border-muted/20 hover:bg-muted/10 transition-colors group ${isPassive ? 'opacity-60 bg-muted/5' : ''}`}
                  >
                    <td className="px-6 py-4">
                      <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                        {IconComponent ? (
                          <IconComponent className="w-5 h-5 text-primary" />
                        ) : (
                          <HelpCircle className="w-5 h-5 text-muted-foreground opacity-50" />
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-foreground">{category.name}</span>
                        {isPassive && (
                          <span className="px-2 py-0.5 rounded-full bg-destructive/10 text-destructive text-[10px] font-bold uppercase tracking-wider">
                            Pasif
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="inline-flex items-center px-2.5 py-1 rounded-md bg-muted/30 text-xs font-mono text-muted-foreground">
                        {category.iconName}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-end gap-2 opacity-50 group-hover:opacity-100 transition-opacity">
                        {isPassive ? (
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => restoreCategoryMutation.mutate(category.id)}
                            disabled={restoreCategoryMutation.isPending}
                            className="h-8 w-8 text-green-600 hover:text-green-700 hover:bg-green-50 dark:hover:bg-green-900/20"
                            title="Geri Yükle"
                          >
                            <RotateCcw className={`w-4 h-4 ${restoreCategoryMutation.isPending ? 'animate-spin' : ''}`} />
                          </Button>
                        ) : (
                          <>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => onEdit(category)}
                              className="h-8 w-8 text-blue-600 hover:text-blue-700 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                              title="Düzenle"
                            >
                              <Pencil className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => onDelete(category)}
                              className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                              title="Sil"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import { useAdminContactMessages, useMarkMessageAsRead, useDeleteMessage } from "@/entities/admin-contact-message";
import type { ContactMessage } from "@/entities/admin-contact-message";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { Button } from "@/shared/ui/button";
import { format } from "date-fns";
import { tr } from "date-fns/locale";
import { Trash2, MailOpen, Headset, Briefcase, Megaphone, MoreHorizontal } from "lucide-react";
import { Badge } from "@/shared/ui/badge";
import { useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/shared/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";

const getDepartmentInfo = (dept: string) => {
  switch (dept) {
    case 'support': return { label: 'Müşteri Destek', icon: Headset };
    case 'business': return { label: 'İş Geliştirme', icon: Briefcase };
    case 'press': return { label: 'Basın ve Medya', icon: Megaphone };
    case 'other': return { label: 'Diğer', icon: MoreHorizontal };
    default: return { label: dept, icon: MoreHorizontal };
  }
};

export const ContactMessagesTable = () => {
  const [page, setPage] = useState(0);
  const [size, setSize] = useState(10);
  const { data, isLoading } = useAdminContactMessages(page, size);
  const { mutate: markAsRead, isPending: isMarking } = useMarkMessageAsRead();
  const { mutate: deleteMessage, isPending: isDeleting } = useDeleteMessage();

  const [selectedMessage, setSelectedMessage] = useState<ContactMessage | null>(null);
  const [isViewOpen, setIsViewOpen] = useState(false);
  const [isDeleteOpen, setIsDeleteOpen] = useState(false);

  const handleView = (message: ContactMessage) => {
    setSelectedMessage(message);
    setIsViewOpen(true);
    if (!message.isRead) {
      markAsRead(message.id);
    }
  };

  const handleDelete = (message: ContactMessage) => {
    setSelectedMessage(message);
    setIsDeleteOpen(true);
  };

  const confirmDelete = () => {
    if (selectedMessage) {
      deleteMessage(selectedMessage.id, {
        onSuccess: () => {
          setIsDeleteOpen(false);
        }
      });
    }
  };

  if (isLoading) return <div>Yükleniyor...</div>;

  return (
    <div className="space-y-6">
      <div className="bg-card border rounded-[2rem] overflow-hidden shadow-sm">
        <Table>
        <TableHeader>
          <TableRow className="bg-muted/50 hover:bg-muted/50">
            <TableHead className="w-[150px] py-4">Tarih</TableHead>
            <TableHead className="py-4">İsim</TableHead>
            <TableHead className="py-4">Departman</TableHead>
            <TableHead className="py-4 text-center">Durum</TableHead>
            <TableHead className="text-right py-4 pr-6">İşlemler</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {data?.items?.map((message) => (
            <TableRow key={message.id} className="group hover:bg-muted/50 transition-colors">
              <TableCell className="py-4">
                <span className="text-sm text-muted-foreground whitespace-nowrap">
                  {format(new Date(message.createdDate), "d MMM yyyy HH:mm", { locale: tr })}
                </span>
              </TableCell>
              <TableCell className="py-4">
                <div className="font-semibold text-foreground">{message.name}</div>
                <a 
                  href={`mailto:${message.email}`}
                  className="text-sm text-primary hover:underline"
                  onClick={(e) => e.stopPropagation()}
                >
                  {message.email}
                </a>
              </TableCell>
              <TableCell className="py-4">
                <div className="flex items-center gap-2">
                  {(() => {
                    const { label, icon: Icon } = getDepartmentInfo(message.department);
                    return (
                      <>
                        <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center shrink-0">
                          <Icon className="w-4 h-4" />
                        </div>
                        <div className="font-medium truncate max-w-[250px]" title={label}>
                          {label}
                        </div>
                      </>
                    );
                  })()}
                </div>
              </TableCell>
              <TableCell className="py-4 text-center">
                <Badge variant={message.isRead ? "secondary" : "default"} className="font-semibold">
                  {message.isRead ? "Okundu" : "Yeni"}
                </Badge>
              </TableCell>
              <TableCell className="text-right py-4 pr-6">
                <div className="flex justify-end gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-8 gap-1.5"
                    onClick={() => handleView(message)}
                  >
                    <MailOpen className="w-3.5 h-3.5" />
                    <span>Görüntüle</span>
                  </Button>
                  <Button
                    variant="destructive"
                    size="icon"
                    className="h-8 w-8"
                    onClick={() => handleDelete(message)}
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </TableCell>
            </TableRow>
          ))}
          {(!data?.items || data.items.length === 0) && (
            <TableRow>
              <TableCell colSpan={5} className="h-32 text-center text-muted-foreground">
                Hiç mesaj bulunamadı.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      </div>

      {data && (() => {
        const count = data.count ?? data.items?.length ?? 0;
        const pagesCount = data.pages ?? 1;
        const hasPrev = data.hasPrevious ?? false;
        const hasNxt = data.hasNext ?? false;
        
        return (
          <div className="flex flex-col sm:flex-row justify-between items-center bg-card px-6 py-4 rounded-[2rem] border shadow-sm gap-4">
            <div className="flex items-center gap-4 text-sm font-medium text-muted-foreground">
              <div className="flex items-center gap-2">
                <span>Sayfa başına:</span>
                <Select 
                  value={size.toString()} 
                  onValueChange={(val) => {
                    setSize(Number(val));
                    setPage(0); // reset to page 0
                  }}
                >
                  <SelectTrigger className="w-[80px] h-8 rounded-xl bg-muted/50 border-none">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="5">5</SelectItem>
                    <SelectItem value="10">10</SelectItem>
                    <SelectItem value="25">25</SelectItem>
                    <SelectItem value="50">50</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="hidden sm:block w-px h-4 bg-border" />
              <span>
                Toplam <strong className="text-foreground">{count}</strong> kayıttan <strong className="text-foreground">{count === 0 ? 0 : page * size + 1}-{Math.min((page + 1) * size, count)}</strong> arası gösteriliyor.
              </span>
            </div>
            
            <div className="flex items-center gap-2">
              <Button 
                variant="outline" 
                size="sm" 
                className="rounded-xl font-bold"
                onClick={() => setPage(p => Math.max(0, p - 1))}
                disabled={!hasPrev}
              >
                Önceki
              </Button>
              <div className="px-3 text-sm font-black text-foreground">
                Sayfa {page + 1} / {pagesCount}
              </div>
              <Button 
                variant="outline" 
                size="sm" 
                className="rounded-xl font-bold"
                onClick={() => setPage(p => p + 1)}
                disabled={!hasNxt}
              >
                Sonraki
              </Button>
            </div>
          </div>
        );
      })()}

      <Dialog open={isViewOpen} onOpenChange={setIsViewOpen}>
        <DialogContent className="sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle>Mesaj Detayı</DialogTitle>
            <DialogDescription>
              {selectedMessage && format(new Date(selectedMessage.createdDate), "d MMMM yyyy HH:mm", { locale: tr })}
            </DialogDescription>
          </DialogHeader>
          {selectedMessage && (
            <div className="space-y-4 py-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <span className="text-sm font-medium text-muted-foreground">Gönderen</span>
                  <div className="font-semibold">{selectedMessage.name}</div>
                </div>
                <div className="space-y-1">
                  <span className="text-sm font-medium text-muted-foreground">E-posta</span>
                  <div>
                    <a href={`mailto:${selectedMessage.email}`} className="text-primary hover:underline">
                      {selectedMessage.email}
                    </a>
                  </div>
                </div>
              </div>
              <div className="space-y-1">
                <span className="text-sm font-medium text-muted-foreground">Departman</span>
                <div className="flex items-center gap-2 mt-1">
                  {(() => {
                    const { label, icon: Icon } = getDepartmentInfo(selectedMessage.department);
                    return (
                      <>
                        <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center shrink-0">
                          <Icon className="w-4 h-4" />
                        </div>
                        <div className="font-medium text-lg">{label}</div>
                      </>
                    );
                  })()}
                </div>
              </div>
              <div className="space-y-1">
                <span className="text-sm font-medium text-muted-foreground">Mesaj</span>
                <div className="bg-muted p-4 rounded-lg whitespace-pre-wrap text-sm leading-relaxed">
                  {selectedMessage.message}
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      <AlertDialog open={isDeleteOpen} onOpenChange={setIsDeleteOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Mesajı Sil</AlertDialogTitle>
            <AlertDialogDescription>
              Bu mesajı silmek istediğinize emin misiniz? Bu işlem geri alınamaz.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>İptal</AlertDialogCancel>
            <AlertDialogAction onClick={confirmDelete} className="bg-destructive hover:bg-destructive/90">
              Sil
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

import { useState } from "react";
import { 
  Pencil, 
  Trash2, 
  Search,
  RotateCcw,
  AlertCircle
} from "lucide-react";
import * as LucideIcons from "lucide-react";
import { useAdminDiets, useDeleteDiet, useRestoreDiet } from "@/entities/admin-diet";
import type { DietDTO } from "@/entities/admin-diet";
import { Input } from "@/shared/ui/input";
import { Button } from "@/shared/ui/button";
import { toast } from "sonner";
import { UpdateDietDialog } from "@/features/admin-diet";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";

export const DietsTable = () => {
  const { data: diets, isLoading, error } = useAdminDiets();
  const { mutate: deleteDiet, isPending: isDeleting } = useDeleteDiet();
  const { mutate: restoreDiet, isPending: isRestoring } = useRestoreDiet();

  const [searchTerm, setSearchTerm] = useState("");
  const [selectedDietForUpdate, setSelectedDietForUpdate] = useState<string | null>(null);
  
  const [dietToDelete, setDietToDelete] = useState<DietDTO | null>(null);
  const [dietToRestore, setDietToRestore] = useState<DietDTO | null>(null);

  if (isLoading) {
    return (
      <div className="w-full h-64 flex flex-col items-center justify-center space-y-4">
        <div className="w-10 h-10 border-4 border-emerald-500/30 border-t-emerald-500 rounded-full animate-spin" />
        <p className="text-muted-foreground font-medium animate-pulse">Diyet tercihleri yükleniyor...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="w-full p-6 bg-destructive/5 border border-destructive/20 rounded-2xl flex items-start gap-4">
        <AlertCircle className="w-6 h-6 text-destructive shrink-0 mt-0.5" />
        <div>
          <h3 className="font-semibold text-destructive">Yükleme Hatası</h3>
          <p className="text-sm text-destructive/80 mt-1">
