      <div className="p-4 border-b border-muted/50 flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-muted/10">
        <div className="relative max-w-sm w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Diyet adı ile ara..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 bg-background"
          />
        </div>
        <div className="text-sm text-muted-foreground font-medium px-2">
          Toplam <span className="text-foreground font-bold">{filteredDiets.length}</span> kayıt bulundu
        </div>
      </div>

      {/* Table Container */}
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b border-muted/30 bg-muted/5">
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider w-16">İkon</th>
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider">Diyet Adı</th>
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider">Açıklama</th>
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider">Dışlanan Öğeler</th>
              <th className="px-6 py-4 text-xs font-bold text-muted-foreground uppercase tracking-wider text-right">İşlemler</th>
            </tr>
          </thead>
          <tbody>
            {filteredDiets.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-12 text-center">
                  <div className="flex flex-col items-center justify-center">
                    <div className="w-12 h-12 rounded-full bg-muted/30 flex items-center justify-center mb-3">
                      <Search className="w-6 h-6 text-muted-foreground" />
                    </div>
                    <p className="text-muted-foreground font-medium">Diyet tercihi bulunamadı.</p>
                  </div>
                </td>
              </tr>
            ) : (
              filteredDiets.map((diet, index) => {
                const isDeleted = !!diet.deletedDate;
                const parsedIconName = diet.iconName ? diet.iconName : "Leaf";
                const IconComponent = (LucideIcons as any)[parsedIconName] || LucideIcons.Leaf;

                return (
                  <tr
                    key={diet.id}
                    className={`border-b border-muted/20 hover:bg-muted/10 transition-colors group ${isDeleted ? 'opacity-60 bg-muted/5' : ''}`}
                  >
                    <td className="px-6 py-4">
                      <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                        <IconComponent className="w-5 h-5 text-primary" />
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-foreground">{diet.name}</span>
                        {isDeleted && (
                          <span className="px-2 py-0.5 rounded-full bg-destructive/10 text-destructive text-[10px] font-bold uppercase tracking-wider">
                            Pasif
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-muted-foreground truncate max-w-[200px]">
                      {diet.description || "-"}
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        {diet.excludedCategoryCount > 0 && (
                          <div className="inline-flex items-center px-2.5 py-1 rounded-md bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400 text-xs font-bold">
                            {diet.excludedCategoryCount} Kategori
                          </div>
                        )}
                        {diet.excludedIngredientCount > 0 && (
                          <div className="inline-flex items-center px-2.5 py-1 rounded-md bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 text-xs font-bold">
                            {diet.excludedIngredientCount} Malzeme
                          </div>
                        )}
                        {diet.excludedCategoryCount === 0 && diet.excludedIngredientCount === 0 && (
                          <span className="text-muted-foreground/50 italic text-xs font-medium">Yok</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-end gap-2 opacity-50 group-hover:opacity-100 transition-opacity">
                        {isDeleted ? (
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => setDietToRestore(diet)}
                            disabled={isRestoring}
                            className="h-8 w-8 text-green-600 hover:text-green-700 hover:bg-green-50 dark:hover:bg-green-900/20"
                            title="Geri Yükle"
                          >
                            <RotateCcw className={`w-4 h-4 ${isRestoring ? 'animate-spin' : ''}`} />
                          </Button>
                        ) : (
                          <>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => setSelectedDietForUpdate(diet.id)}
                              className="h-8 w-8 text-blue-600 hover:text-blue-700 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                              title="Düzenle"
                            >
                              <Pencil className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => setDietToDelete(diet)}
                              className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                              title="Sil"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={!!dietToDelete} onOpenChange={(open) => !open && setDietToDelete(null)}>
        <AlertDialogContent className="rounded-2xl border-destructive/20 max-w-md">
          <AlertDialogHeader>
            <div className="w-12 h-12 rounded-full bg-destructive/10 flex items-center justify-center mb-4 mx-auto">
              <AlertCircle className="w-6 h-6 text-destructive" />
            </div>
            <AlertDialogTitle className="text-center text-xl">Diyet Silinecek</AlertDialogTitle>
            <AlertDialogDescription className="text-center">
              <strong>{dietToDelete?.name}</strong> isimli diyeti silmek (pasife almak) istediğinize emin misiniz? <br/><br/>
              Kullanıcılar bu diyeti seçemez hale gelecektir. Bu işlemi daha sonra geri alabilirsiniz.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="sm:justify-center flex-row gap-3 pt-4 border-t">
            <AlertDialogCancel className="mt-0 rounded-xl">İptal</AlertDialogCancel>
            <AlertDialogAction 
              onClick={handleDelete} 
              disabled={isDeleting}
              className="bg-destructive hover:bg-destructive/90 text-white rounded-xl"
            >
              {isDeleting ? "Siliniyor..." : "Evet, Sil"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Restore Confirmation Dialog */}
      <AlertDialog open={!!dietToRestore} onOpenChange={(open) => !open && setDietToRestore(null)}>
        <AlertDialogContent className="rounded-2xl border-emerald-500/20 max-w-md">
          <AlertDialogHeader>
            <div className="w-12 h-12 rounded-full bg-emerald-500/10 flex items-center justify-center mb-4 mx-auto">
              <RotateCcw className="w-6 h-6 text-emerald-600" />
            </div>
            <AlertDialogTitle className="text-center text-xl">Diyeti Geri Yükle</AlertDialogTitle>
            <AlertDialogDescription className="text-center">
              <strong>{dietToRestore?.name}</strong> isimli silinmiş diyeti tekrar aktif hale getirmek istediğinize emin misiniz?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="sm:justify-center flex-row gap-3 pt-4 border-t">
            <AlertDialogCancel className="mt-0 rounded-xl">İptal</AlertDialogCancel>
            <AlertDialogAction 
              onClick={handleRestore} 
              disabled={isRestoring}
              className="bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl"
            >
              {isRestoring ? "Geri Yükleniyor..." : "Geri Yükle"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Update Dialog */}
      <UpdateDietDialog 
        dietId={selectedDietForUpdate} 
        onClose={() => setSelectedDietForUpdate(null)} 
      />
    </div>
  );
};

import { useState, useMemo } from "react";
import { Loader2, Trash2, Tags } from "lucide-react";
import { 
  useAllAliases, 
  useDeleteAliasMutation, 
  useAdminIngredients,
  useRestoreAliasMutation 
} from "@/entities/admin-ingredient";
import { Button } from "@/shared/ui/button";
import { toast } from "sonner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";

export const AllAliasesTable = ({ searchTerm = "" }: { searchTerm?: string }) => {
  const { data: aliases, isLoading: isLoadingAliases } = useAllAliases();
  const { data: ingredientsData, isLoading: isLoadingIngredients } = useAdminIngredients(0, 500);
  
  const deleteMutation = useDeleteAliasMutation(""); 
  const restoreMutation = useRestoreAliasMutation("");

  const [deleteId, setDeleteId] = useState<string | null>(null);

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await deleteMutation.mutateAsync(deleteId);
      toast.success("Eş anlamlı kelime başarıyla silindi");
      setDeleteId(null);
    } catch {
      toast.error("Silme işlemi başarısız oldu");
    }
  };

  const isLoading = isLoadingAliases || isLoadingIngredients;

  // Create a map for ingredient names
  const ingredientMap = useMemo(() => {
    const map = new Map<string, string>();
    if (ingredientsData) {
      ingredientsData.items.forEach(ing => map.set(ing.id, ing.name));
    }
    return map;
  }, [ingredientsData]);

  const filteredAliases = useMemo(() => {
    if (!aliases) return [];
    if (!searchTerm) return aliases;
    
    const lowerSearch = searchTerm.toLowerCase();
    return aliases.filter(a => {
      const masterName = ingredientMap.get(a.ingredientId) || "";
      return a.aliasName.toLowerCase().includes(lowerSearch) || 
             masterName.toLowerCase().includes(lowerSearch);
    });
  }, [aliases, searchTerm, ingredientMap]);

  if (isLoading) {
    return <div className="flex justify-center p-8"><Loader2 className="w-8 h-8 animate-spin text-primary" /></div>;
  }

  return (
    <div className="space-y-4">
      <div className="bg-card border border-muted/30 rounded-[2rem] overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-muted-foreground uppercase bg-muted/20 border-b border-muted/30">
              <tr>
                <th className="px-6 py-5 font-black tracking-wider w-[40%]">Eş Anlamlı Kelime (Alias)</th>
                <th className="px-6 py-5 font-black tracking-wider w-[40%]">Ana Malzeme (Master)</th>
                <th className="px-6 py-5 font-black tracking-wider text-right w-[20%]">İşlemler</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-muted/30">
              {filteredAliases.map((alias: any) => (
                <tr key={alias.id} className="hover:bg-muted/30 transition-all duration-200 group">
                  <td className="px-6 py-4 font-bold text-foreground">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-sm transition-transform group-hover:scale-105 bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400">
                        <Tags className="w-6 h-6" />
                      </div>
                      <span className={`text-base ${alias.deletedDate ? 'line-through text-muted-foreground' : ''}`}>
                        {alias.aliasName}
                        {alias.deletedDate && <span className="ml-2 text-xs font-normal text-destructive bg-destructive/10 px-2 py-0.5 rounded-full">(Silindi)</span>}
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-4 font-medium text-muted-foreground">
                    <span className="bg-muted/50 px-3 py-1.5 rounded-xl text-xs font-bold text-muted-foreground border border-muted-foreground/10">
                      {ingredientMap.get(alias.ingredientId) || "Bilinmiyor"}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    {alias.deletedDate ? (
                      <Button 
                        variant="outline" 
                        size="sm" 
                        className="rounded-xl"
                        onClick={async () => {
                          try {
                            await restoreMutation.mutateAsync(alias.id);
                            toast.success("Eş anlamlı kelime başarıyla geri getirildi");
                          } catch {
                            toast.error("Geri getirme işlemi başarısız oldu");
                          }
                        }}
                        disabled={restoreMutation.isPending}
                      >
                        {restoreMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                        Geri Getir
                      </Button>
                    ) : (
                      <Button 
                        variant="ghost" 
                        size="icon" 
                        className="rounded-xl text-destructive hover:bg-destructive hover:text-white"
                        onClick={() => setDeleteId(alias.id)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </td>
                </tr>
              ))}
              
              {filteredAliases.length === 0 && (
                <tr>
                  <td colSpan={3} className="px-6 py-12 text-center text-muted-foreground">
                    {searchTerm ? "Aradığınız kriterde eş anlamlı kelime bulunamadı." : "Sistemde kayıtlı eş anlamlı kelime bulunamadı."}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Alias Silinecek</AlertDialogTitle>
            <AlertDialogDescription>
              Bu eş anlamlı kelimeyi silmek istediğinizden emin misiniz?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleteMutation.isPending}>İptal</AlertDialogCancel>
            <AlertDialogAction 
              onClick={(e) => {
                e.preventDefault();
                handleDelete();
              }}
              disabled={deleteMutation.isPending}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleteMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
              Evet, Sil
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

