import { useState, useMemo } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Search, Loader2, ChevronDown, ChevronUp, Plus, ShoppingCart, Trash2, Edit2, Minus } from "lucide-react";
import { pantryApi } from "@/entities/pantry/api/pantryApi";
import type { PantryItemResponse } from "@/entities/pantry/api/pantryApi";
import { shoppingListApi } from "@/entities/shopping-list/api/shoppingListApi";
import { motion, AnimatePresence } from "framer-motion";
import { AddIngredientModal } from "@/features/add-pantry-item/ui/AddIngredientModal";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/shared/ui/alert-dialog";
import { toast } from "sonner";
import { getCategoryIcon } from "@/shared/lib/icon-helpers";

// Karta özel kısa birim gösterimleri
const UNIT_SHORT_LABELS: Record<string, string> = {
  "Piece": "Adet",
  "Kilogram": "kg",
  "Gram": "g",
  "Liter": "L",
  "Milliliter": "ml",
  "Packet": "Paket",
  "Bunch": "Demet",
  "Slice": "Dilim",
  "Pinch": "Tutam",
  "Other": "Birim"
};

import { MeasurementUnit } from "@/shared/constants/measurement";

// Helper to calculate expiration days from real date
const getExpirationInfo = (expirationDateString: string | null) => {
  if (!expirationDateString) {
    return { daysText: "Tarih Belirsiz", colorClass: "bg-muted", textClass: "text-muted-foreground", hexColor: "#9e9e9e", progress: 0, isUnknown: true };
  }

  const expDate = new Date(expirationDateString);
  const today = new Date();
  const diffTime = expDate.getTime() - today.getTime();
  const days = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  let colorClass = "bg-[#4CAF50]"; // Green
  let textClass = "text-[#4CAF50]";
  let hexColor = "#4CAF50";
  let progress = Math.min((days / 14) * 100, 100);

  if (days < 0) {
    return { daysText: "Geçti", colorClass: "bg-neutral-800", textClass: "text-neutral-500", hexColor: "#424242", progress: 100, isUnknown: false };
  } else if (days <= 3) {
    colorClass = "bg-[#F44336]"; // Red
    textClass = "text-[#F44336]";
    hexColor = "#F44336";
    progress = 100; // Inverse visualization: red means urgent
  } else if (days <= 7) {
    colorClass = "bg-[#FF9800]"; // Yellow/Orange
    textClass = "text-[#FF9800]";
    hexColor = "#FF9800";
    progress = 50;
  }

  return { daysText: `${days} Gün`, colorClass, textClass, progress, hexColor, isUnknown: false };
};

const mapUnitNameToEnum = (unitName: string): number => {
  // Map string to enum manually, assuming 0 is Default/Pieces if not matched
  const lower = unitName?.toLowerCase();
  if (lower === "kg" || lower === "kilogram") return MeasurementUnit.Kilogram;
  if (lower === "g" || lower === "gram") return MeasurementUnit.Gram;
  if (lower === "l" || lower === "litre") return MeasurementUnit.Liter;
  if (lower === "ml" || lower === "mililitre") return MeasurementUnit.Milliliter;
  if (lower === "adet") return MeasurementUnit.Piece;
  if (lower === "paket") return MeasurementUnit.Packet;
  if (lower === "demet") return MeasurementUnit.Bunch;
  if (lower === "dilim") return MeasurementUnit.Slice;
  return MeasurementUnit.Piece; // Default
};

const PantryItemCard = ({ 
  item, 
  categoryName, 
  idx 
}: { 
  item: PantryItemResponse; 
  categoryName: string; 
  idx: number;
}) => {
  const queryClient = useQueryClient();
  const expiration = getExpirationInfo(item.expirationDate);
  
  const [isUpdateModalOpen, setIsUpdateModalOpen] = useState(false);
  const [isDeleteAlertOpen, setIsDeleteAlertOpen] = useState(false);
  const [isShoppingListModalOpen, setIsShoppingListModalOpen] = useState(false);
  const [quantity, setQuantity] = useState<number>(item.quantity);
  const [expirationDateInput, setExpirationDateInput] = useState<string>(item.expirationDate ? item.expirationDate.split('T')[0] : '');
  const [shoppingQuantity, setShoppingQuantity] = useState<number>(1);

  const updateMutation = useMutation({
    mutationFn: (args: { newQuantity: number; expirationDate?: string }) => pantryApi.updateIngredientQuantity(item.id, args.newQuantity, args.expirationDate),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["my-pantry"] });
      toast.success("Güncellendi.");
      setIsUpdateModalOpen(false);
    },
    onError: () => {
      toast.error("Güncellenemedi.");
    }
  });

  const deleteMutation = useMutation({
    mutationFn: () => pantryApi.deleteIngredient(item.id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["my-pantry"] });
      toast.success("Malzeme silindi.");
      setIsDeleteAlertOpen(false);
    },
    onError: () => {
      toast.error("Malzeme silinemedi.");
    }
  });

  const addToShoppingListMutation = useMutation({
    mutationFn: () => shoppingListApi.addItem({
      ingredientId: item.masterIngredientId || undefined,
      requestedName: !item.masterIngredientId ? item.name : undefined,
      quantity: shoppingQuantity,
      unit: mapUnitNameToEnum(item.unit)
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["shopping-list"] });
      toast.success(`${item.name} alışveriş listesine eklendi.`);
      setIsShoppingListModalOpen(false);
    },
    onError: (error: any) => {
      if(error?.response?.status === 409) {
        toast.error("Bu malzeme zaten alışveriş listesinde mevcut.");
      } else {
        toast.error("Alışveriş listesine eklenemedi.");
      }
    }
  });

  const handleIncrease = () => setQuantity(q => q + 1);
  const handleDecrease = () => setQuantity(q => Math.max(0.1, q - 1)); // Prevent negative/zero

  return (
    <>
      <motion.div 
        initial={{ opacity: 0, scale: 0.95, y: 10 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        transition={{ delay: idx * 0.05, duration: 0.3 }}
        className="group relative flex items-center gap-4 bg-card rounded-[1.5rem] p-4 shadow-md hover:shadow-xl hover:-translate-y-1 transition-all duration-300 border border-muted/80 dark:border-white/10 hover:border-primary/50 overflow-hidden"
      >
        {/* Icon Background */}
        <div className="relative w-14 h-14 rounded-2xl flex-shrink-0 bg-primary/10 flex items-center justify-center overflow-hidden border border-primary/20 group-hover:bg-primary/15 transition-colors">
          <div className="text-primary z-10 group-hover:scale-110 transition-all duration-300">
            {getCategoryIcon(categoryName)}
          </div>
        </div>
        
        {/* Content */}
        <div className="flex-1 min-w-0 py-1">
          <h3 className="font-bold text-sm text-foreground mb-1 whitespace-normal group-hover:text-primary transition-colors">{item.name}</h3>
          <div className="flex items-center gap-2">
            <p className="text-xs font-bold text-primary bg-primary/10 px-2 py-0.5 rounded-md w-fit whitespace-nowrap">
              {item.quantity} {UNIT_SHORT_LABELS[item.unit] || item.unit}
            </p>
            {item.isPendingApproval && (
              <span className="inline-flex items-center px-1.5 py-0.5 rounded-md text-[10px] font-bold bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300">
                Bekliyor
              </span>
            )}
          </div>
        </div>

        {/* Expiration Indicator */}
        <div className="flex flex-col items-end justify-center gap-2 flex-shrink-0 pl-3 border-l border-muted/30">
          <div 
            className={`px-2.5 py-1 rounded-full text-[10px] font-black tracking-wider ${expiration.isUnknown ? 'capitalize' : 'uppercase'}`}
            style={{ 
              backgroundColor: expiration.isUnknown ? undefined : `${expiration.hexColor}15`, 
              color: expiration.isUnknown ? undefined : expiration.hexColor,
              border: expiration.isUnknown ? undefined : `1px solid ${expiration.hexColor}30`
            }}
          >
            {expiration.daysText}
          </div>
          {!expiration.isUnknown && (
            <div className="w-12 h-1.5 rounded-full bg-muted overflow-hidden">
              <div 
                className="h-full rounded-full transition-all duration-1000 ease-out" 
                style={{ width: `${expiration.progress}%`, backgroundColor: expiration.hexColor }}
              />
            </div>
          )}
        </div>

        {/* Hover Action Overlay */}
        <div className="absolute right-0 top-0 bottom-0 flex items-center justify-end gap-2 pl-12 pr-4 bg-gradient-to-l from-white via-white to-transparent dark:from-[#18181b] dark:via-[#18181b] translate-x-full group-hover:translate-x-0 transition-transform duration-300 ease-out z-20">
          <button 
            onClick={() => { setQuantity(item.quantity); setIsUpdateModalOpen(true); }}
            className="w-10 h-10 rounded-full bg-primary/10 text-primary flex items-center justify-center hover:bg-primary hover:text-primary-foreground transition-all hover:scale-110 shadow-sm"
            title="Miktarı Güncelle"
          >
            <Edit2 className="w-4 h-4" />
          </button>
          <button 
            onClick={() => { setShoppingQuantity(1); setIsShoppingListModalOpen(true); }}
            className="w-10 h-10 rounded-full bg-blue-500/10 text-blue-500 flex items-center justify-center hover:bg-blue-500 hover:text-white transition-all hover:scale-110 shadow-sm"
            title="Alışveriş Listesine Ekle"
          >
            <ShoppingCart className="w-4 h-4" />
          </button>
          <button 
            onClick={() => setIsDeleteAlertOpen(true)}
            className="w-10 h-10 rounded-full bg-destructive/10 text-destructive flex items-center justify-center hover:bg-destructive hover:text-destructive-foreground transition-all hover:scale-110 shadow-sm"
            title="Sil"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      </motion.div>

      {/* Update Quantity Modal */}
      <Dialog open={isUpdateModalOpen} onOpenChange={setIsUpdateModalOpen}>
        <DialogContent className="sm:max-w-md rounded-[2rem] p-6">
          <DialogHeader>
            <DialogTitle className="text-2xl font-black">{item.name} Miktarını Güncelle</DialogTitle>
          </DialogHeader>
          <div className="flex flex-col items-center justify-center py-6 gap-6">
            <div className="flex items-center gap-6">
              <button 
                onClick={handleDecrease}
                className="w-14 h-14 rounded-2xl bg-muted flex items-center justify-center text-foreground hover:bg-destructive/10 hover:text-destructive transition-colors"
              >
                <Minus className="w-6 h-6" />
              </button>
              
              <div className="flex flex-col items-center min-w-[100px]">
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={quantity}
                  onChange={(e) => setQuantity(Number(e.target.value))}
                  className="w-28 bg-transparent text-center text-4xl font-black text-foreground outline-none border-b-2 border-transparent focus:border-primary/50 transition-colors pb-1 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                />
                <span className="text-sm font-bold text-muted-foreground mt-1">{item.unit}</span>
              </div>
              
              <button 
                onClick={handleIncrease}
                className="w-14 h-14 rounded-2xl bg-muted flex items-center justify-center text-foreground hover:bg-primary/10 hover:text-primary transition-colors"
              >
                <Plus className="w-6 h-6" />
              </button>
            </div>

            <div className="w-full space-y-2 mt-2">
              <label className="text-sm font-bold text-muted-foreground ml-1">Son Kullanma Tarihi</label>
              <input
                type="date"
                min={new Date().toISOString().split('T')[0]}
                value={expirationDateInput}
                onChange={(e) => setExpirationDateInput(e.target.value)}
                className="w-full h-12 rounded-xl bg-muted/50 px-4 text-sm font-medium border-2 border-transparent focus:border-primary/50 outline-none transition-colors"
              />
            </div>
          </div>
          <div className="flex gap-3 w-full">
            <button 
              onClick={() => setIsUpdateModalOpen(false)}
              className="flex-1 h-12 rounded-xl font-bold bg-muted text-foreground hover:bg-muted/80 transition-colors"
            >
              İptal
            </button>
            <button 
              onClick={() => updateMutation.mutate({ newQuantity: quantity, expirationDate: expirationDateInput ? new Date(expirationDateInput).toISOString() : undefined })}
              disabled={updateMutation.isPending || (quantity === item.quantity && expirationDateInput === (item.expirationDate ? item.expirationDate.split('T')[0] : ''))}
              className="flex-1 h-12 rounded-xl font-bold bg-primary text-primary-foreground hover:bg-primary/90 transition-colors disabled:opacity-50"
            >
              {updateMutation.isPending ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : "Kaydet"}
            </button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Shopping List Modal */}
      <Dialog open={isShoppingListModalOpen} onOpenChange={setIsShoppingListModalOpen}>
        <DialogContent className="sm:max-w-md rounded-[2rem] p-6">
          <DialogHeader>
            <DialogTitle className="text-2xl font-black">{item.name} Listeye Eklenecek</DialogTitle>
          </DialogHeader>
          <div className="flex flex-col items-center justify-center py-6 gap-6">
            <div className="flex items-center gap-6">
              <button 
                onClick={() => setShoppingQuantity(q => Math.max(0.1, q - 1))}
                className="w-14 h-14 rounded-2xl bg-muted flex items-center justify-center text-foreground hover:bg-destructive/10 hover:text-destructive transition-colors"
              >
                <Minus className="w-6 h-6" />
              </button>
              
              <div className="flex flex-col items-center min-w-[100px]">
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={shoppingQuantity}
                  onChange={(e) => setShoppingQuantity(Number(e.target.value))}
                  className="w-28 bg-transparent text-center text-4xl font-black text-foreground outline-none border-b-2 border-transparent focus:border-primary/50 transition-colors pb-1 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                />
                <span className="text-sm font-bold text-muted-foreground mt-1">{item.unit}</span>
              </div>
              
              <button 
                onClick={() => setShoppingQuantity(q => q + 1)}
                className="w-14 h-14 rounded-2xl bg-muted flex items-center justify-center text-foreground hover:bg-primary/10 hover:text-primary transition-colors"
              >
                <Plus className="w-6 h-6" />
              </button>
            </div>
          </div>
          <div className="flex gap-3 w-full">
            <button 
              onClick={() => setIsShoppingListModalOpen(false)}
              className="flex-1 h-12 rounded-xl font-bold bg-muted text-foreground hover:bg-muted/80 transition-colors"
            >
              İptal
            </button>
            <button 
              onClick={() => addToShoppingListMutation.mutate()}
              disabled={addToShoppingListMutation.isPending}
              className="flex-1 h-12 rounded-xl font-bold bg-blue-500 text-white hover:bg-blue-600 transition-colors disabled:opacity-50"
            >
              {addToShoppingListMutation.isPending ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : "Ekle"}
            </button>
          </div>
        </DialogContent>
      </Dialog>


      {/* Delete Confirmation Alert */}
      <AlertDialog open={isDeleteAlertOpen} onOpenChange={setIsDeleteAlertOpen}>
        <AlertDialogContent className="rounded-[2rem]">
          <AlertDialogHeader>
            <AlertDialogTitle>Bu malzemeyi silmek istediğinize emin misiniz?</AlertDialogTitle>
            <AlertDialogDescription>
              <span className="font-bold text-foreground">{item.name}</span> dolabınızdan kalıcı olarak silinecektir. Bu işlem geri alınamaz.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="rounded-xl">İptal</AlertDialogCancel>
            <AlertDialogAction 
              onClick={(e) => {
                e.preventDefault();
                deleteMutation.mutate();
              }}
              disabled={deleteMutation.isPending}
              className="rounded-xl bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleteMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : "Evet, Sil"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export const PantryFeed = () => {
  const [collapsedCategories, setCollapsedCategories] = useState<Record<string, boolean>>({});
  const [expandedCategories, setExpandedCategories] = useState<Record<string, boolean>>({});
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  const { data: pantryItems, isLoading, isError } = useQuery({
    queryKey: ["my-pantry"],
    queryFn: () => pantryApi.getMyPantry(),
  });

  const groupedItems = useMemo(() => {
    if (!pantryItems) return {};

    const filtered = pantryItems.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.categoryName.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return filtered.reduce((acc, item) => {
      const cat = item.categoryName || "Diğer";
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(item);
      return acc;
    }, {} as Record<string, PantryItemResponse[]>);
  }, [pantryItems, searchTerm]);

  const toggleCollapse = (cat: string) => {
    setCollapsedCategories(prev => ({ ...prev, [cat]: !prev[cat] }));
  };

  const toggleExpand = (cat: string) => {
    setExpandedCategories(prev => ({ ...prev, [cat]: !prev[cat] }));
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <Loader2 className="w-10 h-10 animate-spin text-primary" />
      </div>
    );
  }

  if (isError) {
    return (
      <div className="text-center py-20 bg-white/50 dark:bg-neutral-900/50 rounded-[3rem] border border-muted/30">
        <p className="text-muted-foreground font-bold text-lg">Mutfak dolabınız yüklenirken bir hata oluştu.</p>
      </div>
    );
  }

  return (
    <div className="space-y-10">
      {/* Header & Search */}
      <div className="flex flex-col gap-6 mb-8">
        <div>
          <h1 className="text-4xl md:text-5xl font-black text-foreground tracking-tight mb-2">Mutfak Dolabım</h1>
          <p className="text-lg text-muted-foreground font-medium">
            Malzemelerinizi yönetin ve tazeliklerini kolayca takip edin.
          </p>
        </div>

        {/* Action Bar */}
        <div className="flex flex-col sm:flex-row w-full justify-between items-center gap-4">
          <div className="relative group w-full max-w-md">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground group-focus-within:text-primary transition-colors" />
            <input 
              type="text" 
              placeholder="Dolabındaki malzemelerde ara..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full h-12 pl-12 pr-4 rounded-2xl bg-card border-2 border-muted/30 focus:border-primary focus:bg-background shadow-sm outline-none transition-all font-medium text-sm"
            />
          </div>
          
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="w-full sm:w-auto h-12 px-6 rounded-2xl bg-primary text-primary-foreground font-bold flex items-center justify-center gap-2 hover:bg-primary/90 transition-colors shadow-sm shrink-0"
          >
            <Plus className="w-5 h-5" />
            <span>Malzeme Ekle</span>
          </button>
        </div>
      </div>

      {Object.keys(groupedItems).length === 0 ? (
        <div className="text-center py-20 bg-white/50 dark:bg-neutral-900/50 rounded-[3rem] border border-muted/30">
          <p className="text-muted-foreground font-bold text-lg">Hiç malzeme bulunamadı.</p>
        </div>
      ) : (
        <div className="space-y-12">
          {Object.entries(groupedItems).map(([categoryName, items]) => {
            const isCollapsed = collapsedCategories[categoryName];
            const isExpanded = expandedCategories[categoryName];
            const displayedItems = isExpanded ? items : items.slice(0, 4);

            return (
              <div key={categoryName}>
                {/* Category Header (Clickable for Collapse) */}
                <div 
                  className="flex items-center justify-between mb-6 border-b border-muted/30 pb-4 cursor-pointer group"
                  onClick={() => toggleCollapse(categoryName)}
                >
                  <div className="flex items-center gap-3">
                    <div className="text-primary">
                      {getCategoryIcon(categoryName)}
                    </div>
                    <h2 className="text-2xl font-bold text-foreground group-hover:text-primary transition-colors">
                      {categoryName}
                    </h2>
                    <span className="text-xs font-bold text-muted-foreground bg-muted px-2 py-0.5 rounded-full">
                      {items.length}
                    </span>
                  </div>
                  <div className="text-muted-foreground group-hover:text-primary transition-colors p-1 rounded-full group-hover:bg-primary/10">
                    {isCollapsed ? <ChevronDown className="w-5 h-5" /> : <ChevronUp className="w-5 h-5" />}
                  </div>
                </div>

                {/* Items Grid */}
                <AnimatePresence>
                  {!isCollapsed && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      className="overflow-hidden"
                    >
                      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                        {displayedItems.map((item, idx) => (
                          <PantryItemCard 
                            key={item.id} 
                            item={item} 
                            categoryName={categoryName} 
                            idx={idx} 
                          />
                        ))}
                      </div>
                      
                      {/* Show More/Less Button */}
                      {items.length > 4 && (
                        <div className="mt-6 flex justify-center">
                          <button 
                            onClick={() => toggleExpand(categoryName)} 
                            className="px-6 py-2 rounded-full border-2 border-primary/20 text-primary font-bold hover:bg-primary/10 transition-colors text-sm"
                          >
                            {isExpanded ? "Daha Az Göster" : `Tüm ${items.length} Ürünü Göster`}
                          </button>
                        </div>
                      )}
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </div>
      )}

      {/* Modals */}
      <AddIngredientModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)} 
      />
    </div>
  );
};

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { motion, AnimatePresence } from "framer-motion";
import { 
  MessageSquare, 
  Loader2, 
  Search, 
  AlertCircle,
  Clock,
  Trash2,
  Edit2,
  X,
  Check,
  Star,
  ChevronLeft,
  ChevronRight
} from "lucide-react";
import { Link } from "react-router-dom";
import { recipeApi } from "@/entities/recipe/api/recipeApi";
import type { MyComment } from "@/entities/recipe/api/recipeApi";
import { useSessionStore } from "@/entities/session";
import { useDebounce } from "@/shared/hooks/useDebounce";

export const ProfileCommentsTab = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const debouncedSearch = useDebounce(searchTerm, 500);
  const [sortBy, setSortBy] = useState("Newest");
  
  const [page, setPage] = useState(0);
  const [size, setSize] = useState(12);

  const queryClient = useQueryClient();
  const user = useSessionStore(state => state.user);

  // Delete State
  const [commentToDelete, setCommentToDelete] = useState<string | null>(null);

  // Edit State
  const [editingCommentId, setEditingCommentId] = useState<string | null>(null);
  const [editText, setEditText] = useState("");
  const [editRating, setEditRating] = useState<number>(0);

  const { data, isLoading, isError } = useQuery({
    queryKey: ["my-comments", page, size, debouncedSearch, sortBy],
    queryFn: () => recipeApi.getMyComments(page, size, debouncedSearch, sortBy),
  });

  const comments = data?.items || [];

  const deleteCommentMutation = useMutation({
    mutationFn: recipeApi.deleteComment,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["my-comments"] });
    },
  });

  const updateCommentMutation = useMutation({
    mutationFn: ({ commentId, content, rating }: { commentId: string, content: string, rating?: number }) => 
      recipeApi.updateComment(commentId, content, rating),
    onSuccess: () => {
      setEditingCommentId(null);
      queryClient.invalidateQueries({ queryKey: ["my-comments"] });
    },
  });

  const confirmDelete = () => {
    if (commentToDelete) {
      deleteCommentMutation.mutate(commentToDelete);
      setCommentToDelete(null);
    }
  };

  const handleDelete = (commentId: string) => {
    setCommentToDelete(commentId);
  };

  const startEdit = (commentId: string, currentText: string, currentRating: number | undefined) => {
    setEditingCommentId(commentId);
    setEditText(currentText);
    setEditRating(currentRating || 0);
  };

  const handleEditSubmit = (e: React.FormEvent, commentId: string) => {
    e.preventDefault();
    if (!editText.trim()) return;
    updateCommentMutation.mutate({ commentId, content: editText, rating: editRating > 0 ? editRating : undefined });
  };

  return (
    <div className="space-y-6">
      {/* Search Header */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-xl font-black text-foreground flex items-center gap-2 w-full md:w-auto">
          <MessageSquare className="w-6 h-6 text-primary" />
          Yorumlarım {data ? `(${data.totalItems})` : ""}
        </h2>
        
        <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <input
              type="text"
              placeholder="Yorumlarda ara..."
              value={searchTerm}
              onChange={(e) => {
                setSearchTerm(e.target.value);
                setPage(0);
              }}
              className="w-full pl-9 pr-4 py-2.5 rounded-full bg-background border-2 border-muted/30 focus:border-primary/50 focus:ring-4 focus:ring-primary/10 transition-all text-sm font-medium"
            />
          </div>
          
          <div className="relative w-full sm:w-48 shrink-0">
            <select 
              value={sortBy}
              onChange={(e) => {
                setSortBy(e.target.value);
                setPage(0);
              }}
              className="w-full appearance-none pl-4 pr-10 py-2.5 bg-background border-2 border-muted/30 focus:border-primary/50 focus:ring-4 focus:ring-primary/10 rounded-full outline-none transition-all text-sm font-medium cursor-pointer"
            >
              <option value="Newest">En Yeni</option>
              <option value="Oldest">En Eski</option>
              <option value="Highest Rated">En Yüksek Puanlı</option>
              <option value="Lowest Rated">En Düşük Puanlı</option>
            </select>
            <ChevronRight className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground rotate-90 pointer-events-none" />
          </div>
        </div>
      </div>

      {isLoading ? (
        <div className="grid gap-4">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-32 bg-muted/50 rounded-2xl animate-pulse" />
          ))}
        </div>
      ) : isError ? (
        <div className="p-8 rounded-[2rem] bg-red-500/10 text-center">
          <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <p className="text-red-500 font-bold">Yorumlar yüklenirken bir hata oluştu.</p>
        </div>
      ) : comments.length === 0 ? (
        <div className="py-20 text-center bg-card rounded-[2rem] border border-dashed border-muted/50">
          <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <MessageSquare className="w-10 h-10 text-primary opacity-50" />
          </div>
          <h3 className="text-2xl font-black text-foreground mb-3">
            {debouncedSearch ? "Sonuç bulunamadı" : "Henüz yorum yapmadınız"}
          </h3>
          <p className="text-muted-foreground font-medium max-w-sm mx-auto">
            {debouncedSearch 
              ? "Aramanıza uygun yorum bulunamadı. Lütfen başka bir kelime deneyin."
              : "Tariflere yorum yaparak topluluğa katkıda bulunabilirsiniz."}
          </p>
        </div>
      ) : (
        <div className="grid gap-4">
          <AnimatePresence mode="popLayout">
            {comments.map((comment: MyComment) => {
              const isEditing = editingCommentId === comment.id;

              return (
                <motion.div
                  key={comment.id}
                  layout
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  className="bg-card rounded-2xl p-4 sm:p-6 border border-muted/30 shadow-sm hover:shadow-md transition-shadow relative overflow-hidden"
                >
                  <div className="flex flex-col sm:flex-row gap-4 sm:gap-6">
                    {/* Recipe Thumbnail */}
                    <Link to={`/recipes/${comment.recipeId}`} className="block shrink-0 relative group">
                      {comment.recipeImageUrl ? (
                        <img 
                          src={comment.recipeImageUrl} 
                          alt={comment.recipeName}
                          className="w-full sm:w-24 h-40 sm:h-24 rounded-xl object-cover group-hover:opacity-80 transition-opacity" 
                        />
                      ) : (
                        <div className="w-full sm:w-24 h-40 sm:h-24 rounded-xl bg-primary/10 flex flex-col items-center justify-center group-hover:bg-primary/20 transition-colors">
                           <span className="text-3xl">🍲</span>
                        </div>
                      )}
                    </Link>
                    
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-start gap-4 mb-2">
                        <div>
                          <Link to={`/recipes/${comment.recipeId}`} className="text-lg font-bold text-foreground hover:text-primary transition-colors line-clamp-1">
                            {comment.recipeName}
                          </Link>
                          <p className="text-xs text-muted-foreground flex items-center gap-1 mt-1">
                            <Clock className="w-3 h-3" />
                            {new Date(comment.createdDate).toLocaleDateString('tr-TR', {
                              year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit'
                            })}
                          </p>
                        </div>
                        
                        {/* Actions */}
                        {!isEditing && (
                          <div className="flex items-center gap-1 shrink-0 bg-muted/20 p-1 rounded-xl">
                            <button
                              onClick={() => startEdit(comment.id, comment.content, comment.rating)}
                              className="p-2 text-muted-foreground hover:text-blue-500 hover:bg-blue-500/10 rounded-lg transition-colors"
                              title="Düzenle"
                            >
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button
                              onClick={() => handleDelete(comment.id)}
                              disabled={deleteCommentMutation.isPending}
                              className="p-2 text-muted-foreground hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-colors disabled:opacity-50"
                              title="Sil"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        )}
                      </div>

                      {/* Parent Comment Ref */}
                      {comment.parentCommentId && (
                        <div className="text-xs bg-muted/40 p-2 rounded-lg border-l-2 border-primary/50 text-muted-foreground mb-3 italic line-clamp-2">
                          Yanıtlanan yorum: {comment.parentCommentContent || "Silinmiş içerik"}
                        </div>
                      )}

                      {/* Rating Display */}
                      {!isEditing && comment.rating != null && (
                        <div className="flex items-center gap-1 mb-2">
                           {[1, 2, 3, 4, 5].map((star) => (
                              <Star
                                key={star}
                                className={`w-3.5 h-3.5 ${
                                  comment.rating! >= star
                                    ? "fill-amber-500 text-amber-500"
                                    : "fill-muted text-muted-foreground/30"
                                }`}
                              />
                            ))}
                        </div>
                      )}

                      {/* Comment Content / Editor */}
                      {isEditing ? (
                        <form onSubmit={(e) => handleEditSubmit(e, comment.id)} className="mt-3">
                          {comment.rating != null && (
                            <div className="flex items-center gap-2 mb-3">
                              <span className="text-sm font-semibold text-muted-foreground mr-2">Puanı Düzenle:</span>
                              {[1, 2, 3, 4, 5].map((star) => (
                                <button
                                  key={star}
                                  type="button"
                                  onClick={() => setEditRating(star)}
                                  className={`hover:scale-110 transition-transform ${
                                    editRating >= star ? "text-amber-500" : "text-muted-foreground/30"
                                  }`}
                                >
                                  <Star className={`w-5 h-5 ${editRating >= star ? "fill-amber-500" : ""}`} />
                                </button>
                              ))}
                            </div>
                          )}
                          <textarea
                            value={editText}
                            onChange={(e) => setEditText(e.target.value)}
                            className="w-full bg-background border border-muted rounded-xl p-3 text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 resize-none min-h-[80px] mb-3"
                          />
                          <div className="flex justify-end gap-2">
                            <button
                              type="button"
                              onClick={() => setEditingCommentId(null)}
                              className="px-4 py-2 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors flex items-center gap-1 bg-muted/50 rounded-lg hover:bg-muted"
                            >
                              <X className="w-4 h-4" /> İptal
                            </button>
                            <button
                              type="submit"
                              disabled={!editText.trim() || updateCommentMutation.isPending}
                              className="bg-primary text-primary-foreground px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-1 hover:bg-primary/90 transition-colors disabled:opacity-50"
                            >
                              {updateCommentMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                              Kaydet
                            </button>
                          </div>
                        </form>
                      ) : (
                        <p className="text-foreground/80 text-sm whitespace-pre-wrap leading-relaxed">
                          {comment.content}
                        </p>
                      )}
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>
      )}

      {/* Pagination */}
      {data && data.items.length > 0 && (
        <div className="flex flex-col sm:flex-row items-center justify-between gap-4 pt-8 border-t border-muted/50 mt-8">
          <div className="flex items-center gap-2 text-sm text-muted-foreground font-medium">
            <span>Göster:</span>
            <select 
              value={size}
              onChange={(e) => {
                setSize(Number(e.target.value));
                setPage(0);
              }}
              className="bg-card border-2 border-transparent focus:border-primary rounded-xl px-2 py-1 outline-none transition-all shadow-sm cursor-pointer"
            >
              <option value={12}>12</option>
              <option value={24}>24</option>
              <option value={48}>48</option>
            </select>
            <span className="ml-2 border-l border-muted/50 pl-4">Toplam {data.totalItems} yorum ({data.totalPages} sayfa)</span>
          </div>

          {data.totalPages > 0 && (
            <div className="flex items-center gap-2">
              <button 
                onClick={() => setPage(p => Math.max(0, p - 1))}
                disabled={!data.hasPreviousPage}
                className="p-2 rounded-xl bg-card text-foreground disabled:opacity-50 disabled:cursor-not-allowed hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors shadow-sm"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              
              <div className="flex items-center gap-2 hidden sm:flex">
                {[...Array(data.totalPages)].map((_, i) => {
                  // Sadece aktif sayfanın etrafındakileri göster (basit sayfalama)
                  if (data.totalPages > 7 && i !== 0 && i !== data.totalPages - 1 && Math.abs(page - i) > 1) {
                    if (Math.abs(page - i) === 2) return <span key={i} className="text-muted-foreground">...</span>;
                    return null;
                  }
                  return (
                    <button
                      key={i}
                      onClick={() => setPage(i)}
                      className={`w-10 h-10 rounded-xl font-bold transition-colors shadow-sm ${
                        page === i 
                          ? 'bg-primary text-primary-foreground' 
                          : 'bg-card text-muted-foreground hover:bg-neutral-50 dark:hover:bg-neutral-800'
                      }`}
                    >
                      {i + 1}
                    </button>
                  );
                })}
              </div>

              <div className="flex items-center gap-2 sm:hidden text-sm font-bold text-muted-foreground px-4">
                {page + 1} / {data.totalPages}
              </div>

              <button 
                onClick={() => setPage(p => Math.min(data.totalPages - 1, p + 1))}
                disabled={!data.hasNextPage}
                className="p-2 rounded-xl bg-card text-foreground disabled:opacity-50 disabled:cursor-not-allowed hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors shadow-sm"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          )}
        </div>
      )}

      {/* Delete Confirmation Modal */}
      <AnimatePresence>
        {commentToDelete && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="bg-card w-full max-w-md rounded-[2rem] p-6 sm:p-8 shadow-2xl relative overflow-hidden"
            >
              <div className="absolute top-0 left-0 w-full h-2 bg-red-500" />
              <div className="w-16 h-16 bg-red-500/10 rounded-full flex items-center justify-center mb-6">
                <AlertCircle className="w-8 h-8 text-red-500" />
              </div>
              
              <h3 className="text-2xl font-black text-foreground mb-3">
                Yorumu Sil
              </h3>
              <p className="text-muted-foreground font-medium mb-8">
                Bu yorumu silmek istediğinize emin misiniz? Bu işlem geri alınamaz.
              </p>
              
              <div className="flex items-center justify-end gap-3">
                <button
                  onClick={() => setCommentToDelete(null)}
                  className="px-5 py-2.5 text-sm font-bold text-muted-foreground hover:text-foreground hover:bg-muted rounded-xl transition-colors"
                >
                  İptal
                </button>
                <button
                  onClick={confirmDelete}
                  disabled={deleteCommentMutation.isPending}
                  className="px-5 py-2.5 text-sm font-bold bg-red-500 text-white hover:bg-red-600 rounded-xl transition-colors disabled:opacity-50 flex items-center gap-2"
                >
                  {deleteCommentMutation.isPending && <Loader2 className="w-4 h-4 animate-spin" />}
                  Sil
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

